  const getUsersByRole = (roles, type) => {
    let searchQuery = `@serviceId:{'${formatForRedis(
      projects?.userServiceId
    )}'}`;
    let userRoles;
    switch (type) {
      case USER_TYPES.Dispatcher:
        userRoles = roles.filter(
          (x: any) =>
            x.permissions.indexOf(PERMISSION_TYPES.Cad) !== -1 &&
            x.permissions.indexOf(PERMISSION_TYPES.Admin) === -1
        );
        break;
      case USER_TYPES.Live:
        userRoles = roles.filter(
          (x: any) =>
            x.permissions.indexOf(PERMISSION_TYPES.Live) !== -1 &&
            x.permissions.indexOf(PERMISSION_TYPES.Admin) === -1
        );
        break;
      case USER_TYPES.Responder:
        userRoles = roles.filter(
          (x: any) =>
            x.permissions.indexOf(PERMISSION_TYPES.OnMove) !== -1 &&
            x.permissions.indexOf(PERMISSION_TYPES.Admin) === -1
        );
        break;
      case USER_TYPES.Manager:
        userRoles = roles.filter(
          (x: any) =>
            x.permissions.indexOf(PERMISSION_TYPES.Cad) !== -1 &&
            x.permissions.indexOf(PERMISSION_TYPES.OnMove) !== -1 &&
            x.permissions.indexOf(PERMISSION_TYPES.Admin) === -1
        );
        break;
    }
    console.log("selected user roles", userRoles);

    const rolesQuery = userRoles.map((y: any) => {
      return `@roleId === '${y._id}'`;
    });
    const userRequest: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
          searchQuery,
          searchOptions: "TIMEOUT 5000",
        },
        list: {
          objectIds: userId ? [userId.toString()] : undefined,
        },
        load: {
          id: "$.objectId",
          status: "$.nonpersistent.static.live.status",
          live: "$.persistent.static.live",
          roleId: "$..admin.profile.roleId",
        },
      },
      apply: {
        expression: "",
        name: "",
      },
      result: {},
      filter: {
        expression: `exists(@roleId) && (${rolesQuery.join("||")})`,
        // expression: "",
      },
      anyStatus: false,
    };
    setLoading(true);
    dispatch(
      GET_AGGREGATE({
        requestData: userRequest,
        callback: (response) => {
          setLoading(false);
          let sourceData = [];
          response?.map((x, i) => {
            sourceData.push({
              driverId: x.id,
              driverName: `${x?.live?.profile?.firstName} ${x?.live?.profile?.lastName}`,
            });
          });
          setDriverDataSource(sourceData);
          getLocation();
        },
      })
    );
  };


  const formatData = (data) => {
    console.log("data", data);
    return data.map((row) => {
      const formattedRow = { ...row };
      Object.keys(row).forEach((key) => {
        if (Array.isArray(row[key])) {
          formattedRow[key] = row[key].map((slot) =>
            slot.map((time) =>
              typeof time === "string" ? time : time.format("YYYY-MM-DD HH:mm")
            )
          );
        }
      });
      return formattedRow;
    });
  };

