import Geocode from "react-geocode";
import { reverseGeocodeAddress } from "utils/placeName";

Geocode.setApiKey("AIzaSyDgNagv_ozKWc6IQ75Ol4cH8fxdntOaW6M");
Geocode.setLanguage("en");
Geocode.setRegion("us");

declare global {
  interface Window {
    webkit: any;
  }
}

declare var JSBridge: any;

export const DEFAULT_FORM_VALUES = {
  dispatch: { type: "dispatchType", value: "immediate" },
  rideType: { type: "rideType", value: "oneWay" },
  fareType: { type: "fareType", value: "variable" },
  payType: { type: "payType", value: "meter" },
  leadTime: 15,
};

// Offsets a coordinate by a fixed distance so the exact pickup point is masked.
export const getMaskedLocation = (latitude, longitude) => {
  const meter = 417;
  const earth = 6378.137; // radius of the earth in kilometer
  const pi = Math.PI;
  const m = 1 / (((2 * pi) / 360) * earth) / 1000; // 1 meter in degree
  return {
    lat: latitude + meter * m,
    long: longitude + (meter * m) / Math.cos(latitude * (pi / 180)),
  };
};

// Notifies the native (iOS/JSBridge) host that a ride was submitted.
export const notifyNativeBridge = (pageId) => {
  const bridgeRequest = { type: "rideDidSubmit", pageId };
  window?.webkit?.messageHandlers?.jsMessageHandler.postMessage(
    JSON.stringify(bridgeRequest)
  );
  try {
    JSBridge?.jsMessageHandler(JSON.stringify(bridgeRequest));
  } catch (e) {
    console.log("js bridge does not exist");
  }
};

// Address for a coordinate (the "use my location" button). Goes through
// placeName rather than results[0].formatted_address: results[0] is a plus code
// ("52CV+RM6, A5, Harare") whenever the point has no street address, and that
// string ends up on the ride request the driver reads.
export const reverseGeocode = async (marker: any) => {
  const address = await reverseGeocodeAddress(marker);
  return address || "Unknown";
};

export const getCurrentLocation = () => {
  return new Promise((resolve, reject) => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition((position) => {
        resolve({
          lat: position?.coords?.latitude,
          long: position?.coords?.longitude,
        });
      });
    } else {
      reject("Geolocation is not supported by this browser.");
    }
  });
};
