const moment = require("moment-timezone");

const { Panel } = Collapse;

interface LocationOption {
  location?: string;
  startTime?: string;
  endTime?: string;
  days?: string[];
  timeWindow?: number | "custom";
  customTimeWindow?: number;
}

interface LocationInputProps {
  value?: LocationOption[];
  keyPrefix?: string;
  onChange?: (locations: LocationOption[]) => void;
}

interface HolidaySelectorProps {
  value?: Moment[];
  onChange?: (dates: Moment[]) => void;
}
const { TabPane } = Tabs;

const EditDriverModal: FC<{
  onClose: () => void;
  socket?: ISocket;
  student?: any;
  adminRoles?: any;
  onAdd?: () => void;
}> = (props) => {
  const { onClose, socket, student, adminRoles, onAdd } = props;
  const [isModalVisible, setIsModalVisible] = useState(true);
  const [registerForm] = Form.useForm();
  const [error, setError] = useState<string>("");
  const [saving, setSaving] = useState(false);
  const { projects } = useSelector((state: RootState) => state.auth);
  const { updateUserRequestPayloadV2 } = useSocketActions();
  const dispatch = useDispatch();

  const handleCancel = () => {
    setIsModalVisible(false);
    onClose && onClose();
  };

  useEffect(() => {
    if (student?.scheduleId) {
      const {schoolLocation} = student?.data;
      registerForm.setFieldsValue({
        ...student?.data,
        schoolLocation: {
          label: schoolLocation?.attributes?.address,
          value: {
            description: schoolLocation?.attributes?.address,
            place_id: "",
            coordinates: schoolLocation?.coordinates,
            attributes: schoolLocation?.attributes,
          },
        },
        holidays: Object.values(student?.data?.holidays || {})?.map(
          (holiday: any) => {
            return moment(holiday?.timestamp);
          }
        ),
        driver: student?.data?.driverId
          ? {
              type: "responder",
              id: student?.data?.driverId,
              name: student?.data?.driverName,
              beamId: student?.data?.driverName,
              valueName: student?.data?.driverName,
            }
          : undefined,
        vehicle: {
          type: "vehicle",
          value: student?.data?.vehicleId,
          valueName: student?.data?.vehicleName,
          obj: {
            id: student?.data?.vehicleId,
            name: student?.data?.vehicleName,
            noOfPassengers: student?.data?.vehicleCapacity,
          },
        },
        project: student?.data?.projectId,
        time: student?.data?.scheduleTime,
        students: Object.values(student?.data?.students || {})?.map(
          (x: any) => {
            return { id: x?.userId, beamId: x?.beamId };
          }
        ),
      });
    }
  }, []);

  const onSubmitHandler = async (values: any) => {
    console.log("values", values);
    
    const {
      name,
      daysOfTheWeek,
      scheduleType,
      time,
      project,
      vehicle,
      students,
      driver,
      holidays,
      schoolLocation,
      schoolTime,
    } = values;

    setError("");
    
    if(parseInt(vehicle?.obj?.noOfPassengers) < students?.length){
      setError(`Students should not exceed maximum vehicle capacity: ${vehicle?.obj?.noOfPassengers}`);
      return;
    }

    const requestData = {
      name,
      driverId: driver?.id,
      driverName: driver?.beamId,
      projectId: project,
      daysOfTheWeek,
      scheduleTime: time,
      scheduleType,
      vehicleId: vehicle?.value,
      vehicleName: vehicle?.obj.name,
      vehicleCapacity: vehicle?.obj.noOfPassengers,
      schoolLocation: {
        coordinates: schoolLocation?.value?.coordinates,
        attributes: schoolLocation?.value?.attributes,
      },
      schoolTime,
      holidays: holidays?.reduce((acc, item, index) => {
        const timestamp = item.toDate().getTime();
        acc[timestamp] = {
          timestamp,
          type: "emergency",
        };
        return acc;
      }, {} as { [key: string]: any }),
      students: students
        ?.map((x) => {
          return { userId: x?.id, beamId: x?.beamId };
        })
        ?.reduce((acc, item, index) => {
          acc[item.userId] = {
            ...item,
          };
          return acc;
        }, {} as { [key: string]: any }),
      timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
      cudbServiceId: projects?.userServiceId,
    };
    // const notifyDate = new Date(time);
    const originalTime = moment.tz(
      time,
      "MM/DD/YYYY HH:mm",
      Intl.DateTimeFormat().resolvedOptions().timeZone
    );
    const convertedTime = originalTime.utc().format("MM/DD/YYYY HH:mm");
    const notifyDate = new Date(convertedTime);

    // const cron = dateToCron(notifyDate, daysOfTheWeek);
    const cron = `${notifyDate.getMinutes()} ${notifyDate.getHours()} * 0-11 *`;
    if (!student?.scheduleId) {
      const createRequest = {
        cron,
        topic: `${process.env.REACT_APP_ECO_SYSTEM}/service/scheduler-service/service/dps/createSchoolBusPage`,
        data: requestData,
        info: {},
        to: 4920566400000,
      };
      console.log("request", createRequest);
      setSaving(true);
      const response: any = await createSchedule(createRequest);
      const objectId = response?.data?.id?.toString();
      const updateRequest = {
        objectId,
        changes: [
          {
            op: "replace",
            path: "/partitions",
            value: [`org:${projects?.userServiceId}`],
          },
        ],
      };
      await updateSchedule(updateRequest);
      pushNotification(
        "Schedule created successfully",
        "success",
        "TOP_CENTER",
        3000
      );
    } else {
      setSaving(true);
      const objectId = student?.scheduleId?.toString();
      const updateRequest = {
        objectId,
        changes: [
          {
            op: "replace",
            path: "/cron",
            value: cron,
          },
          {
            op: "replace",
            path: "/data",
            value: requestData,
          },
        ],
      };
      await updateSchedule(updateRequest);
      pushNotification(
        "Schedule updated successfully",
        "success",
        "TOP_CENTER",
        3000
      );
    }
    setSaving(false);
    onAdd();
  };

  const createSchedule = async (requestData) => {
    return new Promise((resolve, reject) => {
      dispatch(
        CREATE_SCHEDULE({
          request: requestData,
          callback: (response) => {
            console.log("create response ehere", response);
            resolve(response);
          },
        })
      );
    });
  };

  const updateSchedule = async (requestData) => {
    return new Promise((resolve, reject) => {
      dispatch(
        UPDATE_SCHEDULE({
          request: requestData,
          callback: (response) => {
            console.log("create response ehere", response);
            resolve(response);
          },
        })
      );
    });
  };

  const daysOfWeek = [
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday",
    "Sunday",
  ];

  const HolidaySelector: React.FC<HolidaySelectorProps> = ({
    value = [],
    onChange,
  }) => {
    const handleTagClose = (date: Moment) => {
      const updatedDates = value?.filter((d) => !d.isSame(date, "day"));
      onChange?.(updatedDates);
    };
    const handleAddDate = (date: Moment | null) => {
      if (date && !value?.find((d) => d.isSame(date, "day"))) {
        const updatedDates = [...value, date];
        onChange?.(updatedDates);
      }
    };
    return (
      <div>
        <DatePicker
          onChange={handleAddDate}
          disabledDate={(date) =>
            value?.some((selectedDate) => selectedDate?.isSame(date, "day"))
          }
          placeholder="Select date"
        />
        <div style={{ marginTop: "16px" }} className="custom-tag">
          {value?.map((date) => (
            <Tag
              key={date.toISOString()}
              className="tag-item"
              closable
              onClose={() => handleTagClose(date)}
              closeIcon={<CloseCircleOutlined />}
            >
              {date.format("YYYY-MM-DD")}
            </Tag>
          ))}
        </div>
      </div>
    );
  };

  const ScheduleInformationInput: React.FC<any> = ({ value, onChange }) => {
    const ScheduleTimeInput = (props) => {
      const { value, onChange } = props;
      return (
        <TimeInput
          placeholder={`Select Time`}
          value={value ? moment(value).format("HH:mm") : undefined}
          onChange={onChange}
        />
      );
    };

    return (
      <React.Fragment>
        <Form.Item
          label="Schedule Name"
          name="name"
          rules={[
            { required: true, message: "Please input the schedule name" },
          ]}
        >
          <Input placeholder="Enter name" />
        </Form.Item>

        <Form.Item
          className="mt-3"
          label="Schedule Type"
          name="scheduleType"
          rules={[
            { required: true, message: "Please select Pickup or Dropoff" },
          ]}
        >
          <Radio.Group>
            <Radio value="pickup">Pickup</Radio>
            <Radio value="dropoff">Dropoff</Radio>
          </Radio.Group>
        </Form.Item>

        <Form.Item
          className="mt-3"
          label={`Schedule Days`}
          name={`daysOfTheWeek`}
          rules={[{ required: true, message: "Days selection is required" }]}
        >
          <Select
            placeholder={`Select Days`}
            mode="multiple"
            style={{ width: "100%" }}
          >
            {daysOfWeek.map((day) => (
              <Select.Option key={day} value={day}>
                {day}
              </Select.Option>
            ))}
          </Select>
        </Form.Item>

        <Form.Item
          className="mt-3"
          label={`Schedule Time`}
          name={`time`}
          rules={[{ required: true, message: "Time is required" }]}
        >
          <ScheduleTimeInput onChange={(time) => {}} />
        </Form.Item>

        <Form.Item label={`Holidays`} name={`holidays`} className="mt-3">
          <HolidaySelector />
        </Form.Item>

        <Form.Item
          label={`School Location`}
          name={`schoolLocation`}
          // className="mt-3"
          rules={[{ required: true, message: "School location is required" }]}
        >
          <LocationInput
            placeholder={`Enter Location`}
            onChange={(location) => {}}
          />

</Form.Item>

<Form.Item
          className="mt-3 mb-3"
          label={`School Time`}
          name={`schoolTime`}
          rules={[{ required: true, message: "Time is required" }]}
        >
          <ScheduleTimeInput onChange={(time) => {}} />
        </Form.Item>

        
      </React.Fragment>
    );
  };

  return (
    <Modal
      title={
        student?.scheduleId ? `Edit (${student?.data?.name})` : "Add schedule"
      }
      visible={isModalVisible}
      onCancel={handleCancel}
      width="800px"
      className="beam-modal"
      // width="100%"
      // className="beam-modal analytics-summary-modal"
      footer={[]}
      destroyOnClose={true}
    >
      <Form
        className="auth-form"
        name="register-form"
        id="register-form"
        layout="vertical"
        form={registerForm}
        onFinish={onSubmitHandler}
        requiredMark={false}
      >
        <div className="main-cards mt-3">
          {/* <Collapse
            activeKey={["vehicle", "driver", "preferences"]}
            bordered={false}
            className="simple-collapse d-flex flex-column"
          >
            <Panel
              header={
                <div className="d-flex">
                  <h5 className="m-2">Vehicle Information</h5>
                </div>
              }
              key={"vehicle"}
            >
              <Form.Item name="vehicle">
                <VehicleInformationInput />
              </Form.Item>
            </Panel>

            <Panel
              header={
                <div className="d-flex">
                  <h5 className="m-2">Driver Assignment</h5>
                </div>
              }
              key={"driver"}
            >
              <Form.Item name="responder">
                <ResponderInput
                  placeholder="Assign driver"
                  adminRoles={adminRoles}
                />
              </Form.Item>
            </Panel>

            <Panel
              header={
                <div className="d-flex">
                  <h5 className="m-2">Preferences</h5>
                </div>
              }
              key={"preferences"}
            >
              <Form.Item name="preferences">
                <AdditionalConstraints />
              </Form.Item>
            </Panel>
          </Collapse> */}

          <Form.Item name="schedule">
            <ScheduleInformationInput />
          </Form.Item>

          <Form.Item name="project" label="Route Project" className="mt-3">
            <ProjectInput
              placeholder="Select project"
              onProjectChange={() => {}}
            />
          </Form.Item>

          <Form.Item name="driver" label="Driver" className="mt-3">
            <ResponderInput
              placeholder="Select driver"
              adminRoles={adminRoles}
            />
          </Form.Item>

          <Form.Item name="vehicle" label="Vehicle" className="mt-3">
            <VehicleInput
              placeholder="Select vehicle"
              socket={socket}
              vehicleId={true}
              onChange={(vehicle)=>{
                console.log('vehicle here', vehicle);
              }}
            />
          </Form.Item>

          <Form.Item name="students" label="Students" className="mt-3">
            <StudentInput
              placeholder="Select students"
              adminRoles={adminRoles}
              multiple={true}
            />
          </Form.Item>
        </div>
        
        {error && (
                    <Form.Item>
                      <p className="error">{error}</p>
                    </Form.Item>
                  )}

        <Row className="action-grp mt-3">
          <Col span={24}>
            <Form.Item>
              <Button
                className="beam-btn green-btn cover w-full"
                loading={saving}
                type="primary"
                htmlType="submit"
                onClick={() => setError("")}
              >
                Save
              </Button>
            </Form.Item>
          </Col>
        </Row>
      </Form>
    </Modal>
  );
};

export default EditDriverModal;
