import React, { FC, useEffect, useRef, useState } from "react";
import { Button, Row, Col, Table, Input, Skeleton, Tooltip, Menu, Dropdown } from "antd";

import _ from "lodash";
import { ReactSVG } from "react-svg";
import moment from "moment";
import {
  SearchOutlined,
  ArrowLeftOutlined,
  EditOutlined,
} from "@ant-design/icons";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";
import {
  getAdminRolesTopic,
  getProjectsSubscriptionTopic,
  getProjectsRequestPublishTopic,
} from "hooks/MQTTConstants";
import { SocketTopics, UserTopics } from "constants/enums";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { useDispatch } from "react-redux";
import useSocketActions from "../../../../../hooks/socketActions";
import { formatForRedis } from "utils/appUtil";
import { USER_TYPES, PERMISSION_TYPES } from "utils/PageTypes";
import { GET_AGGREGATE } from "../../../../../reducers/reducer";
import EditVehicleModal from "./EditVehicleModal";
import Loader from "react-loader-spinner";
import "../Dashboard.scss";
import { ExtendedBioTopics } from "constants/enums";

let timeout;
const VehicleModal: FC<{
  socket: ISocket;
  params?: any;
  componentUuid?: string;
}> = ({ socket, params, componentUuid }) => {
  const { selectedPage, encrypted_token, projects, adminUserRoles } = useSelector(
    (state: RootState) => state.auth
  );
  const dispatch = useDispatch();
  const [tableDataSource, setTableDataSource] = useState<any>([]);
  const [tableColumns, setTableColumns] = useState<any>([]);
  useState<boolean>(false);
  const [loading, setLoading] = useState<boolean>(false);
  useState<boolean>(false);
  const { getUserRequestPayload } = useSocketActions();
  // const adminRoles = useRef<any>(undefined);
  // const projects = useRef<any>(undefined);
  const drivers = useRef<any>();
  const [isEditModalVisible, setIsEditModalVisible] = useState<any>(undefined);
  const isMounted = useRef(true);
  const { updateUserRequestPayloadV2 } = useSocketActions();


  const statusOptions = [
    { label: "Unavailable", color: "red" },
    { label: "Available", color: "green" },
  ];

  const statusColorMapping: { [key: string]: string } = {
    green: "#40CC52",
    amber: "#FBAE16",
    red: "#FF5F25",
    blue: "#508AFA",
    purple: "#463BBD",
    gray: "#91A5C6",
    black: "#000000",
    brown: "#964B00",
    aqua: "#00FFFF",
    orange: "#FF8C00",
  };

  const formatMaintenanceMessage = (maintenance: any, vehicleName: string) => {
    if (!maintenance) return "";

    const {
      dropoffDateTime,
      location,
      typeOfWork,
      additionalInformation,
      driverDropoff,
      driverPickup,
    } = maintenance;

    if (!dropoffDateTime) return "";

    const dropoffMoment = moment(dropoffDateTime, "MM/DD/YYYY HH:mm:ss");
    const altMoment = dropoffMoment.isValid() ? dropoffMoment : moment(dropoffDateTime);
    
    if (!altMoment.isValid()) return "";

    const time = altMoment.format("hh:mm A");
    const date = altMoment.format("MMM-DD");

    const parts = [
      `${time} - ${date}`,
      `Vehicle Maintenance for ${vehicleName || "Vehicle"}`,
      location ? `at ${location.label}` : "",
      typeOfWork ? `for ${typeOfWork}` : "",
    ].filter(Boolean);

    let message = parts.join(" ");

    if (additionalInformation) {
      message += `. ${additionalInformation}`;
    }

    if (driverDropoff?.beamId) {
      message += `. Dropoff Driver - ${driverDropoff.beamId}`;
    }

    if (driverPickup?.beamId) {
      message += `. Pickup Driver - ${driverPickup.beamId}`;
    }

    return message;
  };


  const getVehicles = (filterText = undefined) => {
    let searchQuery = `@userType:{asset}@serviceId:{'${formatForRedis(
      projects?.userServiceId
    )}'}`;
    const userRequest: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
          searchQuery,
          searchOptions: "TIMEOUT 5000",
        },
        load: {
          id: "$.objectId",
          static: "$.persistent.static.asset",
          type: "$.persistent.static.asset.type",
          name: "$.persistent.static.asset.name",
          status: "$.nonpersistent.static.live.status.name",
          licensePlate: "$.persistent.static.asset.licensePlate",
          makeAndModel: "$.persistent.static.asset.makeAndModel",
          vin: "$.persistent.static.asset.vin",
          permit: "$.persistent.static.asset.permit",
          maintenance: "$.persistent.static.asset.maintenance",
        },
      },
      apply: {
        expression: "",
        name: "",
      },
      result: {},
      filter: {
        expression:
          `exists(@type) && @type=='vehicle' && exists(@name)` +
          `${filterText && filterText !== ""
            ? ` && (contains(lower(@name), '${filterText.toLowerCase()}') || contains(lower(@licensePlate), '${filterText.toLowerCase()}') || contains(lower(@makeAndModel), '${filterText.toLowerCase()}') || contains(lower(@vin), '${filterText.toLowerCase()}') || contains(lower(@permit), '${filterText.toLowerCase()}'))`
            : ""
          }`,
      },
      anyStatus: false,
    };
    setLoading(true);
    dispatch(
      GET_AGGREGATE({
        requestData: userRequest,
        callback: (response) => {
          setLoading(false);
          console.log("respons ehere", response);
          let sourceData = [];
          let columns: any = [
            {
              title: "Status",
              key: "userStatus",
              dataIndex: "userStatus",
              render: (status: string, record) => {
                const menu = (
                  <Menu
                    onClick={({ key }) => {
                      handleStatusChange(record.key, key, projects?.userServiceId);
                    }}
                    items={statusOptions.map((status) => ({
                      label: status.label,
                      key: status.label,
                    }))}
                  />
                );

                return !record.isShift ? (
                  <Dropdown overlay={menu} trigger={["click"]}>
                    <Tooltip overlay={statusOptions.find((opt) => opt.color === status)?.label}>

                      <Button className="beam-btn icon-btn ml-2">
                        <ReactSVG
                          src="/images/flag-icon.svg"
                          className={`${status ?? "gray"}-icon`}
                        />
                      </Button>
                    </Tooltip>
                  </Dropdown>
                ) : (
                  <div />
                );
              },
            },
            {
              title: "Name",
              key: "name",
              dataIndex: "name",
              sorter: (a, b) => a.name?.localeCompare(b?.name),
            },
            // {
            //   title: "Vehicle type",
            //   key: "vehicleType",
            //   dataIndex: "vehicleType",
            // },
            {
              title: "License plate number",
              key: "licensePlate",
              dataIndex: "licensePlate",
            },
            {
              title: "Make & Model",
              key: "makeAndModel",
              dataIndex: "makeAndModel",
            },
            {
              title: "Year",
              key: "year",
              dataIndex: "year",
            },
            {
              title: "VIN",
              key: "vin",
              dataIndex: "vin",
            },
            {
              title: "Permit #",
              key: "permit",
              dataIndex: "permit",
            },
            {
              title: "Maintenance",
              key: "maintenance",
              dataIndex: "maintenance",
              width: 400,
              render: (maintenance: any, record: any) => {
                if (!maintenance) return "";
                const message = formatMaintenanceMessage(maintenance, record.name);
                return (
                  <div style={{ whiteSpace: "pre-wrap" }}>{message}</div>
                );
              },
            },
            {
              title: "Action",
              key: "action",
              dataIndex: "action",
              render: (action: any) => (
                <Row style={{ width: 135 }}>
                  <Col span={8}>
                    <Button
                      style={{ boxShadow: "none" }}
                      className="beam-btn icon-btn yellow-btn cover"
                      onClick={() => {
                        console.log("action", action);
                        setIsEditModalVisible(action.user);
                      }}
                    >
                      <EditOutlined />
                    </Button>
                  </Col>
                </Row>
              ),
            },
          ];
          response?.map((x, i) => {
            sourceData.push({
              key: x.id.toString(),
              name: x?.static?.name,
              licensePlate: x?.static?.licensePlate,
              makeAndModel: x?.static?.makeAndModel,
              year: x?.static?.year,
              vin: x?.static?.vin,
              permit: x?.static?.permit,
              userStatus: x?.status,
              maintenance: x?.maintenance,
              action: {
                userId: x?.id,
                user: x,
              },
            });
          });
          drivers.current = sourceData;
          setTableColumns(columns);
          // setTableDataSource(sourceData);
          setTableDataSource(
            sourceData.sort((a, b) =>
              (a.name || "").localeCompare(b.name || "")
            )
          );
        },
      })
    );
  };

  useEffect(() => {
    document.title = "Vehicle | Beam";
    isMounted.current = true;
    return () => {
      isMounted.current = false;
    };
  }, []);


  useEffect(() => {
    if (projects?.adminUserId) {
      getVehicles();
    }
  }, [projects])

  const loadingColumns = [
    {
      title: "...",
      dataIndex: "loading",
      key: "loading",
      render: () => (
        <Skeleton
          active
          title={false} // Disable the title if you only want paragraph lines
          paragraph={{
            rows: 7,
            width: "100%",
          }}
        />
      ),
    },
  ];



  const handleStatusChange = (userId, status, serviceId) => {
    const color =
      statusOptions.find((opt) => opt.label === status)?.color || "gray";
    const changes = [
      {
        op: "replace",
        path: `/nonpersistent/static/live/status`,
        value: {
          name: color,
          color: statusColorMapping[color],
        },
      },
    ];
    
    // Update local table data immediately
    setTableDataSource((prevData) =>
      prevData.map((record) =>
        record.key === userId.toString()
          ? { ...record, userStatus: color }
          : record
      )
    );
    
    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.UpdateUser,
      updateUserRequestPayloadV2(userId, changes),
      ExtendedBioTopics.UpdateUserBio,
      serviceId
    );
  };


  // Placeholder loading data to fill the rows
  const loadingData = Array(1)
    .fill({})
    .map((_, index) => ({ key: `loading-${index}` }));

  return (
    <React.Fragment>
      <Row>
        <Col span={24} className="d-flex justify-content-space-between align-items-space-between">
          <div>
            <h2 style={{ marginBottom: 0 }}>Vehicle</h2>
            <p>Home &gt; Vehicle</p>
          </div>

          <Input
            onChange={(e) => {
              let value: string = e.target.value;
              if (timeout) clearTimeout(timeout);
              timeout = setTimeout(() => {
                if (value.includes("-")) value = formatForRedis(value);
                getVehicles(value);
              }, 500);
            }}
            style={{ width: 350 }}
            placeholder={`Search vehicle`}
            suffix={
              // loading ? (
              //   <Loader type="TailSpin" color="#000" height={15} width={15} />
              // ) : (
              //   <SearchOutlined />
              // )
              <SearchOutlined />
            }
          />
        </Col>
      </Row>

      <Row
        gutter={20}
        className="scrollable-table mt-3"
        style={{ display: "grid", marginRight: -20 }}
      >
        <Col
          xs={24}
          sm={24}
          md={24}
          style={{ maxHeight: '100vh', overflow: "scroll" }}
        >
          <Table
            dataSource={loading ? loadingData : tableDataSource}
            columns={loading ? loadingColumns : tableColumns}
            pagination={false}
            // className={tableDataSource?.length > 0 ? "" : "table-empty"}
            onRow={(record) => {
              return {
                onDoubleClick: () => {
                  console.log("on double click row", record);
                },
                onClick: () => { },
              };
            }}
            scroll={{ x: true, y: '100vh' }}
            onChange={(e) => { }}
            rowClassName={(record, index) => {
              if (record?.key === selectedPage?.page?.pageId)
                return "row-selected";
              return "";
            }}
          />
        </Col>
      </Row>
      {isEditModalVisible !== undefined && (
        <EditVehicleModal
          socket={socket}
          student={isEditModalVisible}
          onClose={() => {
            setIsEditModalVisible(undefined);
          }}
          adminRoles={adminUserRoles}
          onAdd={() => {
            getVehicles();
          }}
        />
      )}
    </React.Fragment>
  );
};

export default VehicleModal;
