import React, { FC, useState } from "react";
import { Modal, Rate, Input, Button } from "antd";
import { CheckCircleTwoTone } from "@ant-design/icons";

import "./RatingModal.scss";

const RatingModal: FC<{ onClose: () => void, onSubmit: any }> = ({ onClose, onSubmit }) => {
  const [isModalVisible, setIsModalVisible] = useState(true);
  const [rating, setRating] = useState<number | null>(null);
  const [review, setReview] = useState<string>("");
  const [submitted, setSubmitted] = useState(false);

  const handleCancel = () => {
    setIsModalVisible(false);
    onClose();
  };

  const handleSubmit = () => {
    onSubmit({rating, review});
    setSubmitted(true); // Show the green tick
  };

  const desc = ['terrible', 'bad', 'normal', 'good', 'wonderful'];

  return (
    <Modal
      title="Ratings and Review"
      visible={isModalVisible}
      onCancel={handleCancel}
      className="beam-modal"
      width="400px"
      footer={null}
      destroyOnClose={true}
    >
      {!submitted ? (
        <div>
          <div style={{ marginBottom: "16px", textAlign: "center", background: "#e1e4ea" }}>
            <Rate tooltips={desc} style={{fontSize: 35}}  allowHalf onChange={(value) => setRating(value)} value={rating} />
          </div>
          <div style={{ marginBottom: "16px" }}>
            <h5>Your review:</h5>
            <Input.TextArea
               autoSize={{ minRows: 4, maxRows: 6 }}
              placeholder="Write your review here..."
              onChange={(e) => setReview(e.target.value)}
              value={review}
            />
          </div>
          <div >
            <Button
              className="beam-btn green-btn cover w-full"
              type="primary"
              onClick={handleSubmit}
              disabled={!rating && !review.trim()} // Button is disabled unless rating or review is provided
            >
              Submit
            </Button>
          </div>
        </div>
      ) : (
        <div style={{ textAlign: "center", padding: "40px 0" }}>
          <CheckCircleTwoTone twoToneColor="#52c41a" style={{ fontSize: "64px" }} />
          <h2 style={{ marginTop: "16px" }}>Thank you for your feedback!</h2>
        </div>
      )}
    </Modal>
  );
};

export default RatingModal;
