import React, { FC, useState, useEffect } from "react";
import { Button, Modal, Upload, Progress, Alert } from "antd";
import { InboxOutlined } from "@ant-design/icons";
import type { RcFile } from "rc-upload/lib/interface";
import * as XLSX from "xlsx";
import { mapHulprRowToBeamValues, normalizeRowKeys } from "./hulprToBeamMapping";
import { SocketTopics } from "constants/enums";
import { getCreateEventPageBulkPublishTopic, getCreateEventPageBulkSubscriptionTopic } from "hooks/MQTTConstants";
import { wrapRequestPayload } from "../../../../helpers/request/RequestPayload";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { pushNotification } from "utils/notifications";
const { Dragger } = Upload;

export type BuildContext = {
  userId: string;
  connectionId: string;
  accounts: any[];
  projects: any;
  pageId: any;
  selectedPage: any;
  getPagesByUuid: (uuid: string) => Promise<any>;
};

const UploadCSVModal: FC<{
  onClose?: () => void;
  accounts?: any[];
  socket: ISocket;
  buildEventRequestsFromValues: (
    values: any,
    context: BuildContext
  ) => Promise<{ eventRequests: any[]; deletedPageIds: string[] }>;
  publishEventRequests: (eventRequests: any[]) => any;
  getBuildContext: (overrides?: { pageId?: any; selectedPage?: any }) => BuildContext;
}> = ({
  onClose,
  accounts = [],
  buildEventRequestsFromValues,
  publishEventRequests,
  getBuildContext,
  socket,
}) => {
  const [visible, setVisible] = useState(true);
  const [file, setFile] = useState<RcFile | null>(null);
  const [parsedRows, setParsedRows] = useState<Record<string, unknown>[]>([]);
  const [processing, setProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [result, setResult] = useState<{ success: number; errors: string[] } | null>(null);
  const { encrypted_token } = useSelector((state: RootState) => state.auth);
  const handleCancel = () => {
    setVisible(false);
    onClose?.();
  };

  const parseFile = (file: RcFile): Promise<Record<string, unknown>[]> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      const ext = (file.name || "").toLowerCase();
      const isCsv = ext.endsWith(".csv");

      reader.onload = (e) => {
        try {
          const data = e.target?.result;
          if (!data) {
            reject(new Error("No data read"));
            return;
          }
          const wb = XLSX.read(data, {
            type: isCsv ? "binary" : "array",
            cellDates: true,
          });
          const firstSheet = wb.SheetNames[0];
          if (!firstSheet) {
            reject(new Error("No sheet found"));
            return;
          }
          const sheet = wb.Sheets[firstSheet];
          const rows = XLSX.utils.sheet_to_json<Record<string, unknown>>(sheet, {
            defval: "",
            raw: false,
          });
          if (!rows.length) {
            reject(new Error("No rows in file"));
            return;
          }
          const normalized = rows.map((row) => normalizeRowKeys(row));
          resolve(normalized);
        } catch (err) {
          reject(err);
        }
      };
      reader.onerror = () => reject(new Error("Failed to read file"));
      if (isCsv) {
        reader.readAsBinaryString(file);
      } else {
        reader.readAsArrayBuffer(file);
      }
    });
  };

  useEffect(() => {
    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      getCreateEventPageBulkSubscriptionTopic(encrypted_token?.connectionId),
      (response) => {
        console.log("response", response);
        setProcessing(false);
        pushNotification("Bulk events request processed successfully", "success", "TOP_CENTER", 1000);
        handleCancel();
      }
    );
  }, []);

  const handleFileSelect = (file: RcFile) => {
    setFile(file);
    setResult(null);
    parseFile(file)
      .then((rows) => {
        setParsedRows(rows);
      })
      .catch((err) => {
        setParsedRows([]);
        setResult({ success: 0, errors: [err?.message || "Failed to parse file"] });
      });
    return false;
  };

  const handleProcess = async () => {
    if (!file || !parsedRows.length) return;
    setProcessing(true);
    setResult(null);
    setProgress(0);
    const bulkContext = getBuildContext({ pageId: null, selectedPage: null });
    const allEventRequests: any[] = [];
    const errors: string[] = [];
    const total = parsedRows.length;

    for (let i = 0; i < parsedRows.length; i++) {
      setProgress(Math.round(((i + 1) / total) * 100));
      const row = parsedRows[i];
      try {
        const values = mapHulprRowToBeamValues(row, accounts);
        const pickupAddr = (values.pickupLocation as any)?.attributes?.address || values.pickupAddress;
        const dropoffAddr = (values.dropoffLocation as any)?.attributes?.address || values.dropoffAddress;
        if (!pickupAddr || String(pickupAddr).trim() === "") {
          errors.push(`Row ${i + 2}: Missing pickup address`);
          continue;
        }
        if (!dropoffAddr || String(dropoffAddr).trim() === "") {
          errors.push(`Row ${i + 2}: Missing drop-off address`);
          continue;
        }
        const { eventRequests } = await buildEventRequestsFromValues(values, bulkContext);
        allEventRequests.push(...eventRequests);
      } catch (err: any) {
        errors.push(`Row ${i + 2}: ${err?.message || String(err)}`);
      }
    }

    if (allEventRequests.length > 0) {
      const processedEventRequests = publishEventRequests(allEventRequests);
      console.log("processedEventRequests", processedEventRequests);
      if (processedEventRequests.length > 0) {
        console.log("publishing bulk event requests", getCreateEventPageBulkPublishTopic(encrypted_token?.connectionId));
        socket.publishToEvent(
          SocketTopics.PublishPageTopics,
          getCreateEventPageBulkPublishTopic(encrypted_token?.connectionId),
          wrapRequestPayload({events: processedEventRequests})
        );
      }
      // console.log("allEventRequests", allEventRequests);
    }

    setResult({
      success: allEventRequests.length,
      errors,
    });
    // setProcessing(false);
    // setProgress(100);
  };

  return (
    <Modal
      title="Bulk upload (CSV / XLS)"
      visible={visible}
      onCancel={handleCancel}
      width={560}
      // className="beam-modal"
      footer={[
        <Button key="cancel" onClick={handleCancel}>
          Cancel
        </Button>,
        <Button
          key="process"
          type="primary"
          disabled={!file || parsedRows.length === 0 || processing}
          onClick={handleProcess}
        >
          {processing ? "Processing…" : "Process & submit"}
        </Button>,
      ]}
      destroyOnClose
    >
      <Dragger
        name="file"
        multiple={false}
        accept=".csv,.xls,.xlsx"
        beforeUpload={handleFileSelect}
        showUploadList={true}
        fileList={file ? [{ uid: "1", name: file.name, size: file.size }] : []}
        onRemove={() => {
          setFile(null);
          setParsedRows([]);
          setResult(null);
        }}
      >
        <p className="ant-upload-drag-icon">
          <InboxOutlined />
        </p>
        <p className="ant-upload-text">Click or drag CSV / XLS / XLSX here</p>
        <p className="ant-upload-hint">
          Use Hulpr column headers. First row should be column names.
        </p>
      </Dragger>

      {parsedRows.length > 0 && (
        <p style={{ marginTop: 12, marginBottom: 0 }}>
          {parsedRows.length} row(s) loaded.
        </p>
      )}

      {/* {processing && (
        <Progress percent={progress} status="active" style={{ marginTop: 16 }} />
      )} */}

      {result && (
        <Alert
          style={{ marginTop: 16 }}
          type={result.errors.length > 0 ? "warning" : "success"}
          message={
            result.success > 0
              ? `${result.success} event request(s) submitted.`
              : "No requests submitted."
          }
          description={
            result.errors.length > 0 ? (
              <ul style={{ marginBottom: 0, paddingLeft: 20 }}>
                {result.errors.slice(0, 10).map((e, i) => (
                  <li key={i}>{e}</li>
                ))}
                {result.errors.length > 10 && (
                  <li>… and {result.errors.length - 10} more</li>
                )}
              </ul>
            ) : null
          }
        />
      )}
    </Modal>
  );
};

export default UploadCSVModal;
