type SessionState = {
  startTime: moment.Moment;
  endTime?: moment.Moment;
  breakTimeInSeconds: number;
  pauseTime: moment.Moment | null;
};

function getActiveSessionIndex(sessions: SessionState[]): number {
  if (!sessions.length) return -1;
  const last = sessions.length - 1;
  return sessions[last].endTime ? -1 : last;
}

function workedSecondsForSegment(
  seg: SessionState,
  endOrNow: moment.Moment
): number {
  const gross = endOrNow.diff(seg.startTime, "seconds");
  return Math.max(0, gross - (seg.breakTimeInSeconds || 0));
}

function workedSecondsFromCompletedSessions(sessions: SessionState[]): number {
  let total = 0;
  for (const seg of sessions) {
    if (!seg.endTime) continue;
    total += workedSecondsForSegment(seg, seg.endTime);
  }
  return total;
}

function deserializeSessions(saved: any): SessionState[] {
  if (saved?.sessions?.length) {
    return saved.sessions.map((s: any) => ({
      startTime: moment(s.startTime),
      endTime: s.endTime ? moment(s.endTime) : undefined,
      breakTimeInSeconds: s.breakTimeInSeconds || 0,
      pauseTime: s.pauseTime ? moment(s.pauseTime) : null,
    }));
  }
  if (saved?.startTime) {
    return [
      {
        startTime: moment(saved.startTime),
        endTime: saved.endTime ? moment(saved.endTime) : undefined,
        breakTimeInSeconds: saved.breakTimeInSeconds || 0,
        pauseTime: saved.pauseTime ? moment(saved.pauseTime) : null,
      },
    ];
  }
  return [];
}

function computeActiveElapsedSeconds(
  active: SessionState,
  now: moment.Moment
): number {
  const totalPaused = active.breakTimeInSeconds || 0;
  if (active.pauseTime) {
    return (
      active.pauseTime.diff(active.startTime, "seconds") - totalPaused
    );
  }
  return now.diff(active.startTime, "seconds") - totalPaused;
}

// const API_BASE_URL = "https://example.com/api/timetracker"; // Replace with your API endpoint

const CustomCard = (props) => {
  const { socket, userId } = props;
  const [sessions, setSessions] = useState<SessionState[]>([]);
  const [isClockedIn, setIsClockedIn] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [pauseTime, setPauseTime] = useState<moment.Moment | null>(null);
  const [elapsedTime, setElapsedTime] = useState<number>(0); // active segment worked seconds
  const [breakTime, setBreakTime] = useState<number>(0);
  const [editModalVisible, setEditModalVisible] = useState(false);
  const [form] = Form.useForm();
  const { encrypted_token } = useSelector((state: RootState) => state.auth);
  const [selectedCustomId, setSelectedCustomId] = useState(undefined);
  const dispatch = useDispatch();

  const getTimeSheet = (date) => {
    const customerRequest: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:custom:id`,
          // searchIndex: "beamdev:custom:id",
          searchQuery: `@partitions:{'org\\:${formatForRedis(
            encrypted_token?.cudbServiceId || encrypted_token?.serviceId
          )}'}@partitions:{user\\:${
            userId
          }}@partitions:{type\\:timesheet}@partitions:{date\\:${date}}`,
          searchOptions: "VERBATIM TIMEOUT 10000",
        },
        load: {
          info: "$.info",
          objectId: "$.objectId",
        },
      },
      filter: {
        expression: "",
      },
    };
    dispatch(
      GET_AGGREGATE({
        requestData: customerRequest,
        callback: (response) => {
          setSelectedCustomId(response?.[0]?.objectId);
          const savedState = response?.[0]?.info;
          const loaded = deserializeSessions(savedState);
          if (!loaded.length) {
            setSessions([]);
            setIsClockedIn(false);
            setIsPaused(false);
            setPauseTime(null);
            setBreakTime(0);
            setElapsedTime(0);
            return;
          }

          setSessions(loaded);
          const activeIdx = getActiveSessionIndex(loaded);
          const clockedIn = activeIdx >= 0;
          setIsClockedIn(clockedIn);

          if (clockedIn) {
            const active = loaded[activeIdx];
            const now = moment();
            const pt = active.pauseTime;
            setPauseTime(pt);
            setIsPaused(!!pt);
            setBreakTime(active.breakTimeInSeconds || 0);
            setElapsedTime(computeActiveElapsedSeconds(active, now));
          } else {
            setPauseTime(null);
            setIsPaused(false);
            setBreakTime(0);
            setElapsedTime(0);
          }
        },
      })
    );
  };

  useEffect(() => {
    // const savedState = JSON.parse(localStorage.getItem("clockIn"));

    // if (savedState && savedState.startTime) {
    //   const now = moment(); // Current time
    //   const startTime = moment(savedState.startTime);
    //   const pauseTime = savedState.pauseTime
    //     ? moment(savedState.pauseTime)
    //     : null;
    //   const totalPausedTimeInSeconds = savedState.breakTimeInSeconds || 0;

    //   let calculatedElapsedTimeInSeconds;

    //   if (pauseTime) {
    //     // If paused, calculate elapsed time until the last pause
    //     calculatedElapsedTimeInSeconds =
    //       pauseTime.diff(startTime, "seconds") - totalPausedTimeInSeconds;
    //   } else {
    //     // If not paused, calculate elapsed time until now
    //     calculatedElapsedTimeInSeconds =
    //       now.diff(startTime, "seconds") - totalPausedTimeInSeconds;
    //   }

    //   setStartTime(startTime);
    //   setElapsedTime(calculatedElapsedTimeInSeconds);
    //   setPauseTime(pauseTime);
    //   setIsPaused(!!pauseTime);
    //   setBreakTime(totalPausedTimeInSeconds); // Restore break time
    //   setIsClockedIn(true);
    // }

    getTimeSheet(moment().format("YYYYMMDD"));

    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      getCustomCreateSubscriptionTopic(encrypted_token?.connectionId),
      (response) => {
        //   setSaving(false);
        console.log("response", response?.response?.data?.id);
        setSelectedCustomId(response?.response?.data?.id);
        // pushNotification(
        //   "Timesheet saved successfully",
        //   "success",
        //   "TOP_CENTER",
        //   1000
        // );
      }
    );

    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      getCustomUpdateSubscriptionTopic(encrypted_token?.connectionId),
      (response) => {
        //   setSaving(false);
        console.log("response", response);
        // pushNotification(
        //   "Timesheet saved successfully",
        //   "success",
        //   "TOP_CENTER",
        //   1000
        // );
        getTimeSheet(moment().format("YYYYMMDD"));
      }
    );
  }, []);

  const persistTimesheet = (
    nextSessions: SessionState[],
    activeElapsedSeconds?: number
  ) => {
    const activeIdx = getActiveSessionIndex(nextSessions);
    const now = moment();
    let totalWorkedSeconds = workedSecondsFromCompletedSessions(nextSessions);
    if (activeIdx >= 0) {
      const active = nextSessions[activeIdx];
      const elapsed =
        activeElapsedSeconds !== undefined
          ? activeElapsedSeconds
          : computeActiveElapsedSeconds(active, now);
      totalWorkedSeconds += Math.max(0, elapsed);
    }

    const totalWorkedTimeInMinutes = Math.floor(totalWorkedSeconds / 60);
    const totalBreakSeconds = nextSessions.reduce(
      (sum, s) => sum + (s.breakTimeInSeconds || 0),
      0
    );

    const serializedSessions = nextSessions.map((s, i) => {
      const isOpen = i === activeIdx;
      return {
        startTime: s.startTime.toISOString(),
        endTime: s.endTime?.toISOString(),
        breakTimeInSeconds: s.breakTimeInSeconds || 0,
        pauseTime:
          isOpen && s.pauseTime ? s.pauseTime.toISOString() : null,
      };
    });

    const first = nextSessions[0];
    const last = nextSessions[nextSessions.length - 1];
    const state = {
      sessions: serializedSessions,
      totalWorkedTimeInMinutes,
      breakTimeInSeconds: totalBreakSeconds,
      startTime: first?.startTime.toISOString(),
      endTime: last?.endTime?.toISOString(),
      isClockedIn: activeIdx >= 0,
    };

    localStorage.setItem("clockIn", JSON.stringify(state));

    if (!selectedCustomId) {
      const customChanges = [
        {
          op: "add",
          path: "/partitions",
          value: [
            `org:${encrypted_token?.cudbServiceId || encrypted_token?.serviceId}`,
            `user:${userId}`,
            `type:timesheet`,
            `date:${moment().format("YYYYMMDD")}`,
          ],
        },
        {
          op: "add",
          path: "/createdAt",
          value: new Date().getTime(),
        },
        {
          op: "add",
          path: "/info",
          value: state,
        },
      ];
      console.log("custom changes", customChanges);

      socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        getCustomCreateRequestPublishTopic(encrypted_token?.connectionId),
        wrapRequestPayload({
          changes: customChanges,
        })
      );
    } else {
      socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        getCustomUpdateRequestPublishTopic(encrypted_token?.connectionId),
        wrapRequestPayload({
          objectId: selectedCustomId,
          changes: [
            {
              op: "replace",
              path: "/info",
              value: state,
            },
          ],
        })
      );
    }
  };

  // Timer logic
  useEffect(() => {
    let timer: NodeJS.Timeout | null = null;

    if (isClockedIn && !isPaused) {
      timer = setInterval(() => {
        setElapsedTime((prev) => prev + 1);
      }, 1000);
    }

    return () => {
      if (timer) clearInterval(timer);
    };
  }, [isClockedIn, isPaused]);

  const handleClockIn = () => {
    if (getActiveSessionIndex(sessions) >= 0) {
      message.warning("You are already clocked in.");
      return;
    }
    const now = moment();
    const next: SessionState[] = [
      ...sessions,
      {
        startTime: now,
        breakTimeInSeconds: 0,
        pauseTime: null,
      },
    ];
    setSessions(next);
    setIsClockedIn(true);
    setIsPaused(false);
    setPauseTime(null);
    setBreakTime(0);
    setElapsedTime(0);
    persistTimesheet(next, 0);
    message.success("Clocked In!");
  };

  const handlePauseResume = () => {
    const now = moment();
    const activeIdx = getActiveSessionIndex(sessions);
    if (activeIdx < 0) return;

    if (isPaused && pauseTime) {
      const pausedDurationInSeconds = now.diff(pauseTime, "seconds");
      const updatedBreakTimeInSeconds = breakTime + pausedDurationInSeconds;
      const next = sessions.map((s, i) =>
        i === activeIdx
          ? {
              ...s,
              breakTimeInSeconds: updatedBreakTimeInSeconds,
              pauseTime: null,
            }
          : s
      );
      setSessions(next);
      setBreakTime(updatedBreakTimeInSeconds);
      setPauseTime(null);
      setIsPaused(false);
      const newElapsed = computeActiveElapsedSeconds(
        { ...next[activeIdx], pauseTime: null },
        now
      );
      setElapsedTime(newElapsed);
      persistTimesheet(next, newElapsed);
      message.success("Resumed!");
    } else {
      const next = sessions.map((s, i) =>
        i === activeIdx ? { ...s, pauseTime: now } : s
      );
      setSessions(next);
      setPauseTime(now);
      setIsPaused(true);
      persistTimesheet(next, elapsedTime);
      message.success("Paused!");
    }
  };

  const handleClockOut = () => {
    const now = moment();
    const activeIdx = getActiveSessionIndex(sessions);
    if (activeIdx < 0) return;

    const active = sessions[activeIdx];
    const totalSessionTimeInSeconds = now.diff(active.startTime, "seconds");
    const totalWorkedTimeInSeconds = totalSessionTimeInSeconds - breakTime;
    const sessionWorkedMinutes = Math.floor(totalWorkedTimeInSeconds / 60);

    const next = sessions.map((s, i) =>
      i === activeIdx
        ? {
            ...s,
            endTime: now,
            pauseTime: null,
          }
        : s
    );

    setSessions(next);
    setIsClockedIn(false);
    setIsPaused(false);
    setPauseTime(null);
    setElapsedTime(0);
    setBreakTime(0);

    persistTimesheet(next);

    const dayMinutes = Math.floor(
      workedSecondsFromCompletedSessions(next) / 60
    );
    message.success(
      `Clocked Out! Session: ${sessionWorkedMinutes} min. Today total: ${dayMinutes} min.`
    );
  };

  const applyTimesheetDay = (t: moment.Moment, dayStr: string) => {
    const y = parseInt(dayStr.slice(0, 4), 10);
    const m = parseInt(dayStr.slice(4, 6), 10) - 1;
    const d = parseInt(dayStr.slice(6, 8), 10);
    return moment(t).clone().year(y).month(m).date(d);
  };

  const handleEdit = () => {
    const day = moment().format("YYYYMMDD");
    const initialSessions =
      sessions.length > 0
        ? sessions.map((s) => ({
            startTime: s.startTime ? moment(s.startTime) : null,
            endTime: s.endTime ? moment(s.endTime) : null,
            breakTime: parseFloat(
              ((s.breakTimeInSeconds || 0) / 60).toFixed(2)
            ),
          }))
        : [
            {
              startTime: null,
              endTime: null,
              breakTime: 0,
            },
          ];
    form.setFieldsValue({
      sessions: initialSessions,
      day,
    });
    setEditModalVisible(true);
  };

  const handleSaveEdit = () => {
    form.validateFields().then((values) => {
      const dayStr = values.day as string;
      const rows = values.sessions as Array<{
        startTime: moment.Moment;
        endTime: moment.Moment | null;
        breakTime: number;
      }>;
      const wasClockedIn = getActiveSessionIndex(sessions) >= 0;

      if (!rows?.length) {
        message.error("Add at least one session.");
        return;
      }

      for (let i = 0; i < rows.length; i++) {
        const row = rows[i];
        if (!row?.startTime) {
          message.error("Each session needs a start time.");
          return;
        }
        const isLast = i === rows.length - 1;
        const openLast = isLast && !row.endTime;
        if (openLast && !wasClockedIn) {
          message.error("End time is required for each session.");
          return;
        }
        if (!isLast && !row.endTime) {
          message.error("Each session needs an end time.");
          return;
        }
      }

      const next: SessionState[] = rows.map((row) => {
        const start = applyTimesheetDay(moment(row.startTime), dayStr);
        let endM: moment.Moment | undefined;
        if (row.endTime) {
          endM = applyTimesheetDay(moment(row.endTime), dayStr);
        }
        const breakSecs = Math.max(0, (row.breakTime || 0) * 60);
        return {
          startTime: start,
          endTime: endM,
          breakTimeInSeconds: breakSecs,
          pauseTime: null,
        };
      });

      setSessions(next);
      const stillIn = getActiveSessionIndex(next) >= 0;
      setIsClockedIn(stillIn);
      setIsPaused(false);
      setPauseTime(null);
      setBreakTime(stillIn ? next[next.length - 1].breakTimeInSeconds : 0);

      const now = moment();
      if (stillIn) {
        setElapsedTime(computeActiveElapsedSeconds(next[next.length - 1], now));
      } else {
        setElapsedTime(0);
      }

      persistTimesheet(
        next,
        stillIn ? computeActiveElapsedSeconds(next[next.length - 1], now) : undefined
      );

      setEditModalVisible(false);
      const totalMins = Math.floor(
        (workedSecondsFromCompletedSessions(next) +
          (stillIn ? computeActiveElapsedSeconds(next[next.length - 1], now) : 0)) /
          60
      );
      message.success(
        `Timesheet updated successfully! Total worked today: ${totalMins} minutes`
      );
    });
  };

  const formatElapsedTime = (seconds: number) => {
    const hrs = Math.floor(seconds / 3600);
    const mins = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;
    return `${hrs.toString().padStart(2, "0")}:${mins
      .toString()
      .padStart(2, "0")}:${secs.toString().padStart(2, "0")}`;
  };

  return (
    <div className="card-container">
      <div
        className="custom-card"
        style={{ backgroundColor: isClockedIn ? "#FF5F25" : "#40CC52" }}
        onClick={!isClockedIn ? handleClockIn : handleClockOut}
      >
        <div className="card-icon">
          <ClockCircleOutlined style={{ fontSize: "24px", color: "#fff" }} />
        </div>
        <div className="card-title">
          {!isClockedIn
            ? "Clock In"
            : `Clock Out (${formatElapsedTime(elapsedTime)})`}
        </div>
        {sessions.some((s) => s.endTime) && (
          <div
            className="card-title"
            style={{ fontSize: "12px", marginTop: 6, opacity: 0.95 }}
          >
            Today total:{" "}
            {formatElapsedTime(
              workedSecondsFromCompletedSessions(sessions) +
                (isClockedIn ? elapsedTime : 0)
            )}
          </div>
        )}
      </div>

      {isClockedIn && (
        <div
          className="custom-card"
          style={{ backgroundColor: "#FBAE16" }}
          onClick={handlePauseResume}
        >
          <div className="card-icon">
            {isPaused ? (
              <PlayCircleOutlined style={{ fontSize: "24px", color: "#fff" }} />
            ) : (
              <PauseCircleOutlined
                style={{ fontSize: "24px", color: "#fff" }}
              />
            )}
          </div>
          <div className="card-title">{isPaused ? "Resume" : "Pause"}</div>
        </div>
      )}

      <div
        className="custom-card"
        style={{ backgroundColor: "#1890ff" }}
        onClick={handleEdit}
      >
        <div className="card-icon">
          <EditOutlined style={{ fontSize: "24px", color: "#fff" }} />
        </div>
        <div className="card-title">Edit Timesheet</div>
      </div>

      {/* Edit Modal */}
      <Modal
        title="Edit Timesheet"
        className="beam-modal"
        visible={editModalVisible}
        onCancel={() => setEditModalVisible(false)}
      >
        <Form form={form} layout="vertical">
          <Form.Item name="day" hidden>
            <Input />
          </Form.Item>
          <p className="mb-3" style={{ opacity: 0.85 }}>
            Add one row per shift. Leave end time blank only for your current
            open session (while clocked in).
          </p>
          <Form.List name="sessions">
            {(fields, { add, remove }) => (
              <>
                {fields.map((field, index) => (
                  <Row
                    key={field.key}
                    gutter={[8, 8]}
                    align="middle"
                    className="mb-2"
                  >
                    <Col xs={24} sm={7}>
                      <Form.Item
                        label={index === 0 ? "Start" : ""}
                        name={[field.name, "startTime"]}
                        fieldKey={[field.fieldKey, "startTime"]}
                        rules={[
                          {
                            required: true,
                            message: "Start time required",
                          },
                        ]}
                      >
                        <TimePicker format="HH:mm" className="w-full" />
                      </Form.Item>
                    </Col>
                    <Col xs={24} sm={7}>
                      <Form.Item
                        label={index === 0 ? "End" : ""}
                        name={[field.name, "endTime"]}
                        fieldKey={[field.fieldKey, "endTime"]}
                      >
                        <TimePicker format="HH:mm" className="w-full" />
                      </Form.Item>
                    </Col>
                    <Col xs={24} sm={6}>
                      <Form.Item
                        label={index === 0 ? "Break (min)" : ""}
                        name={[field.name, "breakTime"]}
                        fieldKey={[field.fieldKey, "breakTime"]}
                        rules={[
                          {
                            required: true,
                            message: "Required",
                          },
                        ]}
                      >
                        <Input type="number" min={0} />
                      </Form.Item>
                    </Col>
                    <Col xs={24} sm={4} className="pb-1">
                      {fields.length > 1 ? (
                        <MinusCircleOutlined
                          className="text-red-500"
                          style={{ fontSize: 20, marginTop: index === 0 ? 28 : 4 }}
                          onClick={() => remove(field.name)}
                        />
                      ) : null}
                    </Col>
                  </Row>
                ))}
                <Form.Item>
                  <Button
                    type="dashed"
                    onClick={() =>
                      add({ startTime: null, endTime: null, breakTime: 0 })
                    }
                    block
                    icon={<PlusOutlined />}
                  >
                    Add shift
                  </Button>
                </Form.Item>
              </>
            )}
          </Form.List>

          <Form.Item>
            <Row className="action-grp mt-4">
              <Col span={12} xs={12} sm={12}>
                <Button
                  className="beam-btn orange-btn bordered w-full"
                  onClick={() => setEditModalVisible(false)}
                >
                  Cancel
                </Button>
              </Col>
              <Col span={12} className="pl-2" xs={12} sm={12}>
                <Button
                  className="beam-btn green-btn cover w-full"
                  onClick={handleSaveEdit}
                >
                  Save
                </Button>
              </Col>
            </Row>
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
};

export default CustomCard;
