const TestLogs: FC = () => {
  const [logs, setLogs] = useState<string[]>([]);

  useEffect(() => {
    const originalConsoleLog = console.log;

    console.log = (...args) => {
      const logMessage = args.map((arg) => (typeof arg === "string" ? arg : JSON.stringify(arg))).join(" ");
      setLogs((prevLogs) => [...prevLogs, logMessage]); // Save log to state
      originalConsoleLog(...args); // Call the original log
    };

    // Cleanup to restore console.log on unmount
    return () => {
      console.log = originalConsoleLog;
    };
  }, []);

  return (
    <List
      dataSource={logs}
      renderItem={(log, index) => (
        <List.Item>
          <span>
            {index + 1}. {log}
          </span>
        </List.Item>
      )}
    />
  );
};

