const STORAGE_KEY = "visibleKeys";
const SORT_ORDERS_STORAGE_KEY = "dashboardSortOrders";

const ColumnVisibilityDropdown = ({
  allColumns,
  status,
  visibleKeys,
  setVisibleKeys,
}: {
  allColumns: Column[];
  status?: string;
  visibleKeys: string[];
  setVisibleKeys: (keys: string[]) => void;
}) => {
  // const [visibleKeys, setVisibleKeys] = useState<string[]>([]);
  const [open, setOpen] = useState(false); // control open state

  // Load saved keys from localStorage
  useEffect(() => {
    const savedKeys = localStorage.getItem(STORAGE_KEY);
    // console.log("savedKeys", savedKeys);
    if (savedKeys) {
      setVisibleKeys(JSON.parse(savedKeys));
    } else {
      // Default: show all columns
      setVisibleKeys(allColumns.map((col) => col.key));
    }
  }, [allColumns]);

  // Save keys to localStorage whenever they change
  useEffect(() => {
    if (visibleKeys.length > 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(visibleKeys));
    }
  }, [visibleKeys]);

  // Build the menu overlay
  const menu = (
    <div
      style={{ padding: 10, backgroundColor: "white" }}
      onClick={(e) => e.stopPropagation()}
    >
      <Checkbox.Group
        value={visibleKeys}
        onChange={(keys) => setVisibleKeys(keys as string[])}
      >
        {allColumns.map((col) => (
          <div key={col.key} style={{ marginBottom: 8 }}>
            <Checkbox value={col.key}>{col.title}</Checkbox>
          </div>
        ))}
      </Checkbox.Group>

      {/* Optional: Reset button */}
      {/* <Button
        type="link"
        style={{ marginTop: 10, padding: 0 }}
        onClick={() => {
          localStorage.removeItem(STORAGE_KEY);
          setVisibleKeys(allColumns.map((col) => col.key));
        }}
      >
        Reset to Default
      </Button> */}

      <div style={{ marginTop: 10, textAlign: "right" }}>
        <Button
          size="small"
          onClick={() => {
            localStorage.removeItem(STORAGE_KEY);
            localStorage.removeItem("columnWidths");
            // setVisibleKeys(allColumns.map((col) => col.key));
            window.location.reload();
          }}
        >
          Reset
        </Button>
        {/* <Button
          type="primary"
          size="small"
          style={{ marginLeft: 8 }}
          onClick={() => setOpen(false)} // close dropdown on Apply
        >
          Apply
        </Button> */}
      </div>
    </div>
  );

  return (
    <Dropdown
      overlay={menu}
      trigger={["click"]}
      visible={open}
      onVisibleChange={(flag) => setOpen(flag)}
    >
      <Button className="beam-btn icon-btn" style={{ margin: '10px' }}>
        <SettingOutlined />
      </Button>
    </Dropdown>
  );
};


