const ResizableTitle = ({ width, onResize, ...restProps }: any) => {
  const [colWidth, setColWidth] = useState(width);
  const resizing = useRef(false);
  const justResizedRef = useRef(false);
  const startX = useRef(0);
  const startWidth = useRef(width);
  const startLeft = useRef(0); // Store the initial left position of the column
  const pendingWidth = useRef(width);
  const thRef = useRef<HTMLTableCellElement>(null);
  const resizeHandleRef = useRef<HTMLDivElement>(null);
  const tableContainerRef = useRef<HTMLElement | null>(null);
  const [previewLine, setPreviewLine] = useState<{ visible: boolean; x: number; top: number; height: number }>({
    visible: false,
    x: 0,
    top: 0,
    height: 0
  });

  useEffect(() => {
    if (!resizing.current) {
      setColWidth(width);
      pendingWidth.current = width;
      if (thRef.current) thRef.current.style.width = `${width}px`;
      startWidth.current = width;
    }
  }, [width]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (resizing.current) {
        resizing.current = false;
        setPreviewLine({ visible: false, x: 0, top: 0, height: 0 });
        // Remove all event listeners
        document.removeEventListener("pointermove", handlePointerMove);
        document.removeEventListener("pointerup", handlePointerUp);
        document.removeEventListener("pointercancel", handlePointerCancel);
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Find table container on mount - look for the div that contains the table
  useEffect(() => {
    if (thRef.current) {
      let parent = thRef.current.parentElement;
      while (parent) {
        // Look for the table-scroll-wrapper (Col element) or ant-table-wrapper
        if (parent.classList.contains('table-scroll-wrapper')) {
          tableContainerRef.current = parent;
          break;
        }
        // Check for ant-table-wrapper which is the direct container of the table
        if (parent.classList.contains('ant-table-wrapper')) {
          tableContainerRef.current = parent;
          break;
        }
        // Check if this element contains the ant-table and has position relative
        const computedStyle = window.getComputedStyle(parent);
        if (computedStyle.position === 'relative' && parent.querySelector('.ant-table')) {
          tableContainerRef.current = parent;
          break;
        }
        if (!parent.parentElement) break;
        parent = parent.parentElement;
      }
    }
  }, []);

  const handlePointerMove = (e: PointerEvent) => {
    if (!resizing.current || !thRef.current || !tableContainerRef.current) return;
    e.preventDefault();
    e.stopPropagation();

    // Update preview line position - use clientX directly for fixed positioning
    // Also update container bounds for accurate height/position
    const containerRect = tableContainerRef.current.getBoundingClientRect();

    setPreviewLine({
      visible: true,
      x: e.clientX,
      top: containerRect.top,
      height: containerRect.height
    });
  };

  const handlePointerUp = (e: PointerEvent) => {
    if (!resizing.current || !thRef.current) return;
    e.preventDefault();
    e.stopPropagation();
    resizing.current = false;

    // Hide preview line
    setPreviewLine({ visible: false, x: 0, top: 0, height: 0 });

    // Get initial measurements before resize
    const beforeRect = thRef.current.getBoundingClientRect();

    // Calculate the required offsetWidth to make the right edge align with mouse position
    // The relationship between offsetWidth and actual rendered width includes padding/borders
    // We need to use the ratio from the initial state
    const widthFromMouse = e.clientX - beforeRect.left;

    // Calculate the ratio: offsetWidth / actualRenderedWidth
    // This accounts for padding/borders that are included in offsetWidth
    const actualRenderedWidth = beforeRect.right - beforeRect.left;
    const offsetWidthRatio = thRef.current.offsetWidth / actualRenderedWidth;

    // Scale the width to account for padding/borders
    let finalWidth = widthFromMouse * offsetWidthRatio;

    // Ensure minimum width
    finalWidth = Math.max(finalWidth, 50);

    // Round to avoid sub-pixel rendering issues
    finalWidth = Math.round(finalWidth);

    // Call onResize callback FIRST - this updates the column definition
    // which is what actually controls the width in tableLayout="fixed"
    onResize?.(e, { size: { width: finalWidth, height: 0 } });

    // Then update local state and style
    setColWidth(finalWidth);
    if (thRef.current) {
      thRef.current.style.width = `${finalWidth}px`;
      // Also set minWidth to ensure it's respected
      thRef.current.style.minWidth = `${finalWidth}px`;
    }

    // Force reflow to ensure width is applied
    void thRef.current.offsetWidth;

    document.removeEventListener("pointermove", handlePointerMove);
    document.removeEventListener("pointerup", handlePointerUp);
    document.removeEventListener("pointercancel", handlePointerCancel);

    // Prevent sorting immediately after resize by temporarily intercepting clicks
    justResizedRef.current = true;

    const preventClick = (clickEvent: MouseEvent) => {
      if (thRef.current && thRef.current.contains(clickEvent.target as Node)) {
        clickEvent.preventDefault();
        clickEvent.stopPropagation();
        document.removeEventListener("click", preventClick, true);
      }
    };

    document.addEventListener("click", preventClick, true);

    setTimeout(() => {
      justResizedRef.current = false;
      document.removeEventListener("click", preventClick, true);
    }, 200);
  };

  const handlePointerCancel = (e: PointerEvent) => {
    if (!resizing.current) return;
    resizing.current = false;
    setPreviewLine({ visible: false, x: 0, top: 0, height: 0 });
    document.removeEventListener("pointermove", handlePointerMove);
    document.removeEventListener("pointerup", handlePointerUp);
    document.removeEventListener("pointercancel", handlePointerCancel);
  };

  const handlePointerDown = (e: React.PointerEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (!thRef.current) return;

    resizing.current = true;

    // Store the initial column right edge position as the reference point
    // Use getBoundingClientRect() to get the actual rendered dimensions
    const thRect = thRef.current.getBoundingClientRect();
    startX.current = thRect.right; // Use column's right edge, not click position

    // Use offsetWidth as the base since it represents the actual rendered size
    // This includes padding/borders and matches what we see on screen
    startWidth.current = thRef.current.offsetWidth || colWidth || width;
    startLeft.current = thRect.left;
    pendingWidth.current = startWidth.current;

    document.addEventListener("pointermove", handlePointerMove);
    document.addEventListener("pointerup", handlePointerUp);
    document.addEventListener("pointercancel", handlePointerCancel);
  };

  const handleResizeHandleClick = (e: React.MouseEvent) => {
    // Prevent sorting when clicking on the resize handle
    e.preventDefault();
    e.stopPropagation();
  };

  const handleResizeHandleMouseDown = (e: React.MouseEvent) => {
    // Prevent sorting when mouse down on the resize handle
    e.preventDefault();
    e.stopPropagation();
  };

  return (
    <>
      <th
        {...restProps}
        ref={thRef}
        style={{
          width: colWidth,
          position: "relative",
          userSelect: "none",
          touchAction: "none",
        }}
      >
        {restProps.children}

        <div
          ref={resizeHandleRef}
          onPointerDown={handlePointerDown}
          onClick={handleResizeHandleClick}
          onMouseDown={handleResizeHandleMouseDown}
          className="resizable-handle"
          style={{
            position: "absolute",
            top: 0,
            right: 0,
            width: 10,
            height: "100%",
            cursor: "col-resize",
            zIndex: 999,
            touchAction: "none",
          }}
        />
      </th>

      {/* Preview line rendered via portal to document.body for accurate positioning */}
      {previewLine.visible && createPortal(
        <div
          className="column-resize-preview-line"
          style={{
            position: "fixed",
            left: `${previewLine.x}px`,
            top: `${previewLine.top}px`,
            height: `${previewLine.height}px`,
            width: "2px",
            backgroundColor: "#508AFA",
            pointerEvents: "none",
            zIndex: 10000,
            transform: "translateX(-1px)", // Center the 2px line on the mouse position
          }}
        />,
        document.body
      )}
    </>
  );
};

const useResizableColumnsWithVisibility = (initialColumns) => {
  const [allColumns, setAllColumns] = useState([]);
  const [visibleKeys, setVisibleKeys] = useState([]);

  useEffect(() => {
    const savedWidths = JSON.parse(localStorage.getItem("columnWidths")) || {};

    // Add 10 dummy columns
    const dummyColumns = initialColumns?.length > 0 ? Array.from({ length: 10 }).map((_, idx) => ({
      key: `__dummy_${idx}`,
      title: "",
      width: 200,       // fixed width for dummy
      minWidth: 200,
      dataIndex: `__dummy_${idx}`,
      isDummy: true,    // optional flag
    })) : [];

    setAllColumns(
      [
        ...initialColumns,
        ...dummyColumns
      ].map(col => ({
        ...col,
        width: savedWidths[col.key] || col.width || 150,
      }))
    );
  }, [initialColumns]);

  const handleResize = useCallback(
    (key) => (_, { size }) => {
      setAllColumns(prev => {
        const updated = prev.map(col =>
          col.key === key ? { ...col, width: size.width } : col
        );

        const widthsToSave = updated.reduce((acc, c) => {
          acc[c.key] = c.width;
          return acc;
        }, {});
        localStorage.setItem("columnWidths", JSON.stringify(widthsToSave));

        return updated;
      });
    },
    []
  );

  const visibleColumns = allColumns
    .filter(col => visibleKeys.includes(col.key) || col.isDummy)
    .map(col => ({
      ...col,
      onHeaderCell: () => ({
        width: col.width,
        onResize: handleResize(col.key),
      }),
    }));

  return {
    columns: visibleColumns,
    allColumns,
    visibleKeys,
    setVisibleKeys,
    ResizableTitle,
  };
};



