import React, { FC } from "react";
import { Drawer, Empty, Tag } from "antd";
import { Violation } from "services/apis/aiSchedulerTypes";

const ViolationsDrawer: FC<{
  visible: boolean;
  violations: Violation[];
  onClose: () => void;
}> = ({ visible, violations, onClose }) => {
  const hard = violations.filter((v) => v.severity === "hard");
  const soft = violations.filter((v) => v.severity !== "hard");

  return (
    <Drawer
      title="Schedule warnings"
      visible={visible}
      onClose={onClose}
      width={420}
      className="violations-drawer"
    >
      {!violations.length && <Empty description="No violations — clean schedule" />}

      {hard.length > 0 && (
        <>
          <h4>
            <Tag color="red">hard</Tag> Broken rules
          </h4>
          {hard.map((v, i) => (
            <div key={`h${i}`} className="violation-item hard">
              <strong>{v.constraint}</strong>
              {v.detail && <p style={{ marginBottom: 0 }}>{v.detail}</p>}
            </div>
          ))}
        </>
      )}

      {soft.length > 0 && (
        <>
          <h4 style={{ marginTop: hard.length ? 16 : 0 }}>
            <Tag color="orange">soft</Tag> Allowed but worse
          </h4>
          {soft.map((v, i) => (
            <div key={`s${i}`} className="violation-item soft">
              <strong>{v.constraint}</strong>
              {v.penalty !== undefined && (
                <span style={{ color: "#8c8c8c" }}> · penalty {v.penalty}</span>
              )}
              {v.detail && <p style={{ marginBottom: 0 }}>{v.detail}</p>}
            </div>
          ))}
        </>
      )}
    </Drawer>
  );
};

export default ViolationsDrawer;
