import React from "react";
import { Table } from "antd";
import { useDashboard } from "../context";

const PagesTable: React.FC = () => {
  const { tableDataSource, tableColumns, dispatch, selectedPage } =
    useDashboard();

  return (
    <Table
      dataSource={tableDataSource}
      className={tableDataSource?.length > 0 ? "" : "table-empty"}
      onRow={(record: any) => {
        return {
          onDoubleClick: () => {
            dispatch({
              type: "SET_SELECTED_PAGE",
              payload: { page: record?.action?.page },
            });
          },
          onClick: () => {},
        };
      }}
      columns={tableColumns}
      scroll={{ x: true }}
      onChange={(e) => {
        console.log("event here", e);
      }}
      rowClassName={(record: any, index) => {
        if (record?.key === selectedPage?.page?.pageId)
          return `row-selected ${record.pageStatus}-row`;
        return `${record.pageStatus}-row`;
      }}
    />
  );
};

export default PagesTable;
