/** Avoid UTC parsing of YYYY-MM-DD via `new Date` (off-by-one calendar day in local TZ). */
function localDateFromPickupField(pickupDate: unknown): Date {
  if (pickupDate == null || pickupDate === "") return new Date();
  if (moment.isMoment(pickupDate)) {
    return pickupDate.toDate();
  }
  const s = String(pickupDate).trim();
  const m = moment(
    s,
    [
      "YYYY-MM-DD",
      "MM/DD/YYYY",
      "MMM-DD",
      "DD/MM/YYYY",
      "MMM D, YYYY",
      "ddd, MMM D, YYYY",
    ],
    true
  );
  if (m.isValid()) return m.toDate();
  const fallback = moment(s);
  return fallback.isValid() ? fallback.toDate() : new Date();
}

function formatAppointmentTimeForAttributes(raw: unknown): string | undefined {
  if (raw == null || raw === "") return undefined;
  if (moment.isMoment(raw)) {
    return raw.isValid() ? raw.format("HH:mm") : undefined;
  }
  const s = String(raw).trim();
  const m = moment(
    s,
    [
      "YYYY-MM-DDTHH:mm:ss",
      "YYYY-MM-DDTHH:mm",
      "HH:mm",
      "HH:mm:ss",
      "h:mm A",
      "hh:mm A",
    ],
    true
  );
  if (m.isValid()) return m.format("HH:mm");
  const loose = moment(s);
  return loose.isValid() ? loose.format("HH:mm") : undefined;
}

