// Types for the AI Scheduler service (see INTEGRATION.md).
// Prefixed "Sched" to avoid clashing with the app's ambient interfaces.

export type Day = "mon" | "tue" | "wed" | "thu" | "fri" | "sat" | "sun";

export const DAY_ORDER: Day[] = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"];

export const DAY_LABELS: Record<Day, string> = {
  mon: "Monday",
  tue: "Tuesday",
  wed: "Wednesday",
  thu: "Thursday",
  fri: "Friday",
  sat: "Saturday",
  sun: "Sunday",
};

export const SLOT_MINUTES_OPTIONS = [5, 10, 15, 20, 30, 60] as const;

export interface TimeWindow {
  days: Day[];
  start: string; // "HH:MM" 24h
  end: string;
}

export interface OrgSettings {
  slotMinutes: number;
  days: Day[];
  dayStart: string;
  dayEnd: string;
}

export interface SchedResource {
  id?: string;
  kind: string;
  name: string;
  capacity?: number;
  quantity?: number;
  location?: string;
  tags?: string[];
  availability?: TimeWindow[]; // empty = always available
  bufferMinutes?: number;
  active?: boolean;
}

export interface Requirement {
  // Either pin one resource...
  resourceId?: string;
  count?: number; // units drawn from a pooled resource
  // ...or describe an acceptable one and let the solver choose.
  kind?: string;
  tagsAll?: string[];
  tagsAny?: string[];
  capacityAtLeast?: number | "enrollment";
}

export interface PinnedMeeting {
  occurrence: number;
  day: Day;
  start: string;
}

export interface SchedActivity {
  id?: string;
  name: string;
  durationMinutes: number;
  countPerWeek: number;
  enrollment?: number;
  enrollmentMin?: number;
  priority?: number; // 0-100
  requirements: Requirement[];
  window?: TimeWindow[];
  allowedDays?: Day[];
  preferredLocations?: string[];
  noOverlapWith?: string[];
  pinned?: PinnedMeeting[];
  active?: boolean;
}

export interface DistanceEntry {
  fromLocation: string;
  toLocation: string;
  minutes: number;
}

export interface ConstraintDef {
  key: string;
  enabled: boolean;
  hard: boolean;
  weight?: number;
  params?: Record<string, any>;
  description?: string;
}

export interface Scenario {
  resourcesOffline?: string[];
  activitiesExcluded?: string[];
}

export interface SolveRequest {
  timeLimitSeconds?: number;
  scenario?: Scenario;
  previousScheduleId?: string;
}

export type JobStatus = "queued" | "running" | "done" | "failed" | "infeasible";

export interface SchedJob {
  jobId?: string;
  id?: string;
  status: JobStatus;
  progress?: number; // 0..1
  scheduleId?: string;
}

export interface Assignment {
  activityId: string;
  activityName?: string;
  occurrence: number;
  day: Day;
  start: string;
  end: string;
  resources: Record<string, string[]>; // kind -> resource ids
  location?: string;
}

export interface Violation {
  constraint: string;
  severity: "hard" | "soft";
  penalty?: number;
  detail?: string;
}

export interface Schedule {
  id?: string;
  status: string;
  assignments: Assignment[];
  violations: Violation[];
  score?: { objective: number; penalties: Record<string, number> };
  diagnostics?: string[];
}

export interface ValidateResponse {
  valid: boolean;
  violations: Violation[];
}
