import React, { FC, useState, useEffect, useRef } from "react";
import { useHistory } from "react-router-dom";
import { Row, Col, Input, Button, Select, Radio, Tooltip } from "antd";
import { SettingOutlined } from "@ant-design/icons";
import _ from "lodash";
import { Form } from "antd";
import { useLocation } from "react-router-dom";
import { SocketTopics } from "constants/enums";
import { wrapRequestPayload } from "../../../../helpers/request/RequestPayload";
import {
  getRespondersSubscriptionTopic,
  getPageRequestPublishTopic,
  getPageSubscriptionTopic,
  getCreateSchoolPagePublishTopic,
  getCreateSchoolPageSubscriptionTopic,
  getAggregateBdsSubscriptionTopic,
  getUsersSubscriptionTopic,
  callAcceptedPublishTopic,
  getCancelSchoolPagePublishTopic,
  getCancelSchoolPageSubscriptionTopic,
  getFocusPageSubscriptionTopic,
} from "hooks/MQTTConstants";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import {
  SET_SUBMITTED,
  ADD_OTHER_LOCATION,
  ADD_GEOFENCE_LOCATION,
  ADD_STAND_LOCATION,
} from "reducers/reducer";
import { pushNotification } from "utils/notifications";
import { generateUUID } from "utils/appUtil";
import LocationInput from "../../../../common/LocationInput";
import ResponderInput from "../../../../common/ResponderInput";
import { formatObject } from "utils/appUtil";
import ScheduleInput from "../../../../common/ScheduleInput";
import VehicleInput from "../../../../common/VehicleInput";
import StudentInput from "../../../../common/StudentInput";
import moment from "moment";
import ConfirmationModal from "./ConfirmationModal";
import "react-phone-number-input/style.css";
import PhoneInput from "react-phone-number-input";
import Geocode from "react-geocode";
Geocode.setApiKey("AIzaSyDgNagv_ozKWc6IQ75Ol4cH8fxdntOaW6M");
Geocode.setLanguage("en");
Geocode.setRegion("us");

const { TextArea } = Input;

const DispatchPanel: FC<{
  socket: ISocket;
  params: any;
  fullScreen?: boolean;
  scale?: boolean;
  componentUuids?: string;
  userRole?: any;
  dispatchPageId?: string;
  panelTitle?: string;
}> = ({
  socket,
  params,
  fullScreen,
  scale,
  componentUuids,
  userRole,
  dispatchPageId = "210856",
  panelTitle = "Form",
}) => {
  const [nine11Form] = Form.useForm();
  const [error, setError] = useState<string>("");
  const { screens, setScreens } = params;
  const { search } = useLocation();
  const history = useHistory();
  const { projects } = useSelector((state: RootState) => state.auth);
  const dispatch = useDispatch();
  const {
    submitted,
    page,
    encrypted_token,
    selectedPickup,
    standLocations,
    selectedPage,
    adminUserRoles,
  } = useSelector((state: RootState) => state.auth);
  const [searching, setSearching] = useState<boolean>(false);
  const [saving, setSaving] = useState<boolean>(false);
  const [ridePageId, setPageId] = useState<any>(undefined);
  const [ridePageStatus, setPageStatus] = useState<any>(undefined);
  const [dispatchType, setDispatchType] = useState<any>();
  const [vehicleType, setVehicleType] = useState<any>();
  const [isCancelModalVisible, setIsCancelModalVisible] =
    useState<boolean>(false);
  const submitPageId = useRef(true);

  const onSubmitHandler = async (values: any) => {
    if (standLocations?.length > 0) return;
    const userId = encrypted_token?.userId;
    const pageId = ridePageId;
    const connectionId = encrypted_token?.connectionId;
    if (values["undefined"]) {
      values = values["undefined"];
    }
    const extendedAttributes: any = {};
    Object.keys(values).map((key) => {
      const formattedObj = formatObject(key, key, values[key], [], {});

      if (Array.isArray(formattedObj)) {
        formattedObj?.map((obj) => {
          _.merge(extendedAttributes, obj);
        });
      } else {
        _.merge(extendedAttributes, formattedObj);
      }
    });

    setError(undefined);
    setSearching(true);
    const sortedAttributes: any = {
      ...extendedAttributes,
      driver: extendedAttributes?.driver?.value,
      vehicle: extendedAttributes?.vehicle?.value,
      studentId: values?.studentId?.id,
    };

    let eventRequests = [];
    await Promise.all(
      Object.keys(sortedAttributes).map(async (key) => {
        if (sortedAttributes?.[key]?.type === "dispatchType") {
          const oneWaysortedAttributes = {
            ...sortedAttributes,
          };
          if (sortedAttributes?.[key]?.value === "schedule") {
            oneWaysortedAttributes["scheduleDate"] =
              oneWaysortedAttributes?.[key]?.date;
            oneWaysortedAttributes["scheduleTime"] =
              oneWaysortedAttributes?.[key]?.time;
            const tempDate = new Date(
              oneWaysortedAttributes?.[key]?.dateTimestamp
            );
            const tempTime = new Date(
              oneWaysortedAttributes?.[key]?.timeTimestamp
            );
            tempDate.setHours(tempTime.getHours());
            tempDate.setMinutes(tempTime.getMinutes());

            oneWaysortedAttributes[key] = {
              utcDateTime: new Date(tempDate.getTime()).toUTCString(),
              rideDateTime: new Date(tempDate.getTime()).toUTCString(),
              ridelocalDateTime: tempDate.getTime(),
              type: "schedule",
            };
          } else {
            const tempDate = new Date();
            oneWaysortedAttributes[key] = {
              utcDateTime: new Date(tempDate.getTime()).toUTCString(),
              rideDateTime: new Date(tempDate.getTime()).toUTCString(),
              ridelocalDateTime: tempDate.getTime(),
              type: "immediate",
            };
          }
          eventRequests.push({
            userId,
            rideRequestAttributes: {
              ...oneWaysortedAttributes,
            },
            connectionId,
            pageId: submitPageId.current ? pageId : undefined,
            timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
          });
        }
      })
    );
    eventRequests.map((request) => {
      socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        getCreateSchoolPagePublishTopic(connectionId),
        wrapRequestPayload(request)
      );
      // console.log('request', request);
    });
  };

  useEffect(() => {
    if (selectedPage) {
      setFormValuesFromPage({
        ...selectedPage?.page,
        persistent: {
          static: {
            profile: selectedPage?.page?.profile,
          },
        },
      });
      if (!selectedPage?.ignorePage) {
        setPageId(selectedPage?.page?.pageId?.toString());
        setPageStatus(
          selectedPage?.page?.status ||
            selectedPage?.page?.nonpersistent?.static?.live?.status?.name
        );
      } else {
        setPageId(undefined);
        setPageStatus(undefined);
      }
    }
  }, [selectedPage]);

  useEffect(() => {
    if (selectedPickup) {
      const pickupLocation = {
        type: "incident-location",
        label: selectedPickup.location.attributes?.address,
        value: {
          description: selectedPickup?.location.attributes?.address,
          place_id: "",
          coordinates: selectedPickup?.location.coordinates,
        },
      };
      nine11Form.setFieldsValue({
        pickupLocation,
      });
      if (pickupLocation) {
        addOtherLocation({ pickupLocation });
        setScreens({
          ...screens,
          map: true,
        });
        dispatch({ type: ADD_GEOFENCE_LOCATION, payload: undefined });
        dispatch({ type: ADD_STAND_LOCATION, payload: [] });
      }
    }
  }, [selectedPickup]);

  const setFormValuesFromPage = (page) => {
    nine11Form.resetFields();
    dispatch({ type: SET_SUBMITTED, payload: false });
    console.log('page', page);
    
    const { location, time, projectId, vehicleId, driverId, userId, studentName } =
      page?.persistent?.static?.profile?.unstructuredAttributes || {};

      console.log('user', userId, studentName);

    let pickupLocation;
    if (location) {
      pickupLocation = {
        type: "location",
        label: location?.attributes?.address,
        value: {
          description: location?.attributes?.address,
          place_id: "",
          coordinates: location?.coordinates,
        },
      };
      addOtherLocation({
        location: pickupLocation,
      });
    }
    nine11Form.setFieldsValue({
      ...(page?.persistent?.static?.profile ?? {}),
      location: pickupLocation,
      dispatch: {
        value: "schedule",
        type: "dispatchType",
        date: moment(time).format("MM/DD/YYYY HH:mm:ss"),
        time: moment(time).format("MM/DD/YYYY HH:mm:ss"),
      },
      project: projectId,
      vehicle: {
        type: "vehicle",
        value: vehicleId,
        valueName: page?.persistent?.static?.profile?.vehicleName,
      },
      studentId: userId
        ? {
            id: userId,
            beamId: page?.persistent?.static?.profile?.studentName,
          }
        : undefined,
      driver: {
        type: "responder",
        value: driverId,
        beamId: page?.persistent?.static?.profile?.driverName,
        id: driverId,
      },
    });
  };

  useEffect(() => {
    if (page) {
      setFormValuesFromPage(page);
    }
  }, [JSON.stringify(page?.persistent?.static?.profile ?? {})]);

  useEffect(() => {
    if (submitted) {
      setSearching(false);
      if (submitted.status) {
        pushNotification(
          "Ride request submitted",
          "success",
          "TOP_CENTER",
          1000
        );
        dispatch({ type: SET_SUBMITTED, payload: false });
        clearForm();
      } else if (submitted.status === false) {
        pushNotification(
          submitted?.data?.details || "Ride request failed",
          "error",
          "TOP_CENTER",
          3000
        );
        dispatch({ type: SET_SUBMITTED, payload: false });
      }
    }
  }, [
    dispatch,
    history,
    nine11Form,
    saving,
    screens,
    search,
    searching,
    setScreens,
    submitted,
  ]);

  useEffect(() => {
    if (projects?.adminUserId) {
      const connectionId = encrypted_token?.connectionId;
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getAggregateBdsSubscriptionTopic(connectionId)
      );
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getUsersSubscriptionTopic(connectionId, projects?.userServiceId)
      );
    }
  }, [projects]);

  useEffect(() => {
    if (encrypted_token) {
      const query = new URLSearchParams(search);
      const token = query.get("token");
      const sessionId = query.get("setup_intent_client_secret");
      if (token && sessionId) {
        const form = JSON.parse(localStorage.getItem("formValues"));
        if (form) {
          nine11Form.setFieldsValue({
            ...form,
          });
        }
      }
      // socket.subscribeToEvent(
      //   SocketTopics.SubscribePageTopics,
      //   getRespondersSubscriptionTopic(encrypted_token?.connectionId)
      // );
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getCreateSchoolPageSubscriptionTopic(encrypted_token?.connectionId)
      );
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getFocusPageSubscriptionTopic(encrypted_token?.userId),
        (response) => {
          setFormValuesFromPage({
            ...response?.page,
            persistent: {
              static: {
                profile: response?.page?.profile,
              },
            },
          });
          setPageId(response?.page?.pageId?.toString());
        }
      );
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getCancelSchoolPageSubscriptionTopic(encrypted_token?.connectionId),
        (response) => {
          pushNotification(
            "Ride cancelled successfully",
            "success",
            "TOP_CENTER",
            1000
          );
          dispatch({ type: SET_SUBMITTED, payload: false });
          clearForm();
        }
      );
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getPageSubscriptionTopic(encrypted_token?.connectionId)
      );
      if (encrypted_token?.pageId) {
        socket.publishToEvent(
          SocketTopics.PublishPageTopics,
          getPageRequestPublishTopic(encrypted_token?.connectionId),
          wrapRequestPayload(
            {
              objectId: encrypted_token?.pageId,
              paths: ["$"],
              returnPaths: ["$"],
            },
            encrypted_token?.pageId
          )
        );
      }
    }
  }, [encrypted_token]);

  const addOtherLocation = (location) => {
    dispatch({ type: ADD_OTHER_LOCATION, payload: location });
  };

  const clearForm = () => {
    setTimeout(() => {
      const query = new URLSearchParams(search);
      query.delete("pageId");
      query.delete("sessionId");
      history.replace({
        search: query.toString(),
      });
      localStorage.removeItem("form");
      localStorage.removeItem("formValues");
      localStorage.removeItem("active");
      dispatch({ type: SET_SUBMITTED, payload: false });
      dispatch({
        type: "SET_SELECTED_PAGE",
        payload: { page: undefined },
      });
      nine11Form.resetFields();
      nine11Form.setFieldsValue({
        dispatch: {
          type: "dispatchType",
          value: "schedule",
        },
      });
      setPageId(undefined);
    });
  };

  return (
    <div
      className="main-column ride-dispatch-panel mr-4"
      style={scale ? { height: "auto" } : {}}
    >
      <div className="main-content">
        <div className="dispatch-form-toolbar">
          <span className="dispatch-form-title">{panelTitle}</span>
          {userRole === "admin" && (
            <Tooltip title="Edit this form's questions and layout">
              <Button
                type="text"
                className="configure-btn"
                icon={<SettingOutlined />}
                onClick={() => {
                  window.open(
                    `https://cpc.staging.beam.live/admin/cpc/${dispatchPageId}/edit?serviceId=${projects?.userServiceId}&adminUserId=${projects?.adminUserId}&connectionId=${encrypted_token?.connectionId}`,
                    "_blank"
                  );
                }}
              >
                Configure
              </Button>
            </Tooltip>
          )}
        </div>
        <iframe
          className="dispatch-form-iframe"
          title="lecture-dispatch"
          src={`https://cpc.staging.beam.live/c/${dispatchPageId}?serviceId=${projects?.userServiceId}&adminUserId=${projects?.adminUserId}&connectionId=${encrypted_token?.connectionId}`}
          style={{ width: "100%", height: "100vh", border: "none" }}
        />
      </div>

      {isCancelModalVisible && (
        <ConfirmationModal
          onClose={() => {
            setIsCancelModalVisible(undefined);
          }}
          handleConfirm={() => {
            socket.publishToEvent(
              SocketTopics.PublishPageTopics,
              getCancelSchoolPagePublishTopic(encrypted_token?.connectionId),
              wrapRequestPayload({
                pageId: ridePageId,
                userId: encrypted_token?.userId,
              })
            );
            setIsCancelModalVisible(undefined);
          }}
          message={`Are you sure you want to cancel?`}
        />
      )}
    </div>
  );
};

export default DispatchPanel;
