import React, { FC, useEffect, useRef, useState } from "react";
import { Button, Row, Col, Table, Input, Popconfirm, Modal, Form, Skeleton } from "antd";

import _ from "lodash";
import { ReactSVG } from "react-svg";
import {
  SearchOutlined,
  ArrowLeftOutlined,
  EditOutlined,
  DeleteOutlined,
} from "@ant-design/icons";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";
import {
  getAdminRolesTopic,
  getProjectsSubscriptionTopic,
  getProjectsRequestPublishTopic,
} from "hooks/MQTTConstants";
import { SocketTopics, UserTopics } from "constants/enums";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { useDispatch } from "react-redux";
import useSocketActions from "../../../../../hooks/socketActions";
import { formatForRedis, generateUUID } from "utils/appUtil";
import { USER_TYPES, PERMISSION_TYPES } from "utils/PageTypes";
import { GET_AGGREGATE } from "../../../../../reducers/reducer";
import EditPricingModal from "./EditPricingModal";
import Loader from "react-loader-spinner";
import { ExtendedBioTopics } from "constants/enums";
import "../Dashboard.scss";

let timeout;
const PricingModal: FC<{
  socket: ISocket;
  params?: any;
  componentUuid?: string;
}> = ({ socket, params, componentUuid }) => {
  const { selectedPage, encrypted_token, projects, adminUserRoles } =
    useSelector((state: RootState) => state.auth);
  const dispatch = useDispatch();
  const [tableDataSource, setTableDataSource] = useState<any>([]);
  const [tableColumns, setTableColumns] = useState<any>([]);
  useState<boolean>(false);
  const [loading, setLoading] = useState<boolean>(false);
  useState<boolean>(false);
  const { getUserRequestPayload } = useSocketActions();
  // const adminRoles = useRef<any>(undefined);
  // const projects = useRef<any>(undefined);
  const drivers = useRef<any>();
  const [isEditModalVisible, setIsEditModalVisible] = useState<any>(undefined);
  const isMounted = useRef(true);

  const { updateUserRequestPayloadV2 } = useSocketActions();
  const [isModalVisible, setIsModalVisible] = useState(false);
  const [newService, setNewService] = useState("");
  const [error, setError] = useState<string>("");
  const [saving, setSaving] = useState(false);

  const addService = async () => {
    setSaving(true);
    await updatePricing({name: newService});
    setNewService("");
    setIsModalVisible(false);
    setSaving(false);
    getPricing();
  };

  const updatePricing = async (updateData) => {
    return new Promise((resolve, reject) => {
      const { vehicle, preferences } = updateData;
      const updatedUserData = [];
      if (tableDataSource?.length === 0)
        updatedUserData.push({
          op: "add",
          path: "/persistent/static/admin/pricingManagement",
          value: { items: {} },
        });
      const id = generateUUID();
      updatedUserData.push({
        op: "add",
        path: `/persistent/static/admin/pricingManagement/items/${id}`,
        value: {
          _id: id,
          ...updateData,
          locations: [],
          rates: []
        },
      });

      console.log("update user data", updatedUserData);

      socket.publishToServiceIdSurvey(
        SocketTopics.SurveyTopics,
        UserTopics.UpdateUser,
        updateUserRequestPayloadV2(projects?.adminUserId, updatedUserData),
        ExtendedBioTopics.UpdateUserBio,
        projects?.userServiceId
      );
      socket.subscribeToSurvey(
        SocketTopics.SurveyTopics,
        ExtendedBioTopics.UpdateUserBio,
        (response) => {
          console.log('update response', response)
          resolve(response);
        }
      );
    });
  };

  const deletePricing = async (id) => {
    return new Promise((resolve, reject) => {
      const updatedUserData = [];
      updatedUserData.push({
        op: "remove",
        path: `/persistent/static/admin/pricingManagement/items/${id}`,
      });
      socket.publishToServiceIdSurvey(
        SocketTopics.SurveyTopics,
        UserTopics.UpdateUser,
        updateUserRequestPayloadV2(projects?.adminUserId, updatedUserData),
        ExtendedBioTopics.UpdateUserBio,
        projects?.userServiceId
      );
      socket.subscribeToSurvey(
        SocketTopics.SurveyTopics,
        ExtendedBioTopics.UpdateUserBio,
        (response) => {
          console.log('delete response', response)
          resolve(response);
        }
      );
    });
  };

  // hardcoded
  const pricing = [
    { id: 1, name: "Private/Institutional" },
    { id: 2, name: "Hospital-Paid (Contract)" },
    { id: 3, name: "2025 Primary Contract" },
  ];

  const getPricing = (filterText = undefined) => {
    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.SearchInUser,
      getUserRequestPayload(
        projects?.adminUserId,
        "$",
        "$.persistent.static.admin.pricingManagement.items"
      ),
      ExtendedBioTopics.GetUserBio,
      projects?.userServiceId
    );
    setLoading(true);
    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      ExtendedBioTopics.GetUserBio,
      (resp) => {
        console.log("pricing management", resp?.data?.[0]?.[0]);
        let sourceData = [];
        Object?.values(resp?.data?.[0]?.[0] || {})?.map((x: any, i) => {
          sourceData.push({
            key: x._id,
            name: x?.name,
            action: {
              userId: x?.id,
              user: x,
            },
          });
        });
        setLoading(false);
        drivers.current = sourceData;
        // setTableDataSource(sourceData);
        setTableDataSource(
          sourceData.sort((a, b) =>
            (a.name || "").localeCompare(b.name || "")
          )
        );
      }
    );

    let columns: any = [
      {
        title: "Name",
        key: "name",
        dataIndex: "name",
        sorter: (a, b) => a.name?.localeCompare(b?.name),
      },
      {
        title: "Action",
        key: "action",
        dataIndex: "action",
        render: (action: any) => (
          <Row style={{ width: 135 }}>
            <Col span={8}>
              <Button
                style={{ boxShadow: "none" }}
                className="beam-btn icon-btn yellow-btn cover"
                onClick={() => {
                  console.log("action", action);
                  setIsEditModalVisible(action.user);
                }}
              >
                <EditOutlined />
              </Button>
            </Col>
            <Col span={8}>

            <Popconfirm
            title="Are you sure to delete this pricing?"
            onConfirm={async () => {
              await deletePricing(action.user._id);
              getPricing();
            }}
          >
            {/* <Button danger>Delete</Button> */}
            <Button
                style={{ boxShadow: "none" }}
                className="beam-btn icon-btn orange-btn cover"
              >
                <DeleteOutlined />
              </Button>
          </Popconfirm>


              
            </Col>
          </Row>
        ),
      },
    ];
    setTableColumns(columns);
  };


  useEffect(() => {
    document.title = "Pricing | Beam";
    isMounted.current = true;
    return () => {
      isMounted.current = false;
    };
  }, []);

  useEffect(() => {
    if (projects?.adminUserId) {
      getPricing();
    }
  }, [projects]);


  const loadingColumns = [
    {
      title: "...",
      dataIndex: "loading",
      key: "loading",
      render: () => (
        <Skeleton
          active
          title={false} // Disable the title if you only want paragraph lines
          paragraph={{
            rows: 7,
            width: "100%",
          }}
        />
      ),
    },
  ];

  // Placeholder loading data to fill the rows
  const loadingData = Array(1)
    .fill({})
    .map((_, index) => ({ key: `loading-${index}` }));

    
  return (
    <React.Fragment>
      <Row>
      <Col span={24} className="d-flex justify-content-space-between align-items-space-between">
          <div>
          <h2 style={{marginBottom: 0}}>Pricing</h2>
          <p>Home &gt; Pricing</p>
          </div>

          <Button
            type="link"
            className="beam-btn green-btn cover"
            onClick={() => {
              setIsModalVisible(true);
            }}
          >
            Add
          </Button>
        </Col>
      </Row>

      <Row
        gutter={20}
        className="scrollable-table mt-3"
        style={{ display: "grid", marginRight: -20 }}
      >
        <Col
          xs={24}
          sm={24}
          md={24}
          style={{ maxHeight: 1000, overflow: "scroll" }}
        >
          <Table
            // className={tableDataSource?.length > 0 ? "" : "table-empty"}
            dataSource={loading ? loadingData : tableDataSource}
            columns={loading ? loadingColumns : tableColumns}
            pagination={false}
            onRow={(record) => {
              return {
                onDoubleClick: () => {
                  console.log("on double click row", record);
                },
                onClick: () => {},
              };
            }}
            scroll={{ x: true }}
            onChange={(e) => {}}
            rowClassName={(record, index) => {
              if (record?.key === selectedPage?.page?.pageId)
                return "row-selected";
              return "";
            }}
          />
        </Col>
      </Row>
      {isEditModalVisible !== undefined && (
        <EditPricingModal
          socket={socket}
          student={isEditModalVisible}
          onClose={() => {
            setIsEditModalVisible(undefined);
          }}
          adminRoles={adminUserRoles}
          onAdd={(updatedValues) => {
            const {locations, rates} = updatedValues;
            setIsEditModalVisible({...isEditModalVisible, locations, rates})
            getPricing();
          }}
        />
      )}

<Modal
        title="Add New Pricing"
        visible={isModalVisible}
        // onOk={addService}
        onCancel={() => setIsModalVisible(false)}
        okButtonProps={{ disabled: !newService.trim() }}
        className="beam-modal"
        footer={[]}
      >
        <Form layout="vertical" className="auth-form" onFinish={addService}>
          <Form.Item label="Name" required>
            <Input
              value={newService}
              onChange={(e) => setNewService(e.target.value)}
              placeholder="Enter name"
            />
          </Form.Item>

          <Row className="action-grp mt-3">
            <Col span={24}>
              <Form.Item>
                <Button
                  className="beam-btn green-btn cover w-full"
                  loading={saving}
                  type="primary"
                  htmlType="submit"
                  onClick={() => setError("")}
                >
                  Save
                </Button>
              </Form.Item>
            </Col>
          </Row>
        </Form>
      </Modal>

    </React.Fragment>
  );
};

export default PricingModal;
