import React, { FC, useEffect, useState } from "react";
import {
  Input,
  Button,
  Modal,
  Row,
  Col,
  Collapse,
  DatePicker,
  Tag,
  Checkbox,
  Tabs,
} from "antd";
import _ from "lodash";
import { useDispatch } from "react-redux";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { Form, Select } from "antd";
import { SocketTopics } from "constants/enums";
import LocationInput from "../../../../../common/LocationInput";
import TimeInput from "../../../../../common/TimeInput";
import PhoneInput from "react-phone-number-input";
import { pushNotification } from "utils/notifications";
import { dateToCron, generateUUID, cronToDate } from "utils/appUtil";
import useSocketActions from "../../../../../hooks/socketActions";
import ActionCards from "./TimeSheet";
import LeaveRequest from "./TimeOff";
import ShiftModal from "../Shift/ShiftModal";

import { ExtendedBioTopics, UserTopics } from "constants/enums";
import {
  DeleteOutlined,
  CloseCircleOutlined,
  PlusOutlined,
} from "@ant-design/icons";
import moment, { Moment } from "moment";

const { Panel } = Collapse;
const { TabPane } = Tabs;
interface LocationOption {
  location?: string;
  startTime?: string;
  endTime?: string;
  days?: string[];
  timeWindow?: number | "custom";
  customTimeWindow?: number;
}

interface LocationInputProps {
  value?: LocationOption[];
  keyPrefix?: string;
  onChange?: (locations: LocationOption[]) => void;
}

interface HolidaySelectorProps {
  value?: Moment[];
  onChange?: (dates: Moment[]) => void;
}

const EditDriverModal: FC<{
  onClose: () => void;
  socket?: ISocket;
  student?: any;
  onAdd?: () => void;
  sourceData?: any;
  fullScreen?: boolean;
}> = (props) => {
  const { onClose, socket, student, onAdd, sourceData, fullScreen } = props;
  const [isModalVisible, setIsModalVisible] = useState(true);
  const [selectedTab, setSelectedTab] = useState("1");
  const [registerForm] = Form.useForm();
  const [error, setError] = useState<string>("");
  const { projects } = useSelector((state: RootState) => state.auth);
  const [saving, setSaving] = useState(false);
  const { updateUserRequestPayloadV2 } = useSocketActions();
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth <= 768);

    // Add resize event listener
    window.addEventListener("resize", handleResize);

    // Cleanup listener on unmount
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const handleCancel = () => {
    setIsModalVisible(false);
    onClose && onClose();
  };

  useEffect(() => {
    if (student?.schoolBus) {
      let locationFormValues = {};
      const pickup = [];
      Object.values(student?.schoolBus?.locationList || {})?.map(
        (location: any) => {
          const formattedLocation = {
            location: {
              label: location?.location?.attributes?.address,
              value: {
                description: location?.location?.attributes?.address,
                place_id: "",
                coordinates: location?.location?.coordinates,
                attributes: location?.location?.attributes,
              },
            },
            days: location?.condition?.days,
            startTime: moment(location?.condition?.startTime),
            endTime: moment(location?.condition?.endTime),
          };
          pickup.push(formattedLocation);
          locationFormValues = {
            ...locationFormValues,
            [`location-${pickup.length - 1}`]: formattedLocation.location,
            [`start-time-${pickup.length - 1}`]: formattedLocation.startTime,
            [`end-time-${pickup.length - 1}`]: formattedLocation.endTime,
            [`days-${pickup.length - 1}`]: formattedLocation.days,
          };
        }
      );
      registerForm.setFieldsValue({
        operation: pickup,
        ...locationFormValues,
        license: student?.schoolBus?.license,
        preferences: student?.schoolBus?.preferences,
        ...student?.schoolBus?.license,
        expiryDate: student?.schoolBus?.license?.expiryDate
          ? moment(student?.schoolBus?.license?.expiryDate)
          : undefined,
        ...student?.schoolBus?.preferences,
      });
    }
  }, []);

  const onSubmitHandler = async (values: any) => {
    console.log("values", values);
    let locationList = [
      ...(values?.operation?.map((x) => {
        return {
          locationType: "operationStart",
          location: {
            coordinates: x?.location?.value?.coordinates,
            attributes: x?.location?.value?.attributes,
          },
          condition: {
            days: x?.days,
            startTime: x?.startTime,
            endTime: x?.endTime,
          },
        };
      }) || []),
    ];
    locationList = locationList.reduce((acc, item, index) => {
      const id = generateUUID();
      acc[id] = { locationId: id, ...item };
      return acc;
    }, {} as { [key: string]: any });
    setSaving(true);
    await updateUser(student?.id, projects?.userServiceId, {
      locationList: selectedTab === "1" ? locationList : undefined,
      license:
        selectedTab === "2"
          ? {
              licenseNumber: values?.licenseNumber,
              licenseType: values?.licenseType,
              experience: values?.experience,
              expiryDate: values?.expiryDate?.format("MM/DD/YYYY HH:mm:ss"),
            }
          : undefined,
      preferences:
        selectedTab === "3"
          ? {
              experiencedStretcher: values?.experiencedStretcher,
              trainedInStretchers: values?.trainedInStretchers,
              wheelchairOnly: values?.wheelchairOnly,
              stairChairs: values?.stairChairs,
              overnightOnCall: values?.overnightOnCall,
              preferredPartners: values?.preferredPartners,
              preferenceNotes: values?.preferenceNotes,
            }
          : undefined,
    });
    pushNotification(
      "User updated successfully",
      "success",
      "TOP_CENTER",
      3000
    );
    setSaving(false);
    onAdd();
  };

  const updateUser = async (userId, serviceId, updateData) => {
    return new Promise((resolve, reject) => {
      const { locationList, license, preferences } = updateData;
      const updatedUserData = [];
      if (locationList) {
        updatedUserData.push({
          op: "add",
          path: "/persistent/static/schoolBus/locationList",
          value: locationList,
        });
      }
      if (license) {
        updatedUserData.push({
          op: "add",
          path: "/persistent/static/schoolBus/license",
          value: license,
        });
      }
      if (preferences) {
        updatedUserData.push({
          op: "add",
          path: "/persistent/static/schoolBus/preferences",
          value: preferences,
        });
      }
      console.log("update user data", updatedUserData);

      socket.publishToServiceIdSurvey(
        SocketTopics.SurveyTopics,
        UserTopics.UpdateUser,
        updateUserRequestPayloadV2(userId, updatedUserData),
        ExtendedBioTopics.UpdateUserBio,
        serviceId
      );
      socket.subscribeToSurvey(
        SocketTopics.SurveyTopics,
        ExtendedBioTopics.UpdateUserBio,
        (response) => {
          resolve(response);
        }
      );
    });
  };

  const daysOfWeek = [
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday",
    "Sunday",
  ];

  const DriverLocationInput: React.FC<LocationInputProps> = ({
    value,
    onChange,
  }) => {
    const [options, setOptions] = useState<LocationOption[]>(
      value || [
        {
          location: undefined,
          startTime: undefined,
          endTime: undefined,
          days: undefined,
          timeWindow: 10,
        },
      ]
    );

    useEffect(() => {
      if (value) {
        setOptions(value);
      }
    }, [value]);

    const addLocation = () => {
      setOptions((prevOptions) => [
        ...prevOptions,
        {
          location: undefined,
          startTime: undefined,
          endTime: undefined,
          days: undefined,
          timeWindow: 10,
        },
      ]);
    };

    const deleteLocation = (index: number) => {
      setOptions((prevOptions) => prevOptions.filter((_, i) => i !== index));
    };

    const handleLocationChange = (
      index: number,
      field: keyof LocationOption,
      newValue: any
    ) => {
      const updatedOptions = options.map((option, i) =>
        i === index ? { ...option, [field]: newValue } : option
      );
      // setOptions(updatedOptions);
      onChange?.(updatedOptions);
    };

    const getSelectedDays = (): string[] => {
      return options.reduce<string[]>((selectedDays, option) => {
        return option.days ? [...selectedDays, ...option.days] : selectedDays;
      }, []);
    };

    const LocationTimeInput = (props) => {
      const { value, onChange } = props;
      return (
        <TimeInput
          placeholder={`Select Time`}
          value={value ? moment(value).format("HH:mm") : undefined}
          onChange={onChange}
        />
      );
    };

    return (
      <>
        {options.map((option, index) => {
          const availableDays = daysOfWeek.filter(
            (day) =>
              !getSelectedDays().includes(day) || option.days?.includes(day)
          );
          return (
            <Row className="mb-3" key={`location-${index}`}>
              <Col span={21} className="pr-3">
                <Form.Item
                  label={`Operation start Location`}
                  name={`location-${index}`}
                  rules={[{ required: true, message: "Location is required" }]}
                >
                  <LocationInput
                    placeholder={`Enter Start Location`}
                    onChange={(location) =>
                      handleLocationChange(index, "location", location)
                    }
                  />
                </Form.Item>
              </Col>
              <Col
                span={3}
                className="t-right d-flex justify-content-end align-items-end"
              >
                <Button
                  type="link"
                  className="beam-btn orange-btn bordered"
                  onClick={() => deleteLocation(index)}
                >
                  <DeleteOutlined style={{ color: "#FF5F25" }} />
                </Button>
              </Col>

              <Col span={24} className="mt-3">
                <Form.Item
                  label={`Operation Days`}
                  name={`days-${index}`}
                  rules={[
                    { required: true, message: "Days selection is required" },
                  ]}
                >
                  <Select
                    placeholder={`Select Days`}
                    mode="multiple"
                    value={option.days}
                    onChange={(days) =>
                      handleLocationChange(index, "days", days)
                    }
                    style={{ width: "100%" }}
                  >
                    {availableDays.map((day) => (
                      <Select.Option key={day} value={day}>
                        {day}
                      </Select.Option>
                    ))}
                  </Select>
                </Form.Item>
              </Col>

              <Col span={12} className="mt-3">
                <Form.Item
                  label={`Start Time`}
                  name={`start-time-${index}`}
                  rules={[
                    { required: true, message: "Start time is required" },
                  ]}
                >
                  <LocationTimeInput
                    onChange={(time) => {
                      handleLocationChange(index, "startTime", time);
                    }}
                  />
                </Form.Item>
              </Col>
              <Col span={12} className="mt-3 pl-2">
                <Form.Item
                  label={`End Time`}
                  name={`end-time-${index}`}
                  rules={[{ required: true, message: "End time is required" }]}
                >
                  <LocationTimeInput
                    onChange={(time) => {
                      handleLocationChange(index, "endTime", time);
                    }}
                  />
                </Form.Item>
              </Col>
            </Row>
          );
        })}
        <Row className="mt-3 mb-3">
          <Col span={24} className="d-flex justify-content-end align-items-end">
            <Button
              type="link"
              className="beam-btn yellow-btn bordered"
              onClick={() => addLocation()}
            >
              <span style={{ color: "#FBAE16" }}>Add</span>
            </Button>
          </Col>
        </Row>
      </>
    );
  };

  const DriverLicenseInfo: React.FC<any> = ({ value, onChange }) => {
    const licenseTypes = ["CDL Class A", "CDL Class B", "CDL Class C"];

    return (
      <React.Fragment>
        <Form.Item
          label="License Number"
          name="licenseNumber"
          rules={[
            { required: true, message: "Please input the license number" },
          ]}
        >
          <Input placeholder="Enter license number" />
        </Form.Item>

        <Form.Item
          className="mt-3"
          label="License Type"
          name="licenseType"
          rules={[{ required: true, message: "Please select a license type" }]}
        >
          <Select placeholder="Select license type">
            {licenseTypes.map((type) => (
              <Select.Option key={type} value={type}>
                {type}
              </Select.Option>
            ))}
          </Select>
        </Form.Item>

        <Form.Item
          className="mt-3"
          label="License Expiry Date"
          name="expiryDate"
          rules={[
            {
              required: true,
              message: "Please select the license expiry date",
            },
          ]}
        >
          <DatePicker style={{ width: "100%" }} />
        </Form.Item>

        <Form.Item
          className="mt-3"
          label="Years of Experience"
          name="experience"
          rules={[
            { required: true, message: "Please input years of experience" },
            {
              pattern: /^[0-9]+$/,
              message: "The input must be a number",
            },
          ]}
        >
          <Input
            min={0}
            max={50}
            placeholder="Years of experience"
            style={{ width: "100%" }}
          />
        </Form.Item>
      </React.Fragment>
    );
  };
  const { Option } = Select;

  const AdditionalConstraints: React.FC<any> = ({ value, onChange }) => {
    return (
      <React.Fragment>
        <Form.Item name="experiencedStretcher" valuePropName="checked">
          <Checkbox>Experienced Stretcher Personnel</Checkbox>
        </Form.Item>

        {/* Trained in Stretchers (dependent on Experienced Personnel) */}
        <Form.Item name="trainedInStretchers" valuePropName="checked">
          <Checkbox>
            Trained in Stretchers (must go with Experienced Personnel)
          </Checkbox>
        </Form.Item>

        {/* Wheelchair Only */}
        <Form.Item name="wheelchairOnly" valuePropName="checked">
          <Checkbox>Wheelchair Only</Checkbox>
        </Form.Item>

        {/* Stair Chairs */}
        <Form.Item name="stairChairs" valuePropName="checked">
          <Checkbox>Stair Chairs</Checkbox>
        </Form.Item>

        {/* Potential Overnight On-Call Personnel */}
        <Form.Item name="overnightOnCall" valuePropName="checked">
          <Checkbox>Potential Overnight On-Call Personnel</Checkbox>
        </Form.Item>

        {/* Preferred Partners to Drive With */}
        <Form.Item
          name="preferredPartners"
          label="Preferred Partners to Drive With"
          className="mt-3"
        >
          <Select
            mode="multiple"
            placeholder="Select preferred partners"
            allowClear
            filterOption={(input, option) =>
              (option!.children as unknown as string)
                .toLowerCase()
                .includes(input.toLowerCase())
            }
          >
            {sourceData
              ?.filter((x) => {
                return x.key !== student?.id;
              })
              ?.map((x) => {
                return <Option value={x.key}>{x.name}</Option>;
              })}
          </Select>
        </Form.Item>

        <Form.Item
          name="preferenceNotes"
          label="Preference Notes"
          className="mt-3"
        >
          <Input.TextArea
            autoSize={{ minRows: 4, maxRows: 6 }}
            placeholder="Enter notes"
          />
        </Form.Item>
      </React.Fragment>
    );
  };

  return (
    <React.Fragment>
      {fullScreen ? (
        <Col
          span={24}
          className={
            isMobile
              ? "d-flex flex-column align-items-start"
              : "d-flex justify-content-space-between align-items-space-between"
          }
        >
          <Form
            className={`auth-form ${fullScreen ? "full-width" : ""}`}
            name="register-form"
            id="register-form"
            layout="vertical"
            form={registerForm}
            onFinish={onSubmitHandler}
            requiredMark={false}
          >
            <div className="main-cards mt-3">
              <Tabs
                defaultActiveKey="1"
                type="line"
                onChange={(activeKey) => {
                  setSelectedTab(activeKey);
                }}
              >
                {/* Tab 1 */}
                {/* <TabPane tab="Driver Availability & Operation" key="1">
                  {selectedTab === "1" && (
                    <Form.Item name="vehicle">
                      <Form.Item name="operation">
                        <DriverLocationInput />
                      </Form.Item>
                    </Form.Item>
                  )}
                </TabPane> */}

                <TabPane tab="Clock In/out" key="1">
                  {selectedTab === "1" && (
                    <ActionCards socket={socket} userId={student?.id} />
                  )}
                </TabPane>

                <TabPane tab="Shift" key="2">
                  <Form.Item name="shift">
                    {selectedTab === "2" && (
                      <ShiftModal socket={socket} userId={student?.id} />
                    )}
                  </Form.Item>
                </TabPane>


                <TabPane tab="Timeoff" key="3">
                  {selectedTab === "3" && (
                    <LeaveRequest socket={socket} userId={student?.id} />
                  )}
                </TabPane>


                {/* Tab 2 */}

{!fullScreen && (
                <React.Fragment>
                  <TabPane tab="Driver License" key="4">
                    {selectedTab === "4" && (
                      <Form.Item name="license">
                        <DriverLicenseInfo />
                      </Form.Item>
                    )}
                  </TabPane>

                  {/* Tab 3 */}
                  <TabPane tab="Preferences" key="5">
                    <Form.Item name="preferences">
                      {selectedTab === "5" && <AdditionalConstraints />}
                    </Form.Item>
                  </TabPane>
                </React.Fragment>
                )}

                {/* <TabPane tab="Shift" key="4">
                  <Form.Item name="shift">
                    {selectedTab === "6" && (
                      <ShiftModal socket={socket} userId={student?.id} />
                    )}
                  </Form.Item>
                </TabPane> */}

                {/* <TabPane tab="Clock In/out" key="4">
                  {selectedTab === "4" && (
                    <ActionCards socket={socket} userId={student?.id} />
                  )}
                </TabPane> */}

                
              </Tabs>
            </div>

            {selectedTab !== "1" &&
              selectedTab !== "2" &&
              selectedTab !== "3" && (
                <Row
                  className="action-grp mt-3"
                  // style={
                  //   fullScreen
                  //     ? { position: "fixed", bottom: 30, width: "calc(100% - 60px)" }
                  //     : {}
                  // }
                >
                  <Col span={24}>
                    <Form.Item>
                      <Button
                        className="beam-btn green-btn cover w-full"
                        loading={saving}
                        type="primary"
                        htmlType="submit"
                        onClick={() => setError("")}
                      >
                        Save
                      </Button>
                    </Form.Item>
                  </Col>
                </Row>
              )}
          </Form>
        </Col>
      ) : (
        <Modal
          title={`Edit (${student?.live?.beamIds?.[0] || "student"})`}
          visible={fullScreen ? true : isModalVisible}
          onCancel={handleCancel}
          width={fullScreen ? "100vw" : "800px"}
          className={`beam-modal ${
            fullScreen ? "analytics-summary-modal" : ""
          }`}
          bodyStyle={{
            height: "100vh",
            overflow: "auto",
          }}
          style={{
            height: "100vh",
            margin: fullScreen ? 0 : undefined,
          }}
          footer={[]}
          destroyOnClose={true}
          closable={!fullScreen}
        >
          <Form
            className={`auth-form ${fullScreen ? "full-width" : ""}`}
            name="register-form"
            id="register-form"
            layout="vertical"
            form={registerForm}
            onFinish={onSubmitHandler}
            requiredMark={false}
          >
            <div className="main-cards mt-3">
              <Tabs
                defaultActiveKey="1"
                type="line"
                onChange={(activeKey) => {
                  setSelectedTab(activeKey);
                }}
              >
                {/* Tab 1 */}
                <TabPane tab="Driver Availability & Operation" key="1">
                  {selectedTab === "1" && (
                    <Form.Item name="vehicle">
                      <Form.Item name="operation">
                        <DriverLocationInput />
                      </Form.Item>
                    </Form.Item>
                  )}
                </TabPane>

                {/* Tab 2 */}
                <TabPane tab="Driver License" key="2">
                  {selectedTab === "2" && (
                    <Form.Item name="license">
                      <DriverLicenseInfo />
                    </Form.Item>
                  )}
                </TabPane>

                {/* Tab 3 */}
                <TabPane tab="Preferences" key="3">
                  <Form.Item name="preferences">
                    {selectedTab === "3" && <AdditionalConstraints />}
                  </Form.Item>
                </TabPane>

                <TabPane tab="Shift" key="6">
                  {selectedTab === "6" && (
                    <ShiftModal socket={socket} userId={student?.id} />
                  )}
                </TabPane>

                <TabPane tab="Clock In/out" key="4">
                  {selectedTab === "4" && (
                    <ActionCards socket={socket} userId={student?.id} />
                  )}
                </TabPane>

                <TabPane tab="Timeoff" key="5">
                  {selectedTab === "5" && (
                    <LeaveRequest socket={socket} userId={student?.id} />
                  )}
                </TabPane>
              </Tabs>
            </div>

            {selectedTab !== "4" &&
              selectedTab !== "5" &&
              selectedTab !== "6" && (
                <Row
                  className="action-grp mt-3"
                  // style={
                  //   fullScreen
                  //     ? { position: "fixed", bottom: 30, width: "calc(100% - 60px)" }
                  //     : {}
                  // }
                >
                  <Col span={24}>
                    <Form.Item>
                      <Button
                        className="beam-btn green-btn cover w-full"
                        loading={saving}
                        type="primary"
                        htmlType="submit"
                        onClick={() => setError("")}
                      >
                        Save
                      </Button>
                    </Form.Item>
                  </Col>
                </Row>
              )}
          </Form>
        </Modal>
      )}
    </React.Fragment>
  );
};

export default EditDriverModal;
