const generateInitialData = (
  services: string[],
  locations: LocationData[]
): any[] => {
  let keyCounter = 1;

  return services.flatMap((service) => {
    const rateTypes = {
      "Hulpr Wheelchair": ["Flat Rate"],
      "Hulpr Broda": ["Flat Rate"],
      Overnight: ["Overnight/Holiday multiplier"],
      Oxygen: ["Oxygen (per L/min)"],
      Tax: ["%"],
    };

    const types = rateTypes[service] || ["Base Rate", "KM Rate", "Wait Time"];

    return types.map((type) => ({
      key: `${keyCounter++}`,
      service,
      type,
      ...Object.fromEntries(locations.map((loc) => [loc.name, 0])),
    }));
  });
};

