import React from "react";
import { Row, Col, Select, Form } from "antd";
import { useDispatchPanel } from "../context";

const AccountSection: React.FC = () => {
  const { encrypted_token, webBooker, accounts } = useDispatchPanel();

  if (!(encrypted_token && !webBooker)) return null;

  return (
    <React.Fragment>
      <Row className="mt-3">
        <Col span={24}>
          <Form.Item name="account">
            <Select
              showSearch
              className="w-full"
              placeholder="Account name"
              onChange={(value) => {}}
              filterOption={(input, option) =>
                (option!.children as unknown as string)
                  .toLowerCase()
                  .includes(input.toLowerCase())
              }
            >
              {accounts?.map((account: any, index: number) => (
                <Select.Option value={account.objectId?.toString()}>
                  {account.info.name}
                </Select.Option>
              ))}
            </Select>
          </Form.Item>
        </Col>
      </Row>
      <hr />
    </React.Fragment>
  );
};

export default AccountSection;
