  const fetchAllCustomers = () => {
    if (!projects?.userServiceId) return;

    const customerRequest: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:custom:id`,
          searchQuery: `@partitions:{'org\\:${formatForRedis(
            projects?.userServiceId
          )}'}`,
          searchOptions: "TIMEOUT 10000",
        },
        load: {
          id: "$..info.id",
          objectId: "$.objectId",
          adults: "$..info.customer.eighteenTo65YearsOldMembers",
          income: "$..info.customer.houseHoldIncome",
          tanFEligibility: "$..info.customer.tanFEligibility",
          dependants: "$..info.customer.seventeenYearsOldMembers",
        },
      },
      filter: {
        expression: "exists(@id)",
      },
    };

    dispatch(
      GET_AGGREGATE({
        requestData: customerRequest,
        callback: (response) => {
          const customersMap: any = {};
          response?.forEach((customer) => {
            if (customer?.id) {
              const dependants = parseInt(customer.dependants || "0", 10);
              const adults = parseInt(customer.adults || "0", 10);
              const maxAdults = Math.min(adults, 2); // Max 2 adults count toward household size
              const householdSize = dependants + maxAdults;

              customersMap[customer.id] = {
                adults: customer.adults || 0,
                income: customer.income || "N/A",
                tanFEligibility: customer.tanFEligibility || "N/A",
                dependants: customer.dependants || 0,
                householdSize: householdSize,
              };
            }
          });
          setCustomers(customersMap);
          customersRef.current = customersMap;
        },
      })
    );
  };

