import React, { FC, useState, useEffect, useMemo } from "react";
import { Row, Col, Card, Spin, Button, DatePicker } from "antd";
import { DownOutlined, PlusOutlined, ClearOutlined } from "@ant-design/icons";
import moment from "moment";
import { useLocation } from "react-router-dom";
import { useSelector, useDispatch } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { GET_AGGREGATE } from "reducers/reducer";
import { formatForRedis } from "utils/appUtil";
import NumberInput from "../../../../common/NumberInput";
import useSocketActions from "../../../../hooks/socketActions";
import { ExtendedBioTopics, SocketTopics, UserTopics } from "../../../../constants/enums";
import { PieChart } from "react-minimal-pie-chart";
import "./LighthouseDashboard.scss";

// TypeScript interfaces for configuration
interface ServiceImage {
    id: string;
    url: string;
}

interface ServiceConfig {
    name: string;
    projectIds: string[];
    image: ServiceImage;
}

interface CategoryConfig {
    name: string;
    services: ServiceConfig[];
}

interface BuildingConfig {
    name: string;
    title: string;
    categories: CategoryConfig[];
    includeStats?: boolean;
}

interface ReportConfig {
    type: string;
    buildings: BuildingConfig[];
    title: string;
}

interface ReportConfigResponse {
    reportConfig: ReportConfig[];
}

interface LighthouseDashboardProps {
    socket: ISocket;
}

interface ServiceData {
    total: number;
    eligibleCount: number;
    percentage: number;
}

interface CenterData {
    name: string;
    subtitle: string;
    services: {
        [key: string]: ServiceData;
    };
}

const LighthouseDashboard: FC<LighthouseDashboardProps> = ({ socket }) => {
    const { search } = useLocation();
    const dispatch = useDispatch();
    const { encrypted_token } = useSelector((state: RootState) => state.auth);
    const { getUserRequestPayload } = useSocketActions();

    // Extract mode from URL (tanF, veteran, etc.)
    const mode = useMemo(() => {
        const query = new URLSearchParams(search);
        return query.get("mode") || "tanF"; // Default to tanF for backward compatibility
    }, [search]);

    // State management
    const [loading, setLoading] = useState(true);
    const [dateFilter, setDateFilter] = useState<string>("lastMonth");
    const [customDateRange, setCustomDateRangeState] = useState<any>({
        startDate: undefined,
        endDate: undefined
    });
    const [dateFilterLoading, setDateFilterLoading] = useState<boolean>(false);
    const [pages, setPages] = useState<any[]>([]);
    const [pagesLoading, setPagesLoading] = useState<boolean>(false);
    const [customers, setCustomers] = useState<any[]>([]);
    const [customersLoading, setCustomersLoading] = useState<boolean>(false);
    const [configUserId, setConfigUserId] = useState<string>("");
    const [cudbServiceId, setCudbServiceId] = useState<string>("");
    const [reportConfig, setReportConfig] = useState<ReportConfig | null>(null);
    const [projects, setProjects] = useState<any[]>([]);
    const [configLoading, setConfigLoading] = useState<boolean>(false);
    const [isDataReady, setIsDataReady] = useState<boolean>(false);
    const [loadingTimeout, setLoadingTimeout] = useState<boolean>(false);
    const [chartLoading, setChartLoading] = useState<boolean>(false);
    const [showManualInput, setShowManualInput] = useState<boolean>(false);

    // Dynamic stats based on configuration
    const [overallStats, setOverallStats] = useState<{
        totalServices: number;
        eligibleServices: number;
        nonEligibleServices: number;
        eligiblePercentage: number;
        lastUpdated: Date | null;
    }>({
        totalServices: 0,
        eligibleServices: 0,
        nonEligibleServices: 0,
        eligiblePercentage: 0,
        lastUpdated: null,
    });

    // Dynamic service stats based on configuration
    const [serviceStats, setServiceStats] = useState<{
        [buildingName: string]: {
            [categoryName: string]: {
                [serviceName: string]: ServiceData;
            };
        };
    }>({});

    // Dynamic manual inputs based on configuration
    const [manualInputs, setManualInputs] = useState<{ [serviceKey: string]: number }>({});

    // Building-level manual inputs (adds to total, non-eligible count)
    const [buildingManualInputs, setBuildingManualInputs] = useState<{ [buildingName: string]: number }>({});

    // Extract configUserId and cudbServiceId from URL parameters
    useEffect(() => {
        const query = new URLSearchParams(search);
        const userId = query.get("configUserId");
        const serviceId = query.get("cudbServiceId");
        if (userId) {
            setConfigUserId(userId);
        }
        if (serviceId) {
            setCudbServiceId(serviceId);
        }
    }, [search]);

    // Fetch report configuration and projects when configUserId is available
    useEffect(() => {
        if (configUserId && cudbServiceId && socket?.client) {
            fetchReportConfig();
            fetchProjects();
        }
    }, [configUserId, cudbServiceId, mode, socket?.client]);

    // Fetch pages when configUserId is available
    useEffect(() => {
        if (configUserId) {
            getPageData();
        }
    }, [configUserId]);

    // Fetch customers when cudbServiceId is available
    useEffect(() => {
        if (cudbServiceId) {
            getCustomers();
        }
    }, [cudbServiceId]);

    // Initialize manual inputs when config changes
    useEffect(() => {
        if (reportConfig) {
            const initialInputs: { [key: string]: number } = {};
            const initialBuildingInputs: { [key: string]: number } = {};

            reportConfig.buildings.forEach(building => {
                // Initialize building-level inputs
                initialBuildingInputs[building.name] = 0;

                building.categories.forEach(category => {
                    category.services.forEach(service => {
                        const serviceKey = getServiceKey(building.name, category.name, service.name);
                        initialInputs[serviceKey] = 0;
                    });
                });
            });
            setManualInputs(initialInputs);
            setBuildingManualInputs(initialBuildingInputs);
        }
    }, [reportConfig]);

    // Calculate stats when pages, customers, or config changes
    useEffect(() => {
        if (pages.length > 0 && customers.length > 0 && reportConfig) {
            calculateStats(pages, customers, reportConfig);
            setIsDataReady(true);
        } else if (!pagesLoading && !customersLoading && !configLoading) {
            setIsDataReady(true);
        } else {
            setIsDataReady(false);
        }
    }, [pages, customers, reportConfig, pagesLoading, customersLoading, configLoading]);

    // Recalculate stats when manual inputs change
    useEffect(() => {
        if (pages.length > 0 && customers.length > 0 && reportConfig && isDataReady) {
            calculateStats(pages, customers, reportConfig);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [manualInputs, buildingManualInputs]);

    useEffect(() => {
        const timer = setTimeout(() => {
            setLoading(false);
        }, 1000);
        return () => clearTimeout(timer);
    }, []);

    // Timeout fallback - show dashboard after 10 seconds even if data isn't loaded
    useEffect(() => {
        const timeoutTimer = setTimeout(() => {
            setLoadingTimeout(true);
            setIsDataReady(true);
        }, 10000);
        return () => clearTimeout(timeoutTimer);
    }, []);

    // Fetch report configuration from admin path
    const fetchReportConfig = () => {
        if (!configUserId || !cudbServiceId) return;

        setConfigLoading(true);
        socket.publishToServiceIdSurvey(
            SocketTopics.SurveyTopics,
            UserTopics.SearchInUser,
            getUserRequestPayload(
                configUserId,
                "$",
                "$.persistent.static.admin.reportManagement"
            ),
            ExtendedBioTopics.GetReportManagementBio,
            cudbServiceId
        );

        socket.subscribeToSurvey(
            SocketTopics.SurveyTopics,
            ExtendedBioTopics.GetReportManagementBio,
            (resp) => {
                try {
                    const reportConfigData: ReportConfigResponse = resp?.data?.[0]?.[0] || {};
                    const configs = reportConfigData.reportConfig || [];

                    // Find config for current mode
                    const configForMode = configs.find(c => c.type.toLowerCase() === mode.toLowerCase());

                    if (configForMode) {
                        setReportConfig(configForMode);
                        console.log("Report config loaded for mode:", mode, configForMode);
                    } else {
                        console.warn(`No configuration found for mode: ${mode}`);
                        // Fallback to first config if mode not found
                        if (configs.length > 0) {
                            setReportConfig(configs[0]);
                        }
                    }
                } catch (error) {
                    console.error("Error parsing report config:", error);
                } finally {
                    setConfigLoading(false);
                }
            }
        );
    };

    // Fetch projects from admin path
    const fetchProjects = () => {
        if (!configUserId || !cudbServiceId) return;

        socket.publishToServiceIdSurvey(
            SocketTopics.SurveyTopics,
            UserTopics.SearchInUser,
            getUserRequestPayload(
                configUserId,
                "$",
                "$.persistent.static.admin.project"
            ),
            ExtendedBioTopics.GetUserBio,
            cudbServiceId
        );

        socket.subscribeToSurvey(
            SocketTopics.SurveyTopics,
            ExtendedBioTopics.GetUserBio,
            (resp) => {
                try {
                    const respProjects = Object.values(resp?.data?.[0]?.[0]?.items || {}) || [];
                    setProjects(respProjects);
                    console.log("Projects loaded:", respProjects.length);
                } catch (error) {
                    console.error("Error parsing projects:", error);
                }
            }
        );
    };

    // Get service key for manual inputs
    const getServiceKey = (buildingName: string, categoryName: string, serviceName: string): string => {
        return `${buildingName}_${categoryName}_${serviceName}`.replace(/\s+/g, '_').toLowerCase();
    };

    // Check if customer is eligible based on mode
    const isEligible = (customer: any): boolean => {
        if (!customer?.info?.customer) {
            return false;
        }

        switch (mode.toLowerCase()) {
            case 'tanf':
                return customer?.info?.customer?.tanFEligibility?.toLowerCase() === 'yes';
            case 'veteran':
                return customer?.info?.customer?.currentStatus?.includes('Veteran');
            default:
                // For other modes, check if there's a corresponding field
                const fieldName = `${mode}Eligibility` || `${mode}Status`;
                return customer?.info?.customer?.[fieldName]?.toLowerCase() === 'yes';
        }
    };

    // Create customer lookup map
    const createCustomerLookupMap = (customers: any[]): Map<string, any> => {
        const customerMap = new Map<string, any>();
        customers.forEach(customer => {
            if (customer?.id) {
                customerMap.set(customer.id, customer);
            }
        });
        return customerMap;
    };

    // Create project lookup map
    const createProjectLookupMap = (projects: any[]): Map<string, any> => {
        const projectMap = new Map<string, any>();
        projects.forEach(project => {
            if (project?._id) {
                projectMap.set(project._id, project);
            }
        });
        return projectMap;
    };

    // Helper function to extract projectId from page (handles both single value and array)
    const getPageProjectIds = (page: any): string[] => {
        // Try multiple paths for projectId
        const projectId = page?.static?.profile?.projectId || page?.projectId;

        // Handle array case
        if (Array.isArray(projectId)) {
            return projectId.filter(id => id != null && id !== '');
        }

        // Handle single value
        if (projectId != null && projectId !== '') {
            return [projectId];
        }

        return [];
    };

    // Helper function to extract buildingName from page
    const getPageBuildingName = (page: any): string | null => {
        const buildingName = page?.static?.profile?.buildingName || page?.buildingName;
        return buildingName != null && buildingName !== '' ? buildingName : null;
    };

    // Calculate statistics based on configuration
    const calculateStats = (pages: any[], customers: any[], config: ReportConfig) => {
        if (!pages.length || !customers.length || !config) {
            resetStats(config);
            return;
        }

        const customerMap = createCustomerLookupMap(customers);

        // Initialize stats structure
        const stats: {
            [buildingName: string]: {
                [categoryName: string]: {
                    [serviceName: string]: ServiceData;
                };
            };
        } = {};

        let totalServices = 0;
        let eligibleServices = 0;
        let nonEligibleServices = 0;

        // Initialize stats from config
        config.buildings.forEach(building => {
            stats[building.name] = {};
            building.categories.forEach(category => {
                stats[building.name][category.name] = {};
                category.services.forEach(service => {
                    stats[building.name][category.name][service.name] = {
                        total: 0,
                        eligibleCount: 0,
                        percentage: 0
                    };
                });
            });
        });

        console.log("=== STARTING STATS CALCULATION ===");
        console.log(`Total pages: ${pages.length}`);
        console.log(`Total customers: ${customers.length}`);
        console.log(`Mode: ${mode}`);

        // Log pages that have buildingName
        const pagesWithBuildingName = pages
            .map((page, index) => {
                const buildingName = getPageBuildingName(page);
                const pageProjectIds = getPageProjectIds(page);
                const customerId = page?.static?.profile?.customerId || page?.customerId;
                return buildingName ? { index, buildingName, pageProjectIds, customerId } : null;
            })
            .filter(Boolean);

        if (pagesWithBuildingName.length > 0) {
            console.log(`\n📋 Pages with buildingName (${pagesWithBuildingName.length} total):`);
            pagesWithBuildingName.forEach((pageInfo: any) => {
                console.log(`   Page ${pageInfo.index}: buildingName="${pageInfo.buildingName}", projectIds=[${pageInfo.pageProjectIds.join(', ')}], customerId=${pageInfo.customerId || 'N/A'}`);
            });
        } else {
            console.log(`\n⚠️  No pages have buildingName property`);
        }

        // Process each service in the configuration
        config.buildings.forEach(building => {
            building.categories.forEach(category => {
                category.services.forEach(service => {
                    // Get projectIds for this service
                    const serviceProjectIds = service.projectIds || [];

                    if (serviceProjectIds.length === 0) {
                        // No projectIds configured for this service, skip
                        console.log(`\n❌ Service "${service.name}" (${building.name} > ${category.name}) has no projectIds configured`);
                        return;
                    }

                    console.log(`\n📊 Processing Service: "${service.name}"`);
                    console.log(`   Building: ${building.name}`);
                    console.log(`   Category: ${category.name}`);
                    console.log(`   Service ProjectIds: [${serviceProjectIds.join(', ')}]`);
                    console.log(`   Building includeStats: ${building.includeStats ? 'true' : 'false'}`);
                    if (!building.includeStats) {
                        console.log(`   📌 Building name filter: Will accept pages with NO buildingName OR buildingName="${building.name}"`);
                    } else {
                        console.log(`   📌 Building name filter: Will ONLY accept pages with buildingName="${building.name}"`);
                    }

                    let serviceTotal = 0;
                    let serviceEligible = 0;
                    let serviceNonEligible = 0;
                    const matchingPages: any[] = [];

                    // Find all pages that match this service's projectIds
                    let pagesWithoutCustomerId = 0;
                    let pagesWithoutMatchingProjectId = 0;
                    let pagesWithoutMatchingBuildingName = 0;

                    pages.forEach((page, pageIndex) => {
                        const pageProjectIds = getPageProjectIds(page);
                        const customerId = page?.static?.profile?.customerId || page?.customerId;
                        const pageBuildingName = getPageBuildingName(page);

                        // Check if this page's projectId matches any of the service's projectIds
                        const hasMatchingProjectId = pageProjectIds.length > 0 && pageProjectIds.some(pageProjectId =>
                            serviceProjectIds.includes(pageProjectId)
                        );

                        // Building name matching logic:
                        // - If includeStats is true: only accept pages with matching buildingName
                        // - If includeStats is false: accept pages without buildingName OR with matching buildingName
                        //   (This prevents pages with different buildingName from being counted)
                        const hasMatchingBuildingName = building.includeStats
                            ? pageBuildingName && pageBuildingName === building.name
                            : !pageBuildingName || pageBuildingName === building.name; // Accept null/undefined or matching buildingName

                        if (hasMatchingProjectId && hasMatchingBuildingName && customerId) {
                            const customer = customerMap.get(customerId);
                            const isEligibleCustomer = customer && isEligible(customer);

                            // This page matches this service
                            stats[building.name][category.name][service.name].total++;
                            totalServices++;
                            serviceTotal++;

                            matchingPages.push({
                                pageIndex,
                                pageProjectIds,
                                pageBuildingName,
                                customerId,
                                isEligible: isEligibleCustomer,
                                customerFound: !!customer,
                                customerTanFEligibility: customer?.info?.customer?.tanFEligibility,
                                customerVeteranStatus: customer?.info?.customer?.currentStatus?.includes('Veteran') ? 'Yes' : 'No'
                            });

                            if (isEligibleCustomer) {
                                stats[building.name][category.name][service.name].eligibleCount++;
                                eligibleServices++;
                                serviceEligible++;
                            } else {
                                nonEligibleServices++;
                                serviceNonEligible++;
                            }
                        } else {
                            // Track pages that don't match for debugging
                            if (hasMatchingProjectId && hasMatchingBuildingName && !customerId) {
                                pagesWithoutCustomerId++;
                            }
                            if (!hasMatchingProjectId && customerId) {
                                pagesWithoutMatchingProjectId++;
                            }
                            // Track pages that don't match buildingName (for both includeStats true and false cases)
                            if (hasMatchingProjectId && !hasMatchingBuildingName) {
                                pagesWithoutMatchingBuildingName++;
                            }
                        }
                    });

                    if (pagesWithoutCustomerId > 0) {
                        console.log(`   ⚠️  ${pagesWithoutCustomerId} page(s) matched projectIds but have no customerId`);
                    }
                    if (pagesWithoutMatchingProjectId > 0 && matchingPages.length === 0) {
                        console.log(`   ⚠️  ${pagesWithoutMatchingProjectId} page(s) have customerId but projectIds don't match`);
                    }
                    if (pagesWithoutMatchingBuildingName > 0) {
                        if (building.includeStats) {
                            console.log(`   ⚠️  ${pagesWithoutMatchingBuildingName} page(s) matched projectIds but buildingName doesn't match "${building.name}"`);
                        } else {
                            console.log(`   ⚠️  ${pagesWithoutMatchingBuildingName} page(s) matched projectIds but have a different buildingName (not null/undefined and not "${building.name}")`);
                        }
                    }

                    // Log service-specific stats
                    console.log(`   ✅ Total pages matched: ${serviceTotal}`);
                    console.log(`   ✅ Eligible (${mode.toUpperCase()}): ${serviceEligible}`);
                    console.log(`   ❌ Non-eligible: ${serviceNonEligible}`);
                    console.log(`   📈 Percentage: ${serviceTotal > 0 ? ((serviceEligible / serviceTotal) * 100).toFixed(2) : 0}%`);

                    if (matchingPages.length > 0) {
                        console.log(`   📄 Matching pages details:`);
                        matchingPages.forEach((mp, idx) => {
                            const buildingNameInfo = building.includeStats ? `, buildingName=${mp.pageBuildingName || 'N/A'}` : '';
                            console.log(`      Page ${idx + 1}: projectIds=[${mp.pageProjectIds.join(', ')}]${buildingNameInfo}, customerId=${mp.customerId}, eligible=${mp.isEligible}, customerFound=${mp.customerFound}`);
                        });
                    } else {
                        console.log(`   ⚠️  No pages matched for this service`);
                    }
                });
            });
        });

        console.log("\n=== OVERALL STATS SUMMARY ===");
        console.log(`Total Services: ${totalServices}`);
        console.log(`Eligible Services (${mode.toUpperCase()}): ${eligibleServices}`);
        console.log(`Non-Eligible Services: ${nonEligibleServices}`);
        console.log(`Overall Percentage: ${totalServices > 0 ? ((eligibleServices / totalServices) * 100).toFixed(2) : 0}%`);
        console.log("\n=== DETAILED STATS BY BUILDING ===");

        Object.keys(stats).forEach(buildingName => {
            console.log(`\n🏢 Building: ${buildingName}`);
            Object.keys(stats[buildingName]).forEach(categoryName => {
                console.log(`   📁 Category: ${categoryName}`);
                Object.keys(stats[buildingName][categoryName]).forEach(serviceName => {
                    const serviceData = stats[buildingName][categoryName][serviceName];
                    console.log(`      🔧 Service: ${serviceName}`);
                    console.log(`         Total: ${serviceData.total}, Eligible: ${serviceData.eligibleCount}, Percentage: ${serviceData.percentage}%`);
                });
            });
        });

        console.log("\n=== STATS CALCULATION COMPLETE ===");

        // Add service-level manual inputs
        const manualInputsCount = Object.values(manualInputs).filter(v => v > 0).length;
        if (manualInputsCount > 0) {
            console.log("\n=== SERVICE-LEVEL MANUAL INPUTS ===");
            console.log(`Adding ${manualInputsCount} service-level manual input(s)`);
        }

        Object.entries(manualInputs).forEach(([serviceKey, value]) => {
            if (value > 0) {
                // Parse the service key by finding matching building/category/service
                // The key format is: buildingName_categoryName_serviceName (normalized)
                let found = false;

                for (const building of config.buildings) {
                    const normalizedBuildingName = building.name.replace(/\s+/g, '_').toLowerCase();

                    // Check if serviceKey starts with this building's normalized name
                    if (serviceKey.startsWith(normalizedBuildingName + '_')) {
                        const remainingKey = serviceKey.substring(normalizedBuildingName.length + 1);

                        for (const category of building.categories) {
                            const normalizedCategoryName = category.name.replace(/\s+/g, '_').toLowerCase();

                            // Check if remaining key starts with this category's normalized name
                            if (remainingKey.startsWith(normalizedCategoryName + '_')) {
                                const normalizedServiceName = remainingKey.substring(normalizedCategoryName.length + 1);

                                for (const service of category.services) {
                                    const normalizedService = service.name.replace(/\s+/g, '_').toLowerCase();

                                    if (normalizedService === normalizedServiceName) {
                                        // Found the matching service
                                        console.log(`   ➕ Service manual input: ${service.name} (${building.name} > ${category.name}) = ${value} (all counted as eligible)`);
                                        stats[building.name][category.name][service.name].total += value;
                                        stats[building.name][category.name][service.name].eligibleCount += value;
                                        totalServices += value;
                                        eligibleServices += value;
                                        found = true;
                                        break;
                                    }
                                }
                                if (found) break;
                            }
                        }
                        if (found) break;
                    }
                }

                if (!found) {
                    console.log(`   ⚠️  Could not find service for manual input key: ${serviceKey}`);
                }
            }
        });

        // Note: Building-level manual inputs are NOT added here to avoid affecting service-level data
        // They are applied only in the centersData useMemo when calculating building percentages

        // Calculate percentages - each service percentage should be out of category eligible total (TANF eligible)
        console.log("\n=== CALCULATING PERCENTAGES ===");
        Object.keys(stats).forEach(buildingName => {
            Object.keys(stats[buildingName]).forEach(categoryName => {
                // First, calculate the category eligible total (sum of all eligibleCounts in this category)
                const categoryEligibleTotal = Object.values(stats[buildingName][categoryName]).reduce(
                    (sum, serviceData) => sum + serviceData.eligibleCount,
                    0
                );

                console.log(`\n📊 Category: ${categoryName} (Building: ${buildingName})`);
                console.log(`   Category Eligible Total (${mode.toUpperCase()}): ${categoryEligibleTotal}`);

                // Then calculate each service's percentage out of the category eligible total
                Object.keys(stats[buildingName][categoryName]).forEach(serviceName => {
                    const serviceData = stats[buildingName][categoryName][serviceName];
                    const calculatedPercentage = categoryEligibleTotal > 0
                        ? parseFloat(((serviceData.eligibleCount / categoryEligibleTotal) * 100).toFixed(2))
                        : 0;

                    serviceData.percentage = calculatedPercentage;

                    console.log(`   Service: ${serviceName}`);
                    console.log(`      Total: ${serviceData.total}, Eligible: ${serviceData.eligibleCount}`);
                    console.log(`      Calculation: (${serviceData.eligibleCount} / ${categoryEligibleTotal}) * 100 = ${calculatedPercentage}%`);
                });
            });
        });

        const eligiblePercentage = totalServices > 0
            ? parseFloat(((eligibleServices / totalServices) * 100).toFixed(2))
            : 0;

        console.log("\n=== FINAL STATS (After Manual Inputs) ===");
        console.log(`Total Services: ${totalServices}`);
        console.log(`Eligible Services (${mode.toUpperCase()}): ${eligibleServices}`);
        console.log(`Non-Eligible Services: ${nonEligibleServices}`);
        console.log(`Overall Percentage: ${eligiblePercentage}%`);
        console.log("\n=== END OF STATS CALCULATION ===\n");

        setServiceStats(stats);
        setOverallStats({
            totalServices,
            eligibleServices,
            nonEligibleServices,
            eligiblePercentage,
            lastUpdated: new Date(),
        });
    };

    // Reset stats to initial state
    const resetStats = (config: ReportConfig | null) => {
        if (!config) {
            setServiceStats({});
            setOverallStats({
                totalServices: 0,
                eligibleServices: 0,
                nonEligibleServices: 0,
                eligiblePercentage: 0,
                lastUpdated: null,
            });
            return;
        }

        const stats: {
            [buildingName: string]: {
                [categoryName: string]: {
                    [serviceName: string]: ServiceData;
                };
            };
        } = {};

        config.buildings.forEach(building => {
            stats[building.name] = {};
            building.categories.forEach(category => {
                stats[building.name][category.name] = {};
                category.services.forEach(service => {
                    stats[building.name][category.name][service.name] = {
                        total: 0,
                        eligibleCount: 0,
                        percentage: 0
                    };
                });
            });
        });

        setServiceStats(stats);
        setOverallStats({
            totalServices: 0,
            eligibleServices: 0,
            nonEligibleServices: 0,
            eligiblePercentage: 0,
            lastUpdated: null,
        });
    };

    // Format percentage
    const formatPercentage = (value: number): string => {
        if (value % 1 === 0) {
            return value.toString();
        }
        return value.toFixed(2);
    };

    // Build centers data from configuration and stats
    const centersData: CenterData[] = useMemo(() => {
        if (!reportConfig) return [];

        console.log("\n=== CALCULATING BUILDING PERCENTAGES (centersData) ===");

        return reportConfig.buildings.map(building => {
            // Calculate building total and eligible count from service stats
            let buildingTotal = 0;
            let buildingEligible = 0;

            const buildingServices: { [key: string]: ServiceData } = {};

            building.categories.forEach(category => {
                category.services.forEach(service => {
                    const serviceData = serviceStats[building.name]?.[category.name]?.[service.name] || {
                        total: 0,
                        eligibleCount: 0,
                        percentage: 0
                    };
                    buildingTotal += serviceData.total;
                    buildingEligible += serviceData.eligibleCount;
                    buildingServices[service.name] = serviceData;
                });
            });

            // Apply building-level manual inputs (affects building percentage only, not service-level data)
            const buildingManualInput = buildingManualInputs[building.name] || 0;
            if (buildingManualInput > 0) {
                console.log(`   ➕ Building manual input: ${building.name} = ${buildingManualInput} (all counted as eligible, increases building percentage)`);
                buildingTotal += buildingManualInput;
                buildingEligible += buildingManualInput;
            }

            const buildingPercentage = buildingTotal > 0
                ? parseFloat(((buildingEligible / buildingTotal) * 100).toFixed(2))
                : 0;

            console.log(`\n🏢 Building: ${building.name}`);
            console.log(`   Building Total (from services): ${buildingTotal - buildingManualInput}`);
            if (buildingManualInput > 0) {
                console.log(`   Building Manual Input: ${buildingManualInput}`);
            }
            console.log(`   Building Total (with manual input): ${buildingTotal}`);
            console.log(`   Building Eligible (${mode.toUpperCase()}): ${buildingEligible}`);
            console.log(`   Building Percentage Calculation: (${buildingEligible} / ${buildingTotal}) * 100 = ${buildingPercentage}%`);
            console.log(`   Building Title: ${building.title}`);

            return {
                name: building.name,
                subtitle: `${formatPercentage(buildingPercentage)}% ${building.title}`,
                services: buildingServices
            };
        });
    }, [reportConfig, serviceStats, buildingManualInputs, mode]);

    // Date filter handlers
    const handleDateFilter = (type: string) => {
        if (dateFilter === type) return;
        setDateFilter(type);
        setDateFilterLoading(true);
        setChartLoading(true);

        const now = moment();
        let startTimestamp: number | undefined;
        let endTimestamp: number = now.valueOf();

        switch (type) {
            case "last24hours":
                startTimestamp = undefined;
                break;
            case "lastWeek":
                startTimestamp = now.subtract(1, "week").valueOf();
                break;
            case "lastMonth":
                startTimestamp = now.subtract(1, "month").valueOf();
                break;
            case "lastYear":
                startTimestamp = now.subtract(1, "year").valueOf();
                break;
            case "custom":
                setDateFilterLoading(false);
                setChartLoading(false);
                return;
        }

        let timeExpression = "";
        if (startTimestamp && endTimestamp) {
            const start = new Date(startTimestamp);
            start.setHours(0);
            start.setMinutes(1);
            const end = new Date(endTimestamp);
            end.setHours(23);
            end.setMinutes(59);
            timeExpression = `@createdAt:[${start.getTime()},+inf]@createdAt:[-inf, ${end.getTime()}]`;
        }

        getPageData(timeExpression);
        setDateFilterLoading(false);
    };

    const handleCustomDateRange = (type: "start" | "end", value: any) => {
        setCustomDateRangeState(prev => {
            const newState = type === "start"
                ? { startDate: value, endDate: prev.endDate }
                : { startDate: prev.startDate, endDate: value };

            if (newState.startDate && newState.endDate && type === "end" && prev.startDate) {
                setTimeout(() => {
                    setDateFilterLoading(true);
                    setChartLoading(true);

                    const startTimestamp = newState.startDate.valueOf();
                    const endTimestamp = newState.endDate.valueOf();

                    const start = new Date(startTimestamp);
                    start.setHours(0);
                    start.setMinutes(1);
                    const end = new Date(endTimestamp);
                    end.setHours(23);
                    end.setMinutes(59);
                    const timeExpression = `@createdAt:[${start.getTime()},+inf]@createdAt:[-inf, ${end.getTime()}]`;

                    getPageData(timeExpression);
                    setDateFilterLoading(false);
                }, 100);
            }

            return newState;
        });
    };

    const getPageData = (timeExpression?: string) => {
        if (!configUserId) {
            console.warn("configUserId is required to fetch pages");
            return;
        }

        setPagesLoading(true);
        const timeIndex = timeExpression || "";
        const searchQuery = `@pageMembers:{${configUserId}}@pageType:{event}${timeIndex}`;

        const getPageDataRequest: any = {
            select: {
                index: {
                    searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:page:ride`,
                    searchQuery: searchQuery,
                    searchOptions: 'VERBATIM TIMEOUT 10000',
                },
                load: {
                    objectId: '$.objectId',
                    static: '$.persistent.static',
                    status: '$.nonpersistent.static.live.status.name',
                    title: '$.persistent.static.metadata.title',
                    createdAt: '$.persistent.static.metadata.createdAt',
                    updatedAt: '$.nonpersistent.dynamic.metadata.lastSent.members.updatedAt',
                    projectId: '$..profile.projectId',
                    customerId: '$..profile.customerId',
                    buildingName: '$..profile.buildingName',
                },
            },
            sortBy: {
                properties: [
                    {
                        field: "@updatedAt",
                        order: "DESC",
                    },
                ],
                max: 100000,
            },
            result: {
                pagination: {
                    offset: 0,
                    limit: 100000,
                },
            },
        };

        dispatch(
            GET_AGGREGATE({
                requestData: getPageDataRequest,
                callback: (response) => {
                    setPages(response || []);
                    setPagesLoading(false);
                    setChartLoading(false);
                },
            })
        );
    };

    const getCustomers = () => {
        if (!cudbServiceId) {
            console.warn("cudbServiceId is required to fetch customers");
            return;
        }

        setCustomersLoading(true);

        const getGroupsPayload: any = {
            select: {
                index: {
                    searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:custom:id`,
                    searchQuery: `@partitions:{org\\:${formatForRedis(cudbServiceId)}}`,
                    searchOptions: 'VERBATIM TIMEOUT 10000',
                },
                load: {
                    info: '$.info',
                    objectId: '$.objectId',
                    name: '$..info..name',
                    email: '$..info..email',
                    phone: '$..info..phone',
                    id: '$..info.id',
                },
            },
            result: {
                pagination: {
                    offset: 0,
                    limit: 10000,
                },
            },
        };

        dispatch(
            GET_AGGREGATE({
                requestData: getGroupsPayload,
                callback: (response) => {
                    setCustomers(response || []);
                    setCustomersLoading(false);
                },
            })
        );
    };

    const createDonutChart = (percentage: number, size: number = 120) => {

        const chartData = [
            { value: percentage, color: "#20B2AA" },
            { value: 100 - percentage, color: "#F0F8FF" }
        ];

        // Calculate lineWidth for 70% cutout (donut effect)
        // lineWidth represents the thickness of the ring
        // For a 70% cutout, we want the ring to be 30% of the radius
        const lineWidth = Math.floor(size * 0.15);
   
        return (
            <div style={{
                width: size,
                height: size,
                position: "relative",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                margin: "15px auto"
            }}>
                <PieChart
                    data={chartData}
                    lineWidth={lineWidth}
                    totalValue={100}
                    startAngle={-90}
                    animate={false}
                />

                <div
                    style={{
                        position: "absolute",
                        top: "50%",
                        left: "50%",
                        transform: "translate(-50%, -50%)",
                        fontSize: "18px",
                        fontWeight: "bold",
                        color: "#000"
                    }}
                >
                    {formatPercentage(percentage)}%
                </div>
            </div>
        );
    };

    const ServiceIcon = ({ imageUrl, alt }: { imageUrl?: string; alt: string }) => {
        return (
            <img
                src={imageUrl || "/images/dish-icon.svg"}
                alt={alt}
                style={{ width: "56px", height: "56px" }}
            />
        );
    };

    const renderServiceSection = (
        title: string,
        services: { [key: string]: ServiceData },
        serviceConfigs: ServiceConfig[]
    ) => {
        const totalEligible = Object.values(services).reduce((sum, data) => sum + data.eligibleCount, 0);

        return (
            <div className="service-section mt-3">
                <h4 className="section-title" style={{ marginTop: "12px", marginBottom: "10px", fontSize: "14px", fontWeight: "bolder" }}>
                    {title}: {totalEligible}
                </h4>
                <div className="services-grid">
                    {serviceConfigs.map((serviceConfig) => {
                        const serviceData = services[serviceConfig.name] || {
                            total: 0,
                            eligibleCount: 0,
                            percentage: 0
                        };
                        return (
                            <div key={serviceConfig.name} className="service-item" style={{ display: "flex", justifyContent: "flex-start", marginBottom: "10px", gap: "10px" }}>
                                <ServiceIcon imageUrl={serviceConfig.image?.url} alt={serviceConfig.name} />
                                <div className="service-info">
                                    <span className="service-count" style={{ fontSize: "16px", fontWeight: "600" }}>
                                        {serviceData.eligibleCount}
                                    </span>
                                    <div className="service-percentage" style={{ fontSize: "12px", fontStyle: "italic" }}>
                                        ({formatPercentage(serviceData.percentage)}%)
                                    </div>
                                    <p className="service-label" style={{ fontSize: "8px" }}>
                                        {serviceConfig.name}
                                    </p>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>
        );
    };

    const handleManualInputChange = (serviceKey: string, value: number) => {
        setManualInputs(prev => ({
            ...prev,
            [serviceKey]: value || 0
        }));
    };

    const handleBuildingManualInputChange = (buildingName: string, value: number) => {
        setBuildingManualInputs(prev => ({
            ...prev,
            [buildingName]: value || 0
        }));
    };

    const handleClearManualInputs = () => {
        const clearedInputs: { [key: string]: number } = {};
        Object.keys(manualInputs).forEach(key => {
            clearedInputs[key] = 0;
        });
        setManualInputs(clearedInputs);

        const clearedBuildingInputs: { [key: string]: number } = {};
        Object.keys(buildingManualInputs).forEach(key => {
            clearedBuildingInputs[key] = 0;
        });
        setBuildingManualInputs(clearedBuildingInputs);
    };

    if (!isDataReady && !loadingTimeout) {
        return (
            <div className="lighthouse-dashboard-loading" style={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                height: '50vh',
                gap: '20px'
            }}>
                <Spin size="large" />
                <div style={{ textAlign: 'center' }}>
                    <h3>Loading Dashboard...</h3>
                    <p>Fetching data and calculating statistics</p>
                </div>
            </div>
        );
    }

    if (!reportConfig) {
        return (
            <div style={{ textAlign: 'center', padding: '50px' }}>
                <h3>Configuration Not Found</h3>
                <p>No report configuration found for mode: {mode}</p>
            </div>
        );
    }

    return (
        <React.Fragment>
            {/* Date Filter Section */}
            <Row gutter={30} className="mb-4">
                <Col className="gutter-row" sm={24} md={14}>
                    <Card className="filter-card">
                        <Row gutter={16} className="d-flex px-1 flex-wrap">
                            <div>
                                <h5 className="mb-0">Date Filters</h5>
                            </div>
                            <div onClick={() => handleDateFilter("lastWeek")}>
                                <Button
                                    className={`beam-btn w-70 ${dateFilter === "lastWeek" ? "green-btn cover" : ""}`}
                                >
                                    Last Week
                                </Button>
                            </div>
                            <div onClick={() => handleDateFilter("lastMonth")}>
                                <Button
                                    className={`beam-btn w-70 ${dateFilter === "lastMonth" ? "green-btn cover" : ""}`}
                                >
                                    Last Month
                                </Button>
                            </div>
                            <div onClick={() => handleDateFilter("lastYear")}>
                                <Button
                                    className={`beam-btn w-70 ${dateFilter === "lastYear" ? "green-btn cover" : ""}`}
                                >
                                    Last Year
                                </Button>
                            </div>
                            <div onClick={() => handleDateFilter("custom")}>
                                <Button
                                    className={`beam-btn w-70 ${dateFilter === "custom" ? "green-btn cover" : ""}`}
                                >
                                    Custom
                                </Button>
                            </div>
                        </Row>

                        {dateFilter === "custom" && (
                            <>
                                <Row gutter={15} className="d-flex flex-wrap mt-3 mx-0">
                                    <Col xs={24} md={10} className="datetime-item">
                                        <DatePicker
                                            placeholder="From"
                                            suffixIcon={<DownOutlined />}
                                            onChange={(time: any) => {
                                                handleCustomDateRange("start", time);
                                            }}
                                        />
                                    </Col>
                                    <Col xs={24} md={4} className="d-flex justify-content-center">
                                        <span>to</span>
                                    </Col>
                                    <Col xs={24} md={10} className="datetime-item">
                                        <DatePicker
                                            placeholder="To"
                                            suffixIcon={<DownOutlined />}
                                            onChange={(time: any) => {
                                                handleCustomDateRange("end", time);
                                            }}
                                        />
                                    </Col>
                                </Row>
                                <Row className="mt-2">
                                    <Col span={24}>
                                        <div style={{
                                            fontSize: '12px',
                                            color: '#666',
                                            textAlign: 'center',
                                            fontStyle: 'italic'
                                        }}>
                                            {customDateRange.startDate && !customDateRange.endDate &&
                                                "Please select the 'To' date to apply the filter"
                                            }
                                            {!customDateRange.startDate &&
                                                "Please select both 'From' and 'To' dates to apply the filter"
                                            }
                                            {customDateRange.startDate && customDateRange.endDate &&
                                                "Custom date range applied successfully"
                                            }
                                        </div>
                                    </Col>
                                </Row>
                            </>
                        )}
                    </Card>
                </Col>
            </Row>

            {/* Add Manual Data Button Section */}
            <Row gutter={30} className="mb-4">
                <Col className="gutter-row" sm={24} md={14}>
                    <Card className="filter-card">
                        <Row gutter={16} className="d-flex px-1 flex-wrap">
                            <div onClick={() => setShowManualInput(!showManualInput)}>
                                <Button
                                    className={`beam-btn w-70 ${showManualInput ? "green-btn cover" : ""}`}
                                >
                                    <PlusOutlined /> Add Manual Data
                                </Button>
                            </div>
                            {showManualInput && (
                                <div onClick={handleClearManualInputs}>
                                    <Button className="beam-btn w-70">
                                        <ClearOutlined /> Clear
                                    </Button>
                                </div>
                            )}
                        </Row>
                    </Card>
                </Col>
            </Row>

            {/* Manual Input Section */}
            {showManualInput && reportConfig && (
                <>
                    {/* Building-Level Manual Inputs */}
                    <Row gutter={30} className="mb-4">
                        <Col span={24}>
                            <Card className="filter-card">
                                <h5 className="mb-3">Building-Level Manual Data</h5>
                                <p style={{ fontSize: "12px", color: "#666", marginBottom: "16px", fontStyle: "italic" }}>
                                    Add eligible services to buildings (increases both total and eligible count, increases building percentage)
                                </p>
                                <Row gutter={[16, 16]}>
                                    {reportConfig.buildings.map(building => (
                                        <Col key={building.name} xs={24} sm={12} md={8} lg={6}>
                                            <div style={{ marginBottom: "8px" }}>
                                                <label style={{ display: "block", marginBottom: "4px", fontSize: "12px", fontWeight: "500" }}>
                                                    {building.name}
                                                </label>
                                                <NumberInput
                                                    value={buildingManualInputs[building.name] || 0}
                                                    onChange={(val) => handleBuildingManualInputChange(building.name, val)}
                                                    min={0}
                                                    step={"1"}
                                                />
                                            </div>
                                        </Col>
                                    ))}
                                </Row>
                            </Card>
                        </Col>
                    </Row>

                    {/* Service-Level Manual Inputs */}
                    <Row gutter={30} className="mb-4">
                        <Col span={24}>
                            <Card className="filter-card">
                                <h5 className="mb-3">Service-Level Manual Data</h5>
                                <p style={{ fontSize: "12px", color: "#666", marginBottom: "16px", fontStyle: "italic" }}>
                                    Add eligible services to specific services (increases both total and eligible count)
                                </p>
                                <Row gutter={[16, 16]}>
                                    {reportConfig.buildings.map(building =>
                                        building.categories.map(category =>
                                            category.services.map(service => {
                                                const serviceKey = getServiceKey(building.name, category.name, service.name);
                                                return (
                                                    <Col key={serviceKey} xs={24} sm={12} md={8} lg={6}>
                                                        <div style={{ marginBottom: "8px" }}>
                                                            <label style={{ display: "block", marginBottom: "4px", fontSize: "12px", fontWeight: "500" }}>
                                                                {service.name}
                                                            </label>
                                                            <NumberInput
                                                                value={manualInputs[serviceKey] || 0}
                                                                onChange={(val) => handleManualInputChange(serviceKey, val)}
                                                                min={0}
                                                                step={"1"}
                                                            />
                                                        </div>
                                                    </Col>
                                                );
                                            })
                                        )
                                    )}
                                </Row>
                            </Card>
                        </Col>
                    </Row>
                </>
            )}

            {/* Main Title */}
            <div className="dashboard-title">
                <h1>{reportConfig.title}</h1>
            </div>

            {/* Chart Loading Overlay */}
            {chartLoading && (
                <div style={{
                    position: 'relative',
                    minHeight: '400px',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    backgroundColor: 'rgba(255, 255, 255, 0.8)',
                    borderRadius: '8px',
                    margin: '20px 0'
                }}>
                    <div style={{ textAlign: 'center' }}>
                        <Spin size="large" />
                        <div style={{ marginTop: '16px', fontSize: '16px', fontWeight: '500' }}>
                            Updating charts with new data...
                        </div>
                    </div>
                </div>
            )}

            {/* Main Content Cards */}
            <div style={{ opacity: chartLoading ? 0.3 : 1, transition: 'opacity 0.3s ease' }}>
                {/* First Row: All Building Cards */}
                <Row gutter={30} className="mb-4">
                    {centersData.map((center, index) => {
                        const buildingConfig = reportConfig.buildings.find(b => b.name === center.name);
                        if (!buildingConfig) return null;

                        // Calculate column span based on number of buildings (24 columns total)
                        const totalBuildings = centersData.length;
                        const colSpan = totalBuildings > 0 ? Math.floor(24 / totalBuildings) : 8;

                        return (
                            <Col key={index} xs={24} md={colSpan}>
                                <Card className="summary-card center-card">
                                    <div className="center-header">
                                        <h3 style={{ marginBottom: "5px" }}>{center.name}</h3>
                                        <p className="center-subtitle" style={{ fontSize: "14px", fontStyle: "italic", textAlign: "center" }}>
                                            {center.subtitle}
                                        </p>
                                    </div>

                                    <div className="center-content">
                                        {buildingConfig.categories.map(category => {
                                            const categoryServices = category.services.map(service => ({
                                                [service.name]: center.services[service.name] || {
                                                    total: 0,
                                                    eligibleCount: 0,
                                                    percentage: 0
                                                }
                                            })).reduce((acc, curr) => ({ ...acc, ...curr }), {});

                                            return (
                                                <div key={category.name}>
                                                    {renderServiceSection(
                                                        category.name,
                                                        categoryServices,
                                                        category.services
                                                    )}
                                                </div>
                                            );
                                        })}
                                    </div>
                                </Card>
                            </Col>
                        );
                    })}
                </Row>

                {/* Second Row: Main Overall Service Rate Chart (Full Width) */}
                <Row gutter={30} className="mb-4">
                    <Col span={24}>
                        <Card className="summary-card service-rate-card">
                            <div className="overall-service-content">
                                <div className="service-rate-info">
                                    <h3>
                                        {formatPercentage(overallStats.eligiblePercentage)}% of our services were provided to {mode.toUpperCase()} clients
                                    </h3>
                                    <div className="chart-container">
                                        {createDonutChart(overallStats.eligiblePercentage, 120)}
                                    </div>
                                    <p className="chart-label">
                                        {mode.toUpperCase()} Service Rate
                                        {overallStats.lastUpdated && (
                                            <span style={{ fontSize: '12px', display: 'block', marginTop: '5px' }}>
                                                Updated: {overallStats.lastUpdated.toLocaleTimeString()}
                                            </span>
                                        )}
                                    </p>
                                </div>
                            </div>
                        </Card>
                    </Col>
                </Row>

                {/* Third Row: Individual Building Charts (Row Direction) */}
                <Row gutter={30} className="mb-4">
                    <Col span={24}>
                        <Card className="summary-card impact-card">
                            <div className="impact-content">
                                <h3>Lighthouse {mode.toUpperCase()} Impact</h3>
                                <div className="impact-charts-horizontal" style={{ display: "flex", justifyContent: "space-around", alignItems: "center", flexWrap: "wrap", gap: "20px" }}>
                                    {centersData.map((center, idx) => {
                                        // Calculate from service data
                                        let buildingTotal = Object.values(center.services).reduce(
                                            (sum, data) => sum + data.total, 0
                                        );
                                        let buildingEligible = Object.values(center.services).reduce(
                                            (sum, data) => sum + data.eligibleCount, 0
                                        );

                                        // Apply building-level manual inputs (affects building percentage only)
                                        const buildingManualInput = buildingManualInputs[center.name] || 0;
                                        if (buildingManualInput > 0) {
                                            buildingTotal += buildingManualInput;
                                            buildingEligible += buildingManualInput;
                                        }

                                        const buildingPercentage = buildingTotal > 0
                                            ? parseFloat(((buildingEligible / buildingTotal) * 100).toFixed(2))
                                            : 0;

                                        console.log(`\n=== CALCULATING BUILDING PERCENTAGE (Impact Chart) ===`);
                                        console.log(`🏢 Building: ${center.name}`);
                                        console.log(`   Building Total (from services): ${buildingTotal - buildingManualInput}`);
                                        if (buildingManualInput > 0) {
                                            console.log(`   Building Manual Input: ${buildingManualInput}`);
                                        }
                                        console.log(`   Building Total (with manual input): ${buildingTotal}`);
                                        console.log(`   Building Eligible (${mode.toUpperCase()}): ${buildingEligible}`);
                                        console.log(`   Building Percentage Calculation: (${buildingEligible} / ${buildingTotal}) * 100 = ${buildingPercentage}%`);

                                        return (
                                            <div key={idx} className="impact-chart-item" style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
                                                {createDonutChart(buildingPercentage, 100)}
                                                <p style={{ textAlign: "center", fontSize: "12px", marginTop: "10px" }}>
                                                    {center.name}
                                                </p>
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        </Card>
                    </Col>
                </Row>

                {/* Footer Icons */}
                <Row>
                    <Col span={24}>
                        <Card className="summary-card">
                            <div className="footer-icons" style={{ display: "flex", justifyContent: "space-evenly", alignItems: "center", gap: "20px" }}>
                                <img src="/images/education-icon.svg" alt="Education" className="footer-icon" width="55px" height="55px" />
                                <img src="/images/hearts-icon.svg" alt="Heart" className="footer-icon" width="55px" height="55px" />
                                <img src="/images/motherhood-icon.svg" alt="Motherhood" className="footer-icon" width="55px" height="55px" />
                                <img src="/images/mothers-love-icon.svg" alt="Mother's Love" className="footer-icon" width="55px" height="55px" />
                            </div>
                        </Card>
                    </Col>
                </Row>
            </div>
        </React.Fragment>
    );
};

export default LighthouseDashboard;
