const AutoFormatDatePicker = ({ value = undefined, onChange, ...rest }) => {
  const wrapperRef = useRef(null);
  const [open, setOpen] = useState(false);

  // Normalize the value for AntD
  const normalizedValue = value
    ? moment.isMoment(value)
      ? value
      : moment(value)
    : null;

  useEffect(() => {
    if (!open) return;
    const input = wrapperRef.current?.querySelector("input");
    if (!input) return;

    const handleKeyUp = () => {
      const raw = input.value.replace(/[^\d]/g, "");
      if (raw.length === 8) {
        const formatted = `${raw.slice(0, 4)}-${raw.slice(4, 6)}-${raw.slice(
          6,
          8
        )}`;
        if (moment(formatted, "YYYY-MM-DD", true).isValid()) {
          const dateObj = moment(formatted, "YYYY-MM-DD");
          // Call parent's onChange in AntD format
          onChange?.(dateObj.format("YYYY-MM-DD"));
        }
      }
    };

    input.addEventListener("keyup", handleKeyUp);
    return () => {
      input.removeEventListener("keyup", handleKeyUp);
    };
  }, [open, onChange]);

  return (
    <div ref={wrapperRef}>
      <DatePicker
        {...rest}
        value={normalizedValue}
        // autoComplete="on"
        inputReadOnly={false}
        format="YYYY-MM-DD"
        onChange={(date) => onChange?.(date)}
        onOpenChange={setOpen}
        style={{ width: "100%" }}
      />
    </div>
  );
};

const AutoFormatTimePicker = (props: any) => {
  const { value = undefined, onChange, ...rest } = props;
  const wrapperRef = useRef<HTMLDivElement>(null);
  const [open, setOpen] = useState(false);

  // Normalize the value to moment first (like DatePicker)
  const normalizedValue = value
    ? moment.isMoment(value)
      ? value
      : moment(value)
    : null;

  useEffect(() => {
    if (!open) return;
    if (!wrapperRef.current) return;

    const input = wrapperRef.current.querySelector("input") as HTMLInputElement;

    if (!input) return;

    const handleInput = (e: Event) => {
      const target = e.target as HTMLInputElement;
      let raw = target.value.replace(/[^\d]/g, "");

      // Normalize raw input to 4 digits (e.g., 900 -> 0900)
      if (raw.length === 3) {
        // If the first digit is greater than 2 and not 1 or 2, pad with 0
        if (raw[0] !== "1" && raw[0] !== "2" && raw[0] !== "0") {
          raw = `0${raw}`;
        }
      }
      // if (raw.length === 3) {
      //   raw = `0${raw}`;
      // }

      if (raw.length !== 4) return;

      const hours = raw.slice(0, 2);
      const minutes = raw.slice(2, 4);
      const formatted = `${hours}:${minutes}`;

      const parsed = moment(formatted, "HH:mm", true);
      if (parsed.isValid()) {
        onChange?.(parsed);
      }
    };

    input.addEventListener("input", handleInput);

    return () => {
      input.removeEventListener("input", handleInput);
    };
  }, [open, onChange]);


  return (
    <div ref={wrapperRef}>
      <TimePicker
        {...rest}
        value={normalizedValue}
        format="HH:mm"
        inputReadOnly={false}
        allowClear
        onChange={(time) => onChange?.(time)}
        onOpenChange={(isOpen) => setOpen(isOpen)}
      />
    </div>
  );
};

