/*global google*/

// GPS Color Constants
export const GPS_AMBER = "#FBAE16";
export const GPS_RED = "#FF5F25";
export const GPS_GREEN = "#40CC52";

// Speed Thresholds (in meters per second)
export enum Speed {
  Motion = 0.5, // ~1.1 mph or ~1.8 kph
  Speeding = 13.4, // ~30 mph or ~48 kph
}

// GPS Icon Path (standard arrow pointing up)
export const ICON_GPS = {
  path: google.maps.SymbolPath.FORWARD_CLOSED_ARROW,
  scale: 5,
  strokeWeight: 2,
  strokeColor: "#FFFFFF",
  fillOpacity: 1,
  rotation: 0,
};

// Start Icon Path (circle/pin shape)
export const START_ICON = google.maps.SymbolPath.CIRCLE;

/**
 * Converts speed to meters per second and returns appropriate color
 * @param speed - Speed value
 * @param unit - Unit of speed: "mps" (meters per second), "mph" (miles per hour), or "kph" (kilometers per hour)
 * @returns Color string (GPS_AMBER, GPS_RED, or GPS_GREEN)
 */
export const getSpeedColor = (speed: number, unit: string = "mps"): string => {
  // Convert speed to meters per second
  let mpsSpeed = speed;
  switch (unit) {
    case "mps":
      break;
    case "mph":
      mpsSpeed = speed / 2.23694;
      break;
    case "kph":
      mpsSpeed = speed / 3.6;
      break;
  }
  if (mpsSpeed <= Speed.Motion) {
    return GPS_AMBER;
  }
  if (mpsSpeed >= Speed.Speeding) {
    return GPS_RED;
  }
  return GPS_GREEN;
};

/**
 * Creates a marker object for GPS data points
 * @param gps - GPS data point with dataset containing locationGps, speedGps, headingGps
 * @param color - Color for the marker fill
 * @param start - Whether this is the start marker (default: false)
 * @param live - Whether this is a live marker (default: false)
 * @returns Marker object with icon configuration
 */
export const createPeopleMarker = (
  gps: any,
  color: string,
  start: boolean = false,
  live: boolean = false
): any => {
  const icon = { ...ICON_GPS };
  const markerIcon = {
    ...icon,
    anchor: new google.maps.Point(3, 5),
    rotation: gps.dataset.headingGps - 180,
    fillColor: color,
    strokeColor: getSpeedColor(gps.dataset.speedGps),
  };
  if (start) {
    markerIcon.path = START_ICON;
    markerIcon.rotation = 0;
    markerIcon.scale = 1;
    markerIcon.anchor = new google.maps.Point(9, 28);
  }
  if (live) {
    markerIcon.fillColor = "#4682f4";
    markerIcon.strokeWeight = 5;
    markerIcon.scale = 3;
  }
  return {
    ...gps.dataset,
    lat: gps.dataset.locationGps.lat,
    lng: gps.dataset.locationGps.long,
    icon: markerIcon,
    speed: gps.dataset.speedGps,
    speedUnit: "mph",
    heading: gps.dataset.headingGps,
    gpsTimestamp: gps.timestamp,
  };
};

