import React from "react";
import { Row, Col, Form } from "antd";
import { isValidPhoneNumber } from "react-phone-number-input";
import FareTypeInput from "common/FareTypeInput";
import PayTypeInput from "common/PayTypeInput";
import { useDispatchPanel } from "../context";

// Fare + payment options shown for web-booker (passenger self-booking) sessions.
const WebBookerFareSection: React.FC = () => {
  const {
    webBooker,
    estimatedFare,
    setCouponResponse,
    form,
    projects,
    setPayType,
    setIsAddCardModalVisible,
  } = useDispatchPanel();

  if (!webBooker) return null;

  return (
    <React.Fragment>
      <Row className="mt-3">
        <Col span={24}>
          <Form.Item
            name="fareType"
            rules={[
              { required: true, message: "**Required Field" },
              {
                validator: (_, value) => {
                  if (value?.value === "bid" && value?.estimatedFare > 0) {
                    const minBid = value?.estimatedFare * 0.7;
                    const maxBid = value?.estimatedFare * 1.3;

                    if (value?.fare < minBid || value?.fare > maxBid) {
                      return Promise.reject(
                        `Bid must be between ${minBid.toFixed(
                          0
                        )} and ${maxBid.toFixed(0)}`
                      );
                    }
                  }
                  if (value?.value === "bid" && value?.fare === undefined) {
                    return Promise.reject("**Required Field");
                  }
                  return Promise.resolve();
                },
              },
            ]}
          >
            <FareTypeInput
              placeholder="Select fare"
              estimatedFare={estimatedFare}
              onChange={(value: any) => {
                setCouponResponse(undefined),
                  form.setFieldsValue({ coupon: undefined });
              }}
              dispatchOptions={[
                projects?.webSettings?.fixedEstimatedFare
                  ? { id: "fixedEstimate", name: "Fixed" }
                  : { id: "variable", name: "Auto (Metered)" },
                { id: "bid", name: "Bid" },
              ]}
            />
          </Form.Item>
        </Col>
      </Row>
      <hr />

      {projects?.webSettings?.webBookerMeterPayment && (
        <React.Fragment>
          <Row className="mt-3">
            <Col span={24}>
              <Form.Item
                name="payType"
                rules={[{ required: true, message: "**Required Field" }]}
              >
                <PayTypeInput
                  placeholder="Select pay"
                  onChange={(value: any) => {
                    setPayType(value.value);

                    const phone = form.getFieldValue("passengerPhoneNumber");
                    const email = form.getFieldValue("passengerEmail");
                    if (
                      value?.value === "now" &&
                      phone &&
                      isValidPhoneNumber(phone)
                    ) {
                      setIsAddCardModalVisible({
                        phone,
                        email,
                      });
                    } else {
                      setIsAddCardModalVisible(undefined);
                    }
                  }}
                  dispatchOptions={
                    webBooker
                      ? [
                        { id: "meter", name: "Cash" },
                        { id: "now", name: "Card" },
                      ]
                      : undefined
                  }
                />
              </Form.Item>
            </Col>
          </Row>
          <hr />
        </React.Fragment>
      )}
    </React.Fragment>
  );
};

export default WebBookerFareSection;
