import React, { useState, useEffect, useMemo, useRef } from "react";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { GET_AGGREGATE } from "reducers/reducer";

import { formatForRedis } from "utils/appUtil";
import { Select } from "antd";

const { Option } = Select;

const ResponderInput = (props: any) => {
  const { value, placeholder, onChange, adminRoles, multiple } = props;
  const { projects, users_filter } = useSelector(
    (state: RootState) => state.auth
  );
  const defaultPagination = 100;
  const [page, setPage] = useState(0);
  const [searching, setSearching] = useState(false);
  const [pagination, setPagination] = useState(true);
  const [loaded, setLoaded] = useState(false);
  const [options, setOptions] = useState([]);
  const dispatch = useDispatch();
  let timeout;

  // useEffect(() => {
  //   console.log("value", value);
  // }, [value]);

  const getUsers = (pageNumber, search = "") => {
    setPage(pageNumber);
    setSearching(true);

    const responderRoles = adminRoles
      .filter((x) => {
        return (
          x.permissions.indexOf("onMove") !== -1 &&
          x.permissions.indexOf("admin") === -1
        );
      })
      .map((y) => {
        return `@roleId === '${y._id}'`;
      });

    const requestData = {
      objectType: "user",
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
          searchQuery: `@serviceId:{'${formatForRedis(
            projects?.userServiceId
          )}'}`,
          searchOptions: "TIMEOUT 1000",
        },
        load: {
          email: "$..live.alternativeIds.email",
          phone: "$..live.alternativeIds.phone",
          beamIds: "$..beamIds",
          profile: "$..profile",
          roleId: "$..admin.profile.roleId",
          extendedBio: "$..extendedBio",
        },
      },
      groupBy: {
        properties: ["@email", "@phone", "@profile", "@roleId", "@extendedBio", "@beamIds"],
        reducers: [
          {
            func: "TOLIST",
            arguments: ["@objectId"],
            name: "objectIds",
          },
        ],
      },
      apply: {
        expression: "",
        name: "",
      },
      result: {
        pagination: {
          offset: page * defaultPagination,
          limit: defaultPagination,
        },
      },
      filter: {
        expression: `exists(@roleId) && (${responderRoles.join("||")})`,
      },
      anyStatus: false,
    };

    // dispatch({
    //   type: "GET_MAP_PLACES",
    //   payload: requestData,
    // });
    setSearching(true);

    dispatch(
      GET_AGGREGATE({
        requestData: requestData,
        callback: (response) => {
          setSearching(false);
          const opts = response
            ?.map((x) => {
              const obj = {
                id: x?.objectIds?.toString(),
                name: x?.profile?.firstName + " " + x.profile?.lastName,
                extendedBio: x?.extendedBio,
                extendedBioValue: x?.extendedBioValue,
                firstName: x?.profile?.firstName ?? "",
                lastName: x?.profile?.lastName ?? "",
                gender: x?.profile?.gender ?? "",
                dob: x?.profile?.dob ?? "",
                email: x.email,
                phone: x.phone,
                beamId: x?.beamIds?.[0]
                  ? x?.beamIds?.[0]
                  : `${x?.profile?.firstName?.toLowerCase()}.${x?.profile?.lastName?.toLowerCase()}`,
                location: x?.profile?.location?.coordinates
                  ? {
                      coordinates: [
                        x?.profile?.location.coordinates.long,
                        x?.profile?.location.coordinates.lat,
                      ],
                    }
                  : undefined,
              };
              return {
                id: obj.id,
                name: obj.name,
                obj,
              };
            })
            .filter((x) => {
              return !options.find((y) => {
                return x.id === y.id;
              });
            })
            .sort((a, b) => a.name.localeCompare(b.name));
          console.log("options", options);
          setOptions([...options, ...opts]);
          setLoaded(true);
          if (opts.length === 0) {
            setPagination(false);
          }
        },
      })
    );
  };

  // useEffect(() => {
  //   if (users_filter) {
  //     setSearching(false);
  //     const opts = users_filter
  //       ?.map((x) => {
  //         return {
  //           id: x.id,
  //           name: x.name,
  //           obj: x,
  //         };
  //       })
  // .filter((x) => {
  //   return !options.find((y) => {
  //     return x.id === y.id;
  //   });
  // });
  //     setOptions([...options, ...opts]);
  //     if (opts.length === 0) {
  //       setPagination(false);
  //     }
  //   }
  // }, [users_filter]);

  return (
    <Select
      showSearch
      mode={multiple ? "multiple" : undefined}
      className="w-full"
      // value={value?.valueName || (multiple ? value?.values : value?.value)}
      value={
        loaded
          ? multiple
            ? value?.values
            : value?.id
          : multiple
          ? value?.responders?.map((x) => {
              return x?.beamId;
            })
          : value?.beamId
      }
      placeholder={placeholder}
      allowClear
      disabled={adminRoles === undefined}
      onChange={(values) => {
        const changes = [];
        if (multiple) {
          values.map((value) => {
            const responder = options.find((x) => {
              return x.id === value;
            });
            if (responder) {
              changes.push({
                id: value,
                ...responder.obj,
              });
            }
          });
          onChange({
            type: "responder",
            responders: changes,
            values,
          });
        } else {
          const responder = options.find((x) => {
            return x.id === values;
          });
          onChange({
            type: "responder",
            value: values,
            ...responder?.obj,
            valueName: responder?.obj?.name,
          });
        }
      }}
      loading={searching}
      filterOption={(input, option) =>
        (option!.children as unknown as string)
          .toLowerCase()
          .includes(input.toLowerCase())
      }
      onFocus={() => {
        if ((users_filter?.length ?? 0) === 0) getUsers(0);
      }}
      onSearch={(search) => {
        if (timeout) clearTimeout(timeout);
        timeout = setTimeout(() => {
          if (search && search !== "") {
            getUsers(0, search);
            setPagination(false);
          } else getUsers(0);
        }, 500);
      }}
      onPopupScroll={(e: any) => {
        e.persist();
        let target = e.target;
        if (target.scrollTop + target.offsetHeight === target.scrollHeight) {
          if (pagination) {
            getUsers(page + 1);
          }
        }
      }}
    >
      {options?.map((option, index) => (
        <Option key={index} value={option.id}>
          {option.name}
        </Option>
      ))}
    </Select>
  );
};

export default ResponderInput;
