import React, { FC, useEffect, useState } from "react";
import { Upload, Row, Col, Button } from "antd";
import { CloseOutlined, UploadOutlined } from "@ant-design/icons";
import { useDispatch, useSelector } from "react-redux";
import { UPLOAD_MEDIA } from "../../reducers/reducer";
import { RootState } from "reducers/rootReducer";
import { uuid } from "uuidv4";

const MultipleFileUpload: FC<{
  value?: any;
  onChange: any;
  placeholder?: any;
  isMobile?: any;
  onUploadClick?: any;
  name?: any;
}> = ({ value, onChange, placeholder, isMobile, onUploadClick, name }) => {
  const [file, setFile] = useState<any>(value);
  const [fileList, setFileList] = useState([]);
  const [uploadedFiles, setUploadedFiles] = useState([]);
  const dispatch = useDispatch();
  const { fileToSend } = useSelector((state: RootState) => state.auth);
  const [saving, setSaving] = useState<boolean>(false);
  const [requestId, setRequestId] = useState<any>();
  const [uploadedCount, setUploadedCount] = useState<any>(0);

  useEffect(() => {
    if (fileToSend) {
      if (requestId === fileToSend.id) {
        console.log("file to send", fileToSend);
        const image = {
          name: fileToSend.media.originalName,
          url: fileToSend.media.urls.original.url,
          ...fileToSend.media,
        };
        const files = [...uploadedFiles];
        files.push(image);
        setUploadedFiles(files);
        const tempCount = uploadedCount + 1;
        setUploadedCount(tempCount)
        if(tempCount === fileList.length){
        // setFile(image);
          setSaving(false);
          onChange({files});
          setFileList([]);
          dispatch({ type: "ADD_FILE", payload: undefined });
        }
      }
    }
  }, [dispatch, fileToSend, onChange, requestId]);

  const handleOk = (e) => {
    // e.preventDefault();
    e.stopPropagation();

    // let form = new FormData();
    // form.append("file", file);
    // form.append("info", JSON.stringify({}));
    // dispatch(UPLOAD_MEDIA({ form, id: requestId }));

    console.log("file list here", fileList);
    let id = uuid();
    setRequestId(id);
    setUploadedCount(0);
    fileList.map((file) => {
      const form = new FormData();
      form.append("file", file);
      form.append("info", JSON.stringify({}));
      dispatch(UPLOAD_MEDIA({ form, id }));
    })
    // setFileList([]);
    // setUploadedFiles([{ name: "test.txt", url: "" }]);
    setSaving(true);
  };

  const onCancel = (index) => {
    // setFile(null);
    // onChange(null);
    const newFileList = uploadedFiles.slice();
    newFileList.splice(index, 1);
    setUploadedFiles(newFileList);
    onChange({files: newFileList});
  };

  useEffect(() => {
    console.log('value', value);
    if(value?.files){
      setUploadedFiles(value?.files);
    }
  }, [value]);

  const uploadProps = {
    onRemove: (file) => {
      setFileList((prevList) => {
        const index = prevList.indexOf(file);
        const newFileList = prevList.slice();
        newFileList.splice(index, 1);
        return newFileList;
      });
    },
    beforeUpload: (file) => {
      setFileList((prevList) => [...prevList, file]);
      return false; // Prevent auto upload
    },
    fileList,
  };

  return (
    <Row className="custom-file-upload">
      <Col span={24}>
        {/* {(file && file.name) ? (
          <div className="file-wrapper">
            <p>Your dropped file:</p>
            <hr />
            <ul>
              <li>
                <a target="_blank" href={file.url}>
                  {file.name}
                </a>
                <CloseOutlined onClick={() => onCancel()} />
              </li>
            </ul>
            {!file.url && (
              <Row className="action-grp mt-4">
                <Col span={24} className="pr-2">
                  <Button
                    className="beam-btn cover w-full"
                    onClick={handleOk}
                    loading={saving}
                  >
                    Upload
                  </Button>
                </Col>
              </Row>
            )}
          </div>
        ) : ( */}
        <div>
          {isMobile ? (
            <div className="file-wrapper">
              <div
                className="d-flex flex-column justify-content-center align-items-center p-4 cursor-pointer"
                onClick={() => {
                  if (onUploadClick) onUploadClick();
                }}
              >
                <p>Click to upload file</p>
              </div>
            </div>
          ) : (
            <Upload
              // maxCount={1}
              {...uploadProps}
              showUploadList
              multiple
              // beforeUpload={async (file, fileList) => {
              //   console.log('file list', fileList);
              //   // setFile(file);
              //   // setRequestId(uuid());
              //   return false;
              // }}
            >
              <div>
                <div>{placeholder || `Drop your file here (or click)`}</div>
                <div
                  className="d-flex row justify-content-center"
                  style={{ padding: 0 }}
                >
                  <Button className="beam-btn cover" icon={<UploadOutlined />}>
                    Select file
                  </Button>
                  {fileList.length > 0 &&
                    <Button
                      className="beam-btn cover ml-3"
                      onClick={handleOk}
                      // disabled={fileList.length === 0}
                      loading={saving}
                    >
                      {saving ? "Uploading" : "Start Upload"}
                    </Button>
                  }
                </div>
              </div>
            </Upload>
          )}
        </div>

        {uploadedFiles?.length > 0 && (
          <div className="file-wrapper1">
            <p>Your uploaded files:</p>
            {/* <hr /> */}
            <ul>
              {uploadedFiles?.map((file, index) => {
                return (
                  <li>
                    <a target="_blank" href={file.url} rel="noreferrer">
                      {file.name}
                    </a>
                    <CloseOutlined onClick={() => onCancel(index)} />
                  </li>
                );
              })}
            </ul>
          </div>
        )}

        {/* )} */}
      </Col>
    </Row>
  );
};

export default MultipleFileUpload;
