const AutoFormatTimePicker = (props: any) => {
  const { value = undefined, onChange, ...rest } = props;
  const wrapperRef = useRef<HTMLDivElement>(null);
  const [open, setOpen] = useState(false);
  const [pendingTime, setPendingTime] = useState<Moment | null>(null);

  // Normalize the value to moment first (like DatePicker)
  const normalizedValue = value
    ? moment.isMoment(value)
      ? value
      : moment(value)
    : null;

  useEffect(() => {
    if (!open) return;
    if (!wrapperRef.current) return;

    const input = wrapperRef.current.querySelector("input") as HTMLInputElement;

    if (!input) return;

    let lastInputValue = input.value;

    const handleInput = (e: Event) => {
      const target = e.target as HTMLInputElement;
      let raw = target.value.replace(/[^\d]/g, "");

      // Normalize raw input to 4 digits (e.g., 900 -> 0900)
      if (raw.length === 3) {
        // If the first digit is greater than 2 and not 1 or 2, pad with 0
        if (raw[0] !== "1" && raw[0] !== "2" && raw[0] !== "0") {
          raw = `0${raw}`;
        }
      }
      // if (raw.length === 3) {
      //   raw = `0${raw}`;
      // }

      if (raw.length !== 4) return;

      const hours = raw.slice(0, 2);
      const minutes = raw.slice(2, 4);
      const formatted = `${hours}:${minutes}`;

      const parsed = moment(formatted, "HH:mm", true);
      if (parsed.isValid()) {
        lastInputValue = input.value;
        setPendingTime(parsed);
        onChange?.(parsed);
      }
    };

    // Track value changes from panel selection (not just input events)
    const checkValueChange = () => {
      if (input.value !== lastInputValue && input.value) {
        const parsed = moment(input.value, "HH:mm", true);
        if (parsed.isValid()) {
          lastInputValue = input.value;
          setPendingTime(parsed);
        }
      }
    };

    // Poll for value changes while picker is open (panel selections update value but don't fire input event)
    const intervalId = setInterval(checkValueChange, 100);

    input.addEventListener("input", handleInput);

    return () => {
      input.removeEventListener("input", handleInput);
      clearInterval(intervalId);
    };
  }, [open, onChange]);


  return (
    <div ref={wrapperRef}>
      <TimePicker
        {...rest}
        value={normalizedValue}
        format="HH:mm"
        inputReadOnly={false}
        allowClear
        renderExtraFooter={() => null}
        onChange={(time) => {
          setPendingTime(time);
          onChange?.(time);
        }}
        onOpenChange={(isOpen) => {
          if (isOpen) {
            // Initialize pendingTime with current value when picker opens
            setPendingTime(normalizedValue);
          } else {
            // When picker closes, save pendingTime if it exists and is different from current value
            // setTimeout(() => {
              if (pendingTime !== null) {
                const currentTimeStr = normalizedValue?.format("HH:mm");
                const pendingTimeStr = pendingTime?.format("HH:mm");
                if (currentTimeStr !== pendingTimeStr) {
                  onChange?.(pendingTime);
                }
              } else {
                // Fallback: check input value directly if pendingTime is null
                const input = wrapperRef.current?.querySelector("input") as HTMLInputElement;
                if (input && input.value) {
                  const parsed = moment(input.value, "HH:mm", true);
                  if (parsed.isValid()) {
                    const currentTimeStr = normalizedValue?.format("HH:mm");
                    const inputTimeStr = parsed.format("HH:mm");
                    if (currentTimeStr !== inputTimeStr) {
                      onChange?.(parsed);
                    }
                  }
                }
              }
              setPendingTime(null);
            // }, 50);
          }
          setOpen(isOpen);
        }}
      />
    </div>
  );
};


const ScrollSyncTable = ({ data, columns }) => {
  const topScrollRef = useRef<HTMLDivElement>(null);
  const bottomScrollRef = useRef<HTMLDivElement>(null);
  const [tableWidth, setTableWidth] = useState<number>(0);

  useEffect(() => {
    const bottomTable = bottomScrollRef.current?.querySelector("table");
    if (bottomTable) {
      setTableWidth(bottomTable.scrollWidth); // use scrollWidth for full horizontal scroll space
    }

    const top = topScrollRef.current;
    const bottom = bottomScrollRef.current?.querySelector(".ant-table-content") as HTMLElement;

    if (!top || !bottom) return;

    const syncScrollLeft = (from: HTMLElement, to: HTMLElement) => {
      return () => {
        to.scrollLeft = from.scrollLeft;
      };
    };

    top.addEventListener("scroll", syncScrollLeft(top, bottom));
    bottom.addEventListener("scroll", syncScrollLeft(bottom, top));

    return () => {
      top.removeEventListener("scroll", syncScrollLeft(top, bottom));
      bottom.removeEventListener("scroll", syncScrollLeft(bottom, top));
    };
  }, [data]);

  return (
    <div>
      {/* Top scrollbar */}
      <div
        ref={topScrollRef}
        className="custom-scrollbar"
        style={{
          overflowX: "auto",
          overflowY: "hidden",
          height: 12,
          marginBottom: 8,
        }}
      >
        <div style={{ width: tableWidth, height: 1 }} />
      </div>

      {/* Table with scrollable content */}
      <div ref={bottomScrollRef}>
        <Table
          columns={columns}
          dataSource={data}
          pagination={false}
          scroll={{ x: "max-content" }} // let width flow freely
          style={{ tableLayout: "auto", width: "max-content" }}
        />
      </div>
    </div>
  );
};





