const TimeRangeSelector = ({ value, onChange }) => {
  const [selectedValue, setSelectedValue] = useState<any>(value);
  const [customRange, setCustomRange] = useState<any>(null);
  const [specificDate, setSpecificDate] = useState<any>(null);

  useEffect(() => {
    if (value) setSelectedValue(value);
  }, [value]);

  const triggerChange = (
    startTimestamp: number,
    endTimestamp: number,
    selected: any
  ) => {
    if (onChange) {
      onChange({ startTimestamp, endTimestamp, selected });
    }
  };

  const handleChange = (value: string) => {
    const now = moment();
    let startTimestamp: number;
    let endTimestamp: number = now.valueOf(); // Current timestamp

    if (value !== "customRange") setCustomRange(null);

    if (value !== "specificDate") setSpecificDate(null);

    switch (value) {
      // case "last24hours":
      //   startTimestamp = undefined;
      //   break;
      // case "last3days":
      //   startTimestamp = now.subtract(3, "days").valueOf();
      //   break;
      // case "last1week":
      //   startTimestamp = now.subtract(7, "days").valueOf();
      //   break;
      // case "last1month":
      //   startTimestamp = now.subtract(1, "month").valueOf();
      //   break;
      case "today":
        startTimestamp = moment().startOf("day").valueOf();
        endTimestamp = moment().endOf("day").valueOf();
        break;

      case "todayAndBeyond":
        startTimestamp = moment().startOf("day").valueOf();
        endTimestamp = moment().add(100, "years").endOf("day").valueOf(); // open-ended (future)
        break;

      case "tomorrow":
        startTimestamp = moment().add(1, "day").startOf("day").valueOf();
        endTimestamp = moment().add(1, "day").endOf("day").valueOf();
        break;

      case "nextWeek":
        startTimestamp = moment().add(1, "week").startOf("week").valueOf();
        endTimestamp = moment().add(1, "week").endOf("week").valueOf();
        break;
      case "customRange":
        if (customRange) {
          startTimestamp = customRange[0];
          endTimestamp = customRange[1];
        } else {
          console.warn("Select a custom range from the date picker.");
          // return;
        }
        break;
      case "specificDate":
        if (specificDate) {
          const start = moment(specificDate).startOf("day").valueOf();
          const end = moment(specificDate).endOf("day").valueOf();
          startTimestamp = start;
          endTimestamp = end;
        } else {
          console.warn("Select a specific date.");
        }
        break;
      default:
        console.warn("Invalid selection");
        return;
    }

    setSelectedValue(value);
    triggerChange(startTimestamp, endTimestamp, value);
  };

  const handleCustomRangeChange = (dates: any) => {
    if (dates) {
      const startTimestamp = dates[0].valueOf();
      const endTimestamp = dates[1].valueOf();
      setCustomRange([startTimestamp, endTimestamp]);
      triggerChange(startTimestamp, endTimestamp, "customRange");
    } else {
      setCustomRange(null);
    }
  };

  const handleSpecificDateChange = (date: any) => {
    if (date) {
      setSpecificDate(date);
      const startTimestamp = moment(date).startOf("day").valueOf();
      const endTimestamp = moment(date).endOf("day").valueOf();
      triggerChange(startTimestamp, endTimestamp, "specificDate");
    } else {
      setSpecificDate(null);
    }
  };

  return (
    <div className="w-100">
      <Select
        style={{ width: 200 }}
        placeholder="Select time range"
        className="w-100"
        value={selectedValue}
        onChange={handleChange}
      >
        {/* <Option value="last24hours">Last 1 Day and Upcoming</Option>
        <Option value="last3days">Last 3 Days</Option>
        <Option value="last1week">Last 1 Week</Option>
        <Option value="last1month">Last 1 Month</Option> */}

        <Option value="today">Today</Option>
        <Option value="todayAndBeyond">Today and Beyond</Option>
        <Option value="tomorrow">Tomorrow</Option>
        <Option value="nextWeek">Next Week</Option>

        <Option value="specificDate">Specific Date</Option>
        <Option value="customRange">Custom Range</Option>
      </Select>

      {selectedValue === "customRange" && (
        <RangePicker
          style={{ marginTop: 16 }}
          onChange={handleCustomRangeChange}
          format="YYYY-MM-DD"
          disabledTime={() => ({})} // Disable the time picker
          showTime={false} // Do not show the time picker
        />
      )}

      {selectedValue === "specificDate" && (
        <DatePicker
          style={{ marginTop: 16 }}
          onChange={handleSpecificDateChange}
          format="YYYY-MM-DD"
        />
      )}
    </div>
  );
};

