import React, { useEffect, useState } from "react";
import { Button, Row, Col, Dropdown, Menu } from "antd";
import { Link, useLocation } from "react-router-dom";
import { DownOutlined, UpOutlined } from "@ant-design/icons";
import "./index.scss";
import { ReactSVG } from "react-svg";
import EditPaymentModal from "./Payment/EditPaymentModal";
import Login from "./Login/Login";
import VerifyModal from "./VerifyCode/VerifyCode";
import Register from "./Register/Register";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { ENCRYPT_TOKEN, GET_USER_INFO, LOGOUT_USER } from "reducers/reducer";
import {
  CLOSE_LOGIN_MODAL,
  CLOSE_REGISTER_MODAL,
  CLOSE_VERIFY_MODAL,
  OPEN_LOGIN_MODAL,
  OPEN_REGISTER_MODAL,
} from "actions/Auth/actionTypes";
import useSocketActions from "../../../hooks/socketActions";

import { SocketTopics, UserTopics } from "constants/enums";
import { getAdminRolesTopic } from "hooks/MQTTConstants";

import EditCoachModal from "./EditCoach/EditCoachModal";

import SummaryTableModal from "./InvoiceTable/InvoiceTable";

import { uuid } from "uuidv4";

const Header = ({ socket }) => {
  const dispatch = useDispatch();
  const { getUserRequestPayload, handleMessages } = useSocketActions();
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const [isEditPaymentModalOpen, setEditPaymentModalOpen] = useState(false);
  // const [isLoginModalOpen, setLoginModalOpen] = useState(false);
  const [isOpenEditCoachModal, setOpenEditCoachModal] = useState(false);
  const [coachProfile, setCoachProfile] = useState({});

  const [adminRoles, setAdminRoles] = useState();

  const [isOpenInvoiceTableModal, setOpenInvoiceTableModal] = useState(false);

  const [name, setName] = useState<string>("");
  const { userInfo } = useSelector((state: RootState) => state.auth);
  const [image, setImage] = useState("/images/users/user.png");
  const [isUserLoggedIn, setUserLoggedIn] = useState(false);

  const {
    isOpenLoginModal,
    isOpenVerifyModal,
    loginSuccessfull,
    isOpenRegisterationModal,
    categories,
  } = useSelector((state: RootState) => state.auth);

  const [categoriesList, setCategoriesList] = useState([]);
  const { search } = useLocation();

  useEffect(() => {
    if (categories?.categories?.length) {
      const categoriesInfo = categories.categories.map((category) => ({
        name: category,
        subcategories: categories.subcategories[category] || [],
      }));

      setCategoriesList(categoriesInfo);
    }
  }, [categories]);

  useEffect(() => {
    if (userInfo?.coach) {
      const { type, ...coachData } = userInfo?.coach;
      setCoachProfile({
        ...coachData,
        categories: coachData?.categories?.map(cat=> {return {...cat, pricingPlans: cat?.pricingPlans || []} }),
        bio: {
          ...userInfo?.coach?.bio,
          image: userInfo?.profileImage?.urls?.original,
        },
      });
    }
  }, [userInfo]);

  useEffect(() => {
    const query = new URLSearchParams(search);
    // const token = query.get("token");
    // const verify = query.get("verify");
    const selectedOrg = query.get("serviceId");
    const adminUserId = query.get("adminUserId");
    const CID = query.get("connectionId");

    if(CID){
      localStorage.setItem("CID",CID);
    }
    if(!localStorage.getItem("UUID")){
      localStorage.setItem("UUID",uuid());
    }

    if (selectedOrg) {
      localStorage.setItem("coachServiceId", selectedOrg || "cudb-live");
    }
    if (adminUserId) {
      localStorage.setItem("adminUserId", adminUserId);
    }

    if (adminUserId && selectedOrg) {     
      getAdminRoles(adminUserId, selectedOrg);
    } else {
      // TODO: what to do if no org service id is there
    }
    // if (token) {
    //   dispatch(DECRYPT_TOKEN({ payload: token }));
    // } else if (localStorage.getItem("TOKEN") && !verify) {
    //   history.push("/coach");
    // } else {
    //   setBackdrop(false);
    // }
  }, [socket.client]);

  const getAdminRoles = (adminUserId, cudbServiceId) => {
    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.SearchInUser,
      getUserRequestPayload(adminUserId, "$", "$..role"),
      getAdminRolesTopic(localStorage.getItem("CID")),
      cudbServiceId
    );
    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      getAdminRolesTopic(localStorage.getItem("CID")),
      (response) => {
      
        setAdminRoles(response.data?.[0]?.[0]);
      }
    );
  };

  useEffect(() => {
    if (loginSuccessfull || localStorage.getItem("TOKEN")) {
      dispatch(GET_USER_INFO());
      setUserLoggedIn(true);
    }
  }, [loginSuccessfull]);

  useEffect(() => {
    if (userInfo) {
      const firstname = userInfo.firstName || "";
      const lastname = userInfo.lastName || "";
      if (!firstname && !lastname) {
        setName("");
        return;
      }
      const name = firstname + " " + lastname;
      setName(name);
      setImage(
        userInfo?.profileImage?.urls?.original?.url ?? "/images/users/user.png"
      );
    } else {
      setName("");
    }
  }, [userInfo]);

  const openLoginModal = () => {
    dispatch({ type: OPEN_LOGIN_MODAL });
  };
  const closeRegisterModal = () => {
    dispatch({ type: CLOSE_REGISTER_MODAL });
  };
  const openRegisterModal = () => {
    dispatch({ type: OPEN_REGISTER_MODAL });
  };
  const closeLoginModal = () => {
    dispatch({ type: CLOSE_LOGIN_MODAL });
  };
  const closeVerificationModal = () => {
    dispatch({ type: CLOSE_VERIFY_MODAL });
  };
  const logout = () => {
    setUserLoggedIn(false);
    dispatch({ type: LOGOUT_USER });
  };

  const goToLive = ()=>{
    dispatch(
      ENCRYPT_TOKEN({
        data: {
          payload: JSON.stringify({
            userId: localStorage.getItem("RID"),
            connectionId: `${localStorage.getItem("CID")}`,
            cudbServiceId: `${localStorage.getItem("coachServiceId")}`,
            configUserId: `${localStorage.getItem("adminUserId")}`,
          }),
        },
        callback: (token) => {
          window.location.href = `${process.env.REACT_APP_WEB}/auth/login?token=${token.encryptedPayload}`;
        },
      })
    );
  };

  const menu = (
    <ul className="user-dropdown">
      <React.Fragment>
        {userInfo?.coach?.type === "candidate" && (
          <li onClick={() => setEditPaymentModalOpen(true)}>
            <ReactSVG src="/images/payment.svg" className="drop-icon " />
            <span className="ml-3">Payment</span>
          </li>
        )}
        {userInfo?.coach?.type === "coach" && ( <li onClick={() => setOpenEditCoachModal(true)}>
          <ReactSVG src="/images/person.svg" />
          <span className="ml-3">Profile</span>
        </li>)}

        <li onClick={() => goToLive()}>
          <ReactSVG src="/images/chat.svg" />
          <span className="ml-3">Chat</span>
        </li>
        <li onClick={() => setOpenInvoiceTableModal(true)}>
          <ReactSVG className="ml-2" src="/images/desktop-icon.svg" />
          <span className="ml-3">Order</span>
        </li>
        <li
          onClick={() => {
            logout();
          }}
        >
          <ReactSVG className="ml-2" src="/images/logout.svg" />
          <span className="ml-2">Logout</span>
        </li>
      </React.Fragment>

      {/* {!isUserLoggedIn && (
        <React.Fragment>
          <li>
            <span onClick={() => openLoginModal()} className="ml-3">
              Login
            </span>
          </li>
          <li>
            <span onClick={() => openRegisterModal()} className="ml-3">
              Register
            </span>
          </li>
        </React.Fragment>
      )} */}
    </ul>
  );

  return (
    <div
      className="header main-column mobile-responsive"
      style={{ padding: "10px 20px", borderBottom: "1px solid #ddd" }}
    >
      <Row align="middle" justify="space-between" className="w-full">
        <Col>
          <Link to="/coach">
            <img
              src="/images/logo-icon.svg"
              alt="Coach App Icon"
              style={{ height: "40px" }}
            />
          </Link>
        </Col>

        {isUserLoggedIn && userInfo && (
          <Col>
            <Dropdown
              overlay={menu}
              placement="bottomRight"
              trigger={["click"]}
              onVisibleChange={(visible) => setDropdownOpen(visible)}
            >
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  cursor: "pointer",
                }}
              >
                <img
                  src={image}
                  alt="User Profile"
                  style={{
                    height: "40px",
                    width: "40px",
                    borderRadius: "50%",
                    marginRight: "8px",
                  }}
                />
                <p className="mr-1 ml-1">{name}</p>
                {dropdownOpen ? (
                  <UpOutlined style={{ fontSize: "10px" }} />
                ) : (
                  <DownOutlined style={{ fontSize: "10px" }} />
                )}
              </div>
            </Dropdown>
          </Col>
        )}

        {!isUserLoggedIn && (
          <Col style={{ marginLeft: "auto", display: "flex", gap: "10px" }}>
            <Button
              className="beam-btn green-btn cover w-50"
              onClick={() => openLoginModal()}
            >
              Login
            </Button>
            <Button
              className="beam-btn green-btn cover w-50"
              onClick={() => openRegisterModal()}
            >
              Register
            </Button>
          </Col>
        )}
      </Row>

      {isEditPaymentModalOpen && (
        <EditPaymentModal
          socket={socket}
          onClose={() => {
            setEditPaymentModalOpen(!isEditPaymentModalOpen);
          }}
          disableClose={false}
        />
      )}

      {isOpenLoginModal && (
        <Login
          socket={socket}
          onClose={() => {
            closeLoginModal();
          }}
          disableClose={false}
        ></Login>
      )}

      {isOpenEditCoachModal && (
        <EditCoachModal
          socket={socket}
          coach={coachProfile}
          categoriesList={categoriesList}
          onClose={() => {
            setOpenEditCoachModal(undefined);
          }}
          onAdd={() => {
            dispatch(GET_USER_INFO());
            //   getUsersByRole(adminUserRoles, USER_TYPES.Live);
          }}
        />
      )}

      {isOpenVerifyModal && (
        <VerifyModal
          socket={socket}
          onClose={() => {
            closeVerificationModal();
          }}
          disableClose={false}
        ></VerifyModal>
      )}

      {isOpenInvoiceTableModal && (
        <SummaryTableModal
        socket={socket}
        onClose={() => {
          setOpenInvoiceTableModal(false);
        }}
        >
        </SummaryTableModal>
      )}

      {isOpenRegisterationModal && (
        <Register
          socket={socket}
          onClose={() => {
            closeRegisterModal();
          }}
          disableClose={false}
        ></Register>
      )}
    </div>
  );
};

export default Header;
