// CategoriesBox.js
import React, { useEffect, useState } from 'react';
import { Typography } from 'antd';
import CheckableTag from "antd/lib/tag/CheckableTag";
import './index.scss';
const { Title } = Typography;

const CategoriesBox = ({ categoriesInfo, onChange }) => {

  const [categories, setCategories] = useState([]);
  const [subcategories, setSubcategories] = useState({});

  useEffect(() => {
    if (categoriesInfo?.categories?.length) {
      setCategories([...categoriesInfo?.categories])
      setSubcategories(categoriesInfo?.subcategories);
    }

  }, [categoriesInfo]);
  // const { categories: categoriesInfo } = useSelector(
  //   (state: RootState) => state.auth
  // );
  const [selectedCategories, setSelectedCategories] = useState([]);
  const [selectedSubcategories, setSelectedSubcategories] = useState({});

  // const categories = [...categoriesInfo.categories];


  // const subcategories = {
  //   // Technology: ["Software", "Hardware", "AI", "Robotics"],
  //   // Health: ["Medicine", "Wellness", "Nutrition", "Exercise"],
  //   // Finance: ["Banking", "Investing", "Economics", "Insurance"],
  //   // Education: ["Schools", "Online Courses", "Tutoring", "EdTech"],
  //   // Travel: ["Destinations", "Guides", "Transport", "Adventure"],
  //   // Food: ["Recipes", "Restaurants", "Nutrition", "Culinary Arts"],
  //   // Fashion: ["Clothing", "Accessories", "Trends", "Designers"],
  //   // Sports: ["Football", "Basketball", "Tennis", "Running"],
  //   // Entertainment: ["Movies", "Music", "Games", "Theater"],
  //   // Art: ["Painting", "Sculpture", "Photography", "Digital Art"],
  //   ...categoriesInfo.subcategories
  // };

  const toggleCategory = (category, checked) => {
    setSelectedCategories((prevSelected) => {
      const updatedSelected = checked ? [...prevSelected, category] : prevSelected.filter((c) => c !== category);
  
      setSelectedSubcategories((prev) => {
        const updatedSubcategories = { ...prev };
        if (!checked) {
          delete updatedSubcategories[category];
        }
        return updatedSubcategories;
      });
  
      return updatedSelected;
    });
  };
  

  const toggleSubcategory = (category, subcategory, checked) => {
    
  setSelectedSubcategories((prev) => {
    const updatedSubcategories = {
      ...prev,
      [category]: checked
        ? [...(prev[category] || []), subcategory]
        : (prev[category] || []).filter((s) => s !== subcategory),
    };
    if (updatedSubcategories[category].length === 0) {
      delete updatedSubcategories[category];
    }

    return updatedSubcategories;
  });
  };
 

  useEffect(() => {
      onChange({ selectedCategories, selectedSubcategories });
  }, [selectedCategories, selectedSubcategories, onChange]); 
  

  return (
    <div>

      <div className="categories-box">
        <Title level={4}>Select Categories</Title>
        <div className="categories-container">
          {categories.map((category) => (
            <CheckableTag
              key={category}
              checked={selectedCategories.includes(category)}
              onChange={(checked) => toggleCategory(category, checked)}
              className="category-tag"
            >
              {category}
            </CheckableTag>
          ))}
        </div>
      </div>


      {selectedCategories.length > 0 && (
        <div className="categories-box subcategories-box">
          <Title level={4}>Select Subcategories</Title>
          <div className="categories-container">
            {selectedCategories.flatMap((category) =>
              (subcategories[category] || []).map((subcategory) => (
                <CheckableTag
                  key={subcategory}
                  checked={selectedSubcategories[category]?.includes(subcategory)}
                  onChange={(checked) => toggleSubcategory(category, subcategory, checked)}
                  className="subcategory-tag"
                >
                  {subcategory}
                </CheckableTag>
              ))
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default CategoriesBox;
