import React from "react";
import { Row, Col, Form } from "antd";
import VehicleTypeInput from "common/VehicleTypeInput";
import { useDispatchPanel } from "../context";

const VehicleTypeSection: React.FC = () => {
  const { form, socket, setVehicleType, getRideEstimation } = useDispatchPanel();

  return (
    <Row className="mt-3">
      <Col span={24}>
        <Form.Item name="vehicleType" label="Select vehicle type">
          <VehicleTypeInput
            placeholder="Select vehicle type"
            onChange={(value: any) => {
              setVehicleType(value?.value);

              const pickupLocation = form.getFieldValue("pickupLocation");
              const dropoffLocation = form.getFieldValue("dropoffLocation");
              if (
                pickupLocation?.value?.coordinates &&
                dropoffLocation?.value?.coordinates
              ) {
                getRideEstimation(pickupLocation, dropoffLocation, value?.value);
              }
            }}
            socket={socket}
          />
        </Form.Item>
      </Col>
    </Row>
  );
};

export default VehicleTypeSection;
