const CustomDatePickerList: React.FC<any> = ({
  label = "Custom Dates",
  value,
  onChange,
}) => {
  const handleAddDate = (date: any) => {
    if (!date) return;
    if (!value.some((d) => d.isSame(date, "day"))) {
      onChange([...value, date]);
    }
  };

  const handleTagClose = (dateToRemove: Dayjs) => {
    const updated = value.filter((d) => !d.isSame(dateToRemove, "day"));
    onChange(updated);
  };

  return (
    <div>
      <label className="ant-form-item-required">{label}</label>
      {/* <span className="col-label">{label}</span> */}
      <DatePicker
        onChange={handleAddDate}
        disabledDate={(date) =>
          date && date < moment().startOf("day") || value?.some((selectedDate) => selectedDate?.isSame(date, "day"))
        }
        placeholder="Select date"
      />
      <div style={{ marginTop: "16px" }} className="custom-tag">
        {value?.map((date) => (
          <Tag
            key={date.toISOString()}
            className="tag-item"
            closable
            onClose={() => handleTagClose(date)}
            closeIcon={<CloseCircleOutlined />}
          >
            {date.format("YYYY-MM-DD")}
          </Tag>
        ))}
      </div>
    </div>
  );
};

