import React, { FC, useEffect, useState } from "react";
import { Button, Row, Col, Table } from "antd";
import { FilterOutlined, RedoOutlined } from "@ant-design/icons";
import _ from "lodash";
import { ReactSVG } from "react-svg";
import { wrapRequestPayload } from "../../../helpers/request/RequestPayload";
import {
  getProjectsSubscriptionTopic,
  getProjectsRequestPublishTopic,
  getFocusPagePublishTopic,
  getAdminRolesTopic,
} from "hooks/MQTTConstants";
import { useLocation } from "react-router-dom";
import { SocketTopics, UserTopics } from "constants/enums";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { useDispatch } from "react-redux";
import HeartRateMonitor from "common/Graphs/HeartRate";
import BloodPressureMonitor from "common/Graphs/BloodPressure";
import TableFilterModal from "./TableFilterModal";
import useSocketActions from "../../../hooks/socketActions";
import "./Dashboard.scss";

const RxDashboardModal: FC<{ socket: ISocket; params?: any }> = ({
  socket,
}) => {
  const { search } = useLocation();
  const { projects, gps } = useSelector((state: RootState) => state.auth);
  const dispatch = useDispatch();
  const [projectFilterLoading, setProjectFilterLoading] =
    useState<boolean>(false);
  const [iotUpdated, setIotUpdated] = useState<any>();
  const [user, setUser] = useState<any>();
  const [videoToken, setVideoToken] = useState<any>();
  const [tableDataSource, setTableDataSource] = useState<any>([]);
  const [tableColumns, setTableColumns] = useState<any>([]);
  const [showTableFilterModal, setShowTableFilterModal] =
    useState<boolean>(false);
  const [tableHideList, setTableHideList] = useState<any>([]);
  const { getUserRequestPayload } = useSocketActions();

  const getUserBio = (userId, cudbServiceId) => {
    const query = new URLSearchParams(search);
    const connectionId = query.get("connectionId");
    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.SearchInUser,
      getUserRequestPayload(userId, "$", "$"),
      getAdminRolesTopic(connectionId),
      cudbServiceId
    );
    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      getAdminRolesTopic(connectionId),
      (response) => {
        const userObj = response.data?.[0]?.[0];

        setUser({
          name: `${
            userObj?.persistent?.static?.live?.profile?.firstName ?? ""
          } ${userObj?.persistent?.static?.live?.profile?.lastName ?? ""}`,
          email: userObj?.persistent?.static?.live?.alternativeIds?.email,
          phone: userObj?.persistent?.static?.live?.alternativeIds?.phone,
          customId: userObj?.persistent?.static?.live?.alternativeIds?.customId,
          beamId: userObj?.persistent?.static?.live?.beamIds?.[0],
          bio: userObj?.persistent?.static?.[cudbServiceId]?.extendedBio,
        });
      }
    );
  };

  useEffect(() => {
    if (iotUpdated) {
      let tempData = [...tableDataSource];
      const l = tempData.length;
      iotUpdated?.map((x, i) => {
        tempData.unshift({
          key: x.timestamp,
          datetime: new Date(x.timestamp).toLocaleString(),
          oxygen: x?.dataset?.bloodOxygenRx ?? "N/A",
          heartRate: x?.dataset?.heartRateRx?.toFixed(0) ?? "N/A",
          temperature: x?.dataset?.bodyTempRx?.toFixed(1) ?? "N/A",
          bloodPressure: x?.dataset?.bloodpressureHighRx
            ? `${x?.dataset?.bloodpressureHighRx}/${x?.dataset?.bloodpressureLowRx}`
            : "N/A",
          calories: x?.dataset?.calRx?.toFixed(0) ?? "N/A",
          steps: x?.dataset?.stepsRx ?? "N/A",
          status: "N/A",
        });
      });
      setTableDataSource(tempData.slice(0, 100));
    }
  }, [iotUpdated]);

  useEffect(() => {
    if (gps) {
      let sourceData = [];
      let columns: any = [
        {
          title: "Timestamp",
          key: "datetime",
          dataIndex: "datetime",
        },
        {
          title: "Temperature (celcius)",
          key: "temperature",
          dataIndex: "temperature",
        },
        {
          title: "Heart rate (bpm)",
          key: "heartRate",
          dataIndex: "heartRate",
        },
        {
          title: "Oxygen (%)",
          key: "oxygen",
          dataIndex: "oxygen",
        },
        {
          title: "Blood pressure (mmHg)",
          key: "bloodPressure",
          dataIndex: "bloodPressure",
        },
        {
          title: "Calories (kcal)",
          key: "calories",
          dataIndex: "calories",
        },
        {
          title: "Steps",
          key: "steps",
          dataIndex: "steps",
        },
        {
          title: "Status",
          key: "status",
          dataIndex: "status",
        },
      ];
      gps?.samples?.map((x, i) => {
        sourceData.push({
          key: x.timestamp,
          datetime: new Date(x.timestamp).toLocaleString(),
          oxygen: x?.dataset?.bloodOxygenRx ?? "N/A",
          heartRate: x?.dataset?.heartRateRx?.toFixed(0) ?? "N/A",
          temperature: x?.dataset?.bodyTempRx?.toFixed(1) ?? "N/A",
          bloodPressure: x?.dataset?.bloodpressureHighRx
            ? `${x?.dataset?.bloodpressureHighRx}/${x?.dataset?.bloodpressureLowRx}`
            : "N/A",
          calories: x?.dataset?.calRx?.toFixed(0) ?? "N/A",
          steps: x?.dataset?.stepsRx ?? "N/A",
          status: "N/A",
        });
      });
      setTableColumns(columns);
      setTableDataSource(sourceData.reverse().slice(0, 100));
      setProjectFilterLoading(false);
    }
  }, [gps]);

  const getHistoricalRx = (offset = 0) => {
    const query = new URLSearchParams(search);
    // const userId = query.get("userId");
    const userId = "103706";
    const iotUdid = query.get("iotUdid");
    const iotUserId = query.get("iotUserId");
    let requestData = {
      filter: `ecosystem=${process.env.REACT_APP_ECO_SYSTEM} iotUdid=${iotUdid} userId=${userId} iotUserId=${iotUserId} page=true`,
      fromTimestamp: new Date().getTime() - 900000,
      toTimestamp: new Date().getTime(),
      options: {
        withLabels: true,
      },
    };
    dispatch({
      type: "GET_HISTORICAL_GPS",
      payload: { requestData },
    });
  };

  useEffect(() => {
    if (socket.client) {
      const query = new URLSearchParams(search);
      const userId = query.get("userId");
      const connectionId = query.get("connectionId");
      const vToken = query.get("videoToken");
      const iotUdid = query.get("iotUdid");
      const iotUserId = query.get("iotUserId");
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getProjectsSubscriptionTopic(connectionId)
      );
      socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        getProjectsRequestPublishTopic(connectionId),
        wrapRequestPayload({
          userId,
        })
      );
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        `${process.env.REACT_APP_ECO_SYSTEM}/device/${iotUdid}/user/103706/iotAppend/${iotUserId}/#`,
        (response) => {
          console.log("iot updated", response);
          setIotUpdated(response?.samples);
        }
      );
      setProjectFilterLoading(true);
      setVideoToken(vToken);
      getHistoricalRx();
      setTableHideList(JSON.parse(localStorage.getItem("tableHideList")) || []);
    }
  }, [search, socket.client]);

  useEffect(() => {
    if (projects) {
      const query = new URLSearchParams(search);
      const userId = query.get("userId");
      if (projects?.userServiceId) {
        getUserBio(userId, projects?.userServiceId);
      }
    }
  }, [projects]);

  const getUserBioKeyValue = (user, key) => {
    const keys = Object.keys(user?.bio || {});
    let value;
    keys.map((k) => {
      if (user?.bio?.[k]?.name === key) {
        value = user?.bio?.[k]?.value;
      }
    });
    return value;
  };

  return (
    <React.Fragment>
      <div className="profile-container">
        <div>
          <div className="client-info">
            <div className="info-block">
              <div className="client-name-label">Client name</div>
              <div className="client-name">{user?.name || "N/A"}</div>
            </div>
            <div className="contact-info">
              <div className="info-block">
                <div className="label">
                  {user?.phone ? "Phone" : "CustomeId"}
                </div>
                <div className="value">
                  {user?.phone || user?.customId || "N/A"}
                </div>
              </div>
            </div>
            <div className="contact-info">
              <div className="info-block">
                <div className="label">Email</div>
                <div className="value">{user?.email || "N/A"}</div>
              </div>
            </div>
          </div>

          <div className="medical-summary">
            <Button className="beam-btn w-full green-btn cover">
              Medical History
            </Button>
          </div>
        </div>

        <div className="divider"></div>
        <div className="additional-info">
          <div className="info-section">
            <div className="info-card">
              <div className="label">Beam ID</div>
              <div className="value">{user?.beamId || "N/A"}</div>
            </div>
            <div className="info-card">
              <div className="label green">Weight</div>
              <div className="value green">
                {getUserBioKeyValue(user, "weight") || "N/A"} kg
              </div>
            </div>
            <div className="info-card">
              <div className="label blue">Height</div>
              <div className="value blue">
                {getUserBioKeyValue(user, "height") || "N/A"} cm
              </div>
            </div>
            <div className="info-card">
              <div className="label orange">Gender</div>
              <div className="value orange">
                {getUserBioKeyValue(user, "gender") || "N/A"}
              </div>
            </div>
            <div className="info-card">
              <div className="label light-blue">Date of Birth</div>
              <div className="value light-blue">
                {getUserBioKeyValue(user, "dateOfBirth") || "N/A"}
              </div>
            </div>
            <div className="info-card wide">
              <div className="label bright-blue">BMI (body mass index)</div>
              <div className="value bright-blue">
                {getUserBioKeyValue(user, "bmi") || "N/A"}
              </div>
            </div>
          </div>
          <div className="medical-history-section">
            <div className="medical-history-card">
              <div className="label orange">Allergies</div>
              <div className="value orange">
                {getUserBioKeyValue(user, "allergies") || "N/A"}
              </div>
            </div>
            <div className="medical-history-card">
              <div className="label bright-blue">Mobility</div>
              <div className="value bright-blue">
                {getUserBioKeyValue(user, "mobility") || "N/A"}
              </div>
            </div>
            <div className="medical-history-card">
              <div className="label blue">Medication</div>
              <div className="value blue">
                {getUserBioKeyValue(user, "medication") || "N/A"}
              </div>
            </div>
          </div>
        </div>
      </div>

      <React.Fragment>
        <Row className="map-chart mt-4">
          <Col xs={24} sm={12} md={8}>
            <div className="main-column message-panel mr-4">
              <div className="main-content p-0">
                <div className="main-header pt-3 pr-5 pl-4 border-bottom-0">
                  <div className="d-flex">
                    <h4 className="ml-3" style={{ color: "#000" }}>
                      Video call
                    </h4>
                  </div>
                  <div className="d-flex">
                    <ReactSVG
                      src="/images/expand-icon.svg"
                      className="close-icon mr-4"
                    />
                    <ReactSVG
                      src="/images/close-icon.svg"
                      className="close-icon"
                    />
                  </div>
                </div>
                {videoToken && (
                  <iframe
                    title="Video call"
                    style={{ height: "100%", width: "100%", border: "none" }}
                    allow="camera; microphone"
                    src={`https://video.staging.beam.live/room/${videoToken}`}
                  />
                )}
              </div>
            </div>
          </Col>
          <Col xs={24} sm={12} md={8}>
            <div className="main-column message-panel mr-4">
              <div className="main-content">
                <div className="main-header">
                  <div className="d-flex">
                    <h3 className="ml-3" style={{ color: "#000" }}>
                      Max Heart Rate (bpm)
                    </h3>
                  </div>
                  <div className="d-flex">
                    <ReactSVG
                      src="/images/expand-icon.svg"
                      className="close-icon mr-4"
                    />
                    <ReactSVG
                      src="/images/close-icon.svg"
                      className="close-icon"
                    />
                  </div>
                </div>
                {/* <div className="d-flex justify-content-center align-self-center"> */}
                {/* <Pie key={redrawCount} data={chartData} redraw /> */}
                <HeartRateMonitor update={iotUpdated?.[0]} />
                {/* </div> */}
              </div>
            </div>
          </Col>
          <Col xs={24} sm={12} md={8}>
            <div className="main-column message-panel">
              <div className="main-content">
                <div className="main-header">
                  <div className="d-flex">
                    <h3 className="ml-3" style={{ color: "#000" }}>
                      Blood pressure (mmHg)
                    </h3>
                  </div>
                  <div className="d-flex">
                    <ReactSVG
                      src="/images/expand-icon.svg"
                      className="close-icon mr-4"
                    />
                    <ReactSVG
                      src="/images/close-icon.svg"
                      className="close-icon"
                    />
                  </div>
                </div>
                {/* <VerticalGraph data={barChartData} /> */}

                <BloodPressureMonitor update={iotUpdated?.[0]} />
              </div>
            </div>
          </Col>
        </Row>
      </React.Fragment>

      <Row gutter={20} className="mt-4 scrollable-table">
        <Col
          xs={24}
          sm={24}
          md={24}
          style={{ maxHeight: 1000, overflow: "scroll" }}
        >
          <div className="d-flex justify-content-space-between">
            <h3>Analytics table</h3>
            <div>
              <Button
                className="beam-btn icon-btn"
                style={{
                  // float: "right",
                  margin: "10px 10px 10px 0",
                }}
                onClick={() => {
                  setShowTableFilterModal(true);
                }}
              >
                <FilterOutlined />
              </Button>

              <Button
                className="beam-btn icon-btn"
                style={{
                  // float: "right",
                  margin: "10px 10px 10px 0",
                }}
                loading={projectFilterLoading}
                onClick={() => {
                  setProjectFilterLoading(true);
                  getHistoricalRx();
                }}
              >
                {!projectFilterLoading && <RedoOutlined />}
              </Button>
            </div>
          </div>

          <Table
            dataSource={tableDataSource}
            onRow={(record) => {
              return {
                onDoubleClick: () => {
                  const query = new URLSearchParams(search);
                  const userId = query.get("userId");
                  socket.publishToEvent(
                    SocketTopics.PublishPageTopics,
                    getFocusPagePublishTopic(record?.action?.pageId, userId),
                    {
                      page: record?.action?.page,
                    }
                  );
                },
              };
            }}
            columns={tableColumns?.filter((x) => {
              return tableHideList?.indexOf(x.key) === -1;
            })}
            scroll={{ x: true }}
          />
          {/* <Row>
            <Col
              span={24}
              className="d-flex justify-content-center align-items-center"
            >
              <Button
                className="beam-btn mt-3 mb-3"
                loading={projectFilterLoading}
                onClick={() => {
                  setProjectFilterLoading(true);
                  searchPage(pageOffset.current);
                }}
              >
                Load more
              </Button>
            </Col>
          </Row> */}
          {showTableFilterModal && (
            <TableFilterModal
              socket={socket}
              tableHideList={tableHideList}
              onChange={(e) => {
                setTableHideList(e);
                localStorage.setItem("tableHideList", JSON.stringify(e));
                setShowTableFilterModal(false);
              }}
              columns={tableColumns}
              onClose={() => {
                setShowTableFilterModal(false);
              }}
            />
          )}
        </Col>
      </Row>
    </React.Fragment>
  );
};

export default RxDashboardModal;
