  function getScheduleSummary(schedule: {
    mode: "repeat" | "custom" | null;
    customDates: dayjs.Dayjs[];
    repeatType: "daily" | "weekly" | "monthly";
    repeatDays: number[];
    everyX: number;
    monthRepeatDates: number[];
    endUntil: dayjs.Dayjs | null;
  }): string {
    if (!schedule) return "";

    console.log('schedule', schedule);

    if (schedule.mode === "custom") {
      if (!schedule?.customDates?.length) return "No custom dates selected.";
      const dates = schedule.customDates
        .map((d) => dayjs(d).format("MMM D, YYYY"))
        .join(", ");
      return `Custom schedule on: ${dates}`;
    }

    if (schedule.mode === "repeat") {
      let base = "Repeat ";

      if (schedule.repeatType === "daily") {
        base += `every ${schedule.everyX} day${schedule.everyX > 1 ? "s" : ""}`;
      }

      if (schedule.repeatType === "weekly") {
        const weekdays = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
        const days = schedule.repeatDays.map((i) => weekdays[i]).join(", ");
        base += `on ${days} every week`;
      }

      if (schedule.repeatType === "monthly") {
        const dates = schedule.monthRepeatDates.map((d) => `${d}${getOrdinal(d)}`).join(", ");
        base += `on the ${dates} of every month`;
      }

      if (schedule.endUntil) {
        base += ` until ${dayjs(schedule.endUntil).format("MMM D, YYYY")}`;
      }

      return base;
    }

    return "No schedule selected.";
  }

