import React, { FC, useEffect, useRef, useState, useMemo } from "react";
import { Button, Row, Col, Table, Input, Skeleton } from "antd";
import { pushNotification } from "utils/notifications";
import _ from "lodash";
import { ReactSVG } from "react-svg";
import {
  SearchOutlined,
  ArrowLeftOutlined,
  EditOutlined,
  SyncOutlined,
} from "@ant-design/icons";
import { wrapRequestPayload } from "../../../../helpers/request/RequestPayload";
import {
  getAdminRolesTopic,
  getProjectsSubscriptionTopic,
  getProjectsRequestPublishTopic,
  getVehiclesPublishTopic,
  getVehiclesSubscriptionTopic,
  syncUserRequestPublishTopic,
  syncUserSubscriptionTopic,
} from "hooks/MQTTConstants";
import { SocketTopics, UserTopics } from "constants/enums";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { useDispatch } from "react-redux";
import useSocketActions from "../../../../hooks/socketActions";
import { formatForRedis } from "utils/appUtil";
import { USER_TYPES, PERMISSION_TYPES } from "utils/PageTypes";
import { GET_AGGREGATE } from "../../../../reducers/reducer";
import Loader from "react-loader-spinner";
import "./Dashboard.scss";

let timeout;

const DispatcherModal: FC<{
  socket: ISocket;
  params?: any;
  componentUuid?: string;
  userRole?: any;
}> = ({ socket, params, componentUuid, userRole }) => {
  const { selectedPage, encrypted_token, projects, adminUserRoles } =
    useSelector((state: RootState) => state.auth);
  const dispatch = useDispatch();
  const [tableDataSource, setTableDataSource] = useState<any>([]);
  const [tableColumns, setTableColumns] = useState<any>([]);
  useState<boolean>(false);
  const [loading, setLoading] = useState<boolean>(false);
  useState<boolean>(false);
  const { getUserRequestPayload } = useSocketActions();
  // const adminRoles = useRef<any>(undefined);
  // const projects = useRef<any>(undefined);
  const drivers = useRef<any>();
  const [isEditModalVisible, setIsEditModalVisible] = useState<any>(undefined);
  const isMounted = useRef(true);
  const [loadingRowKey, setLoadingRowKey] = useState<string | null>(null);

  const formatUserFilterText = (text: string) => {
    var result = "";
    let comp = text
      .trim()
      .split(" ")
      .filter((word) => word.length > 2)
      .map((x) => {
        return "*" + formatForRedis(x) + "*";
      });
    if (comp.length == 0) {
      return result;
    }
    comp.forEach((element) => {
      result += `@firstName:(${element})|@lastName:(${element})|`;
    });
    result += `@beamIds:{${comp.join("|")}}`;
    return `(${result})`;
  };

  const addUserToOrgPages = (userId) => {
    return new Promise((resolve, reject)=>{
      socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        syncUserRequestPublishTopic(encrypted_token?.connectionId),
        wrapRequestPayload({ userId: userId?.toString(), serviceId: projects?.userServiceId })
      );

      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        syncUserSubscriptionTopic(encrypted_token?.connectionId),
        (response) => {
          resolve(response);
        }
      )
    })
  }

  const columns = useMemo(
    () => [
      {
        title: "Status",
        key: "userStatus",
        dataIndex: "userStatus",
        render: (status: string) => (
          <Button className="beam-btn icon-btn ml-2">
            <ReactSVG
              src="/images/flag-icon.svg"
              className={`${status ?? "gray"}-icon`}
            />
          </Button>
        ),
      },
      {
        title: "Name",
        key: "name",
        dataIndex: "name",
      },
      {
        title: "Custom id",
        key: "customId",
        dataIndex: "customId",
      },
      {
        title: "Email",
        key: "email",
        dataIndex: "email",
      },
      {
        title: "Phone",
        key: "phone",
        dataIndex: "phone",
      },

      {
        title: "Action",
        key: "action",
        dataIndex: "action",
        render: (action: any) => (
          <Row style={{ width: 135 }}>
            <Col span={8}>
              <Button
                style={{ boxShadow: "none" }}
                className="beam-btn icon-btn yellow-btn cover"
                loading={loadingRowKey === action.userId}
                onClick={async () => {
                  console.log("action", action);
                  setLoadingRowKey(action.userId);
                  // await new Promise((res) => setTimeout(res, 3000));
                  try {
                    // ... your async action here ...
                    const response: any = await addUserToOrgPages(action.userId);
                    await new Promise((res) => setTimeout(res, 3000));
                    console.log('response', response);
                    if(response?.response?.status){
                      pushNotification(
                        "Sync requested successfully",
                        "success",
                        "TOP_CENTER",
                        1000
                      );
                    }
                    else{
                      pushNotification(
                        response?.response?.data.details,
                        "error",
                        "TOP_CENTER",
                        1000
                      );
                    }
                  } finally {
                    
                    setLoadingRowKey(null);
                  }
                }}
              >
                {loadingRowKey !== action.userId && <SyncOutlined />}
                {/* <EditOutlined /> */}
              </Button>
            </Col>
          </Row>
        ),
      },
    ],
    [loadingRowKey]
  );

  const getUsersByRole = (roles, type, filterText = undefined) => {
    let searchQuery = `@serviceId:{'${formatForRedis(
      projects?.userServiceId
    )}'}`;
    if (filterText && filterText.length > 2) {
      searchQuery += formatUserFilterText(filterText);
    }
    let userRoles;
    switch (type) {
      case USER_TYPES.Dispatcher:
        userRoles = roles.filter(
          (x: any) =>
            x.permissions.indexOf(PERMISSION_TYPES.Cad) !== -1 ||
            x.permissions.indexOf(PERMISSION_TYPES.Admin) !== -1
        );
        break;
      case USER_TYPES.Live:
        userRoles = roles.filter(
          (x: any) =>
            x.permissions.indexOf(PERMISSION_TYPES.Live) !== -1 &&
            x.permissions.indexOf(PERMISSION_TYPES.Admin) === -1
        );
        break;
      case USER_TYPES.Responder:
        userRoles = roles.filter(
          (x: any) => x.permissions.indexOf(PERMISSION_TYPES.OnMove) !== -1
          // &&
          //   x.permissions.indexOf(PERMISSION_TYPES.Admin) === -1
        );
        break;
      case USER_TYPES.Manager:
        userRoles = roles.filter(
          (x: any) =>
            x.permissions.indexOf(PERMISSION_TYPES.Cad) !== -1 &&
            x.permissions.indexOf(PERMISSION_TYPES.OnMove) !== -1 &&
            x.permissions.indexOf(PERMISSION_TYPES.Admin) === -1
        );
        break;
    }
    console.log("selected user roles", userRoles);

    const rolesQuery = userRoles.map((y: any) => {
      return `@roleId === '${y._id}'`;
    });
    const userRequest: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
          searchQuery,
          searchOptions: "TIMEOUT 5000",
        },
        list: {
          objectIds:
            userRole === "driver" ? [encrypted_token?.userId] : undefined,
        },
        load: {
          id: "$.objectId",
          status: "$.nonpersistent.static.live.status",
          live: "$.persistent.static.live",
          roleId: "$..admin.profile.roleId",
          schoolBus: "$..schoolBus",
        },
      },
      apply: {
        expression: "",
        name: "",
      },
      result: {},
      filter: {
        expression: `exists(@roleId) && (${rolesQuery.join("||")})`,
        // expression: "",
      },
      anyStatus: false,
    };
    setLoading(true);
    dispatch(
      GET_AGGREGATE({
        requestData: userRequest,
        callback: (response) => {
          setLoading(false);
          let sourceData = [];
          // let columns: any = [
          //   {
          //     title: "Status",
          //     key: "userStatus",
          //     dataIndex: "userStatus",
          //     render: (status: string) => (
          //       <Button className="beam-btn icon-btn ml-2">
          //         <ReactSVG
          //           src="/images/flag-icon.svg"
          //           className={`${status ?? "gray"}-icon`}
          //         />
          //       </Button>
          //     ),
          //   },
          //   {
          //     title: "Name",
          //     key: "name",
          //     dataIndex: "name",
          //   },
          //   {
          //     title: "Custom id",
          //     key: "customId",
          //     dataIndex: "customId",
          //   },
          //   {
          //     title: "Email",
          //     key: "email",
          //     dataIndex: "email",
          //   },
          //   {
          //     title: "Phone",
          //     key: "phone",
          //     dataIndex: "phone",
          //   },
          //   // {
          //   //   title: "Operation start location",
          //   //   key: "operationLocation",
          //   //   dataIndex: "operationLocation",
          //   // },
          //   // {
          //   //   title: "License number",
          //   //   key: "licenseNumber",
          //   //   dataIndex: "licenseNumber",
          //   // },
          //   // {
          //   //   title: "License type",
          //   //   key: "licenseType",
          //   //   dataIndex: "licenseType",
          //   // },
          //   // {
          //   //   title: "License expiry",
          //   //   key: "licenseExpiry",
          //   //   dataIndex: "licenseExpiry",
          //   // },
          //   {
          //     title: "Action",
          //     key: "action",
          //     dataIndex: "action",
          //     render: (action: any) => (
          //       <Row style={{ width: 135 }}>
          //         <Col span={8}>
          //           <Button
          //             style={{ boxShadow: "none" }}
          //             className="beam-btn icon-btn yellow-btn cover"
          //             loading={loadingRowKey === action.key}
          //             onClick={async () => {
          //               setLoadingRowKey(action.key);
          //               await new Promise(res => setTimeout(res, 3000));
          //               try {
          //                 // ... your async action here ...
          //               } finally {
          //                 setLoadingRowKey(null);
          //               }
          //             }}
          //           >
          //             <SyncOutlined />
          //             {/* <EditOutlined /> */}
          //           </Button>
          //         </Col>
          //       </Row>
          //     ),
          //   },
          // ];
          response?.map((x, i) => {
            const pickupLocation: any = Object.values(
              x?.schoolBus?.locationList || {}
            )?.find((x: any) => {
              return x.locationType === "operationStart";
            });
            sourceData.push({
              key: x.id,
              userStatus: x?.status?.name,
              name: `${x?.live?.profile?.firstName} ${x?.live?.profile?.lastName}`,
              email: x?.live?.alternativeIds?.email,
              phone: x?.live?.alternativeIds?.phone,
              customId: x?.live?.alternativeIds?.customId,
              operationLocation: pickupLocation?.location?.attributes?.address,
              licenseNumber: x?.schoolBus?.license?.licenseNumber,
              licenseType: x?.schoolBus?.license?.licenseType,
              licenseExpiry: x?.schoolBus?.license?.expiryDate,
              action: {
                userId: x?.id,
                user: x,
              },
            });
          });
          drivers.current = sourceData;
          // setTableColumns(columns);
          setTableDataSource(sourceData);
        },
      })
    );
  };

  useEffect(() => {
    isMounted.current = true;
    return () => {
      isMounted.current = false;
    };
  }, []);

  useEffect(() => {
    if (projects?.adminUserId) {
      getUsersByRole(adminUserRoles, USER_TYPES.Dispatcher);
    }
  }, [projects]);

  const loadingColumns = [
    {
      title: "...",
      dataIndex: "loading",
      key: "loading",
      render: () => (
        <Skeleton
          active
          title={false} // Disable the title if you only want paragraph lines
          paragraph={{
            rows: 7,
            width: "100%",
          }}
        />
      ),
    },
  ];

  // Placeholder loading data to fill the rows
  const loadingData = Array(1)
    .fill({})
    .map((_, index) => ({ key: `loading-${index}` }));

  return (
    <React.Fragment>
      <Row>
        <Col
          span={24}
          className="d-flex justify-content-space-between align-items-space-between"
        >
          <div>
            <h2 style={{ marginBottom: 0 }}>Dispatcher</h2>
            <p>Home &gt; Dispatcher</p>
          </div>

          <Input
            onChange={(e) => {
              let value: string = e.target.value;
              if (timeout) clearTimeout(timeout);
              timeout = setTimeout(() => {
                if (value.includes("-")) value = formatForRedis(value);
                getUsersByRole(adminUserRoles, USER_TYPES.Responder, value);
              }, 500);
            }}
            style={{ width: 350 }}
            placeholder={`Search user`}
            suffix={
              // loading ? (
              //   <Loader type="TailSpin" color="#000" height={15} width={15} />
              // ) : (
              //   <SearchOutlined />
              // )
              <SearchOutlined />
            }
          />
        </Col>
      </Row>

      <Row
        gutter={20}
        className="scrollable-table mt-3"
        style={{ display: "grid", marginRight: -20 }}
      >
        <Col
          xs={24}
          sm={24}
          md={24}
          style={{ maxHeight: 1000, overflow: "scroll" }}
        >
          <Table
            dataSource={loading ? loadingData : tableDataSource}
            columns={loading ? loadingColumns : columns}
            pagination={false}
            // className={tableDataSource?.length > 0 ? "" : "table-empty"}
            onRow={(record) => {
              return {
                onDoubleClick: () => {
                  console.log("on double click row", record);
                },
                onClick: () => {},
              };
            }}
            scroll={{ x: true }}
            onChange={(e) => {}}
            rowClassName={(record, index) => {
              if (record?.key === selectedPage?.page?.pageId)
                return "row-selected";
              return "";
            }}
          />
        </Col>
      </Row>
    </React.Fragment>
  );
};

export default DispatcherModal;
