import React, { useEffect, useState } from "react";
import {
  Table,
  Button,
  Modal,
  Form,
  Input,
  DatePicker,
  Tag,
  Row,
  Col,
} from "antd";
import type { ColumnsType } from "antd/es/table";
import type { FormInstance } from "antd/es/form";
import {
  getCustomCreateRequestPublishTopic,
  getCustomUpdateRequestPublishTopic,
  getCustomCreateSubscriptionTopic,
  getCustomUpdateSubscriptionTopic,
} from "hooks/MQTTConstants";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { pushNotification } from "utils/notifications";
import { GET_AGGREGATE } from "../../../../../reducers/reducer";
import { useDispatch } from "react-redux";
import { formatForRedis } from "utils/appUtil";
import { SocketTopics, UserTopics } from "constants/enums";
import moment from "moment";
import isoWeek from "dayjs/plugin/isoWeek";
import dayjs from "dayjs";
dayjs.extend(isoWeek);


const LeaveRequest = (props) => {
  const { socket, userId } = props;
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [leaveRequests, setLeaveRequests] = useState([
    // {
    //   key: "1",
    //   startDate: "2024-11-27",
    //   endDate: "2024-11-28",
    //   reason: "Medical leave",
    //   status: "Pending",
    // },
  ]);

  const [form] = Form.useForm<FormInstance>();
  const { encrypted_token } = useSelector((state: RootState) => state.auth);
  const dispatch = useDispatch();

  // Columns for the table
  const columns: ColumnsType<(typeof leaveRequests)[0]> = [
    {
      title: "Start Date",
      dataIndex: "startDate",
      key: "startDate",
    },
    {
      title: "End Date",
      dataIndex: "endDate",
      key: "endDate",
    },
    {
      title: "Reason",
      dataIndex: "reason",
      key: "reason",
    },
    {
      title: "Status",
      dataIndex: "status",
      key: "status",
      render: (status) => {
        const color =
          status === "Accepted"
            ? "green"
            : status === "Rejected"
              ? "red"
              : "orange";
        return <Tag color={color}>{status}</Tag>;
      },
    },
  ];

  // Function to open modal
  const showModal = () => {
    setIsModalOpen(true);
  };

  const disableThisWeek = (current: any) => {
    if (!current) return false;

    const today = moment();
    const dayOfWeek = today.isoWeekday(); // 1 (Mon) - 7 (Sun)

    // Define this week’s Monday and Sunday
    const thisMonday = today.clone().startOf("isoWeek");
    const thisSunday = today.clone().endOf("isoWeek");

    if (dayOfWeek < 3) {
      // Before Wednesday → block only this week
      return (
        current.isBefore(thisMonday, "day") ||
        current.isSameOrBefore(thisSunday, "day")
      );
    } else {
      // Wednesday or later → block this week + next week
      const nextSunday = thisSunday.clone().add(1, "week");
      return (
        current.isBefore(thisMonday, "day") ||
        current.isSameOrBefore(nextSunday, "day")
      );
    }
  };

  const getTimeOff = () => {
    const customerRequest: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:custom:createdAt`,
          // searchIndex: "beamdev:custom:id",
          searchQuery: `@partitions:{'org\\:${formatForRedis(
            encrypted_token?.cudbServiceId || encrypted_token?.serviceId
          )}'}@partitions:{user\\:${userId
            }}@partitions:{type\\:timeoff}`,
          searchOptions: "VERBATIM TIMEOUT 10000",
        },
        load: {
          info: "$.info",
          objectId: "$.objectId",
        },
      },
      filter: {
        expression: "",
      },
    };
    dispatch(
      GET_AGGREGATE({
        requestData: customerRequest,
        callback: (response) => {
          console.log("response here", response);
          setLeaveRequests(
            response?.map((x) => {
              return {
                key: x?.objectId,
                ...x?.info,
              };
            })
          );
        },
      })
    );
  };

  useEffect(() => {
    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      getCustomCreateSubscriptionTopic(encrypted_token?.connectionId),
      (response) => {
        //   setSaving(false);
        console.log("response", response?.response?.data?.id);
        //   setSelectedCustomId(response?.response?.data?.id);
        // pushNotification(
        //   "Timesheet saved successfully",
        //   "success",
        //   "TOP_CENTER",
        //   1000
        // );
        getTimeOff();
      }
    );
    getTimeOff();
  }, []);

  // Function to handle form submission
  const handleOk = () => {
    form.validateFields().then((values: any) => {
      const requestData: any = {
        timestamp: new Date().getTime(),
        startDate: values.startDate.format("YYYY-MM-DD hh:mm A"),
        startDateTimestamp: values.startDate.startOf("day").valueOf(),
        endDate: values.endDate.format("YYYY-MM-DD hh:mm A"),
        endDateTimestamp: values.endDate.endOf("day").valueOf(),
        reason: values.reason,
        status: "Pending",
      };
      //   setLeaveRequests((prev) => [...prev, requestData]);
      form.resetFields();
      setIsModalOpen(false);

      const customChanges = [
        {
          op: "add",
          path: "/partitions",
          value: [
            `org:${encrypted_token?.cudbServiceId || encrypted_token?.serviceId}`,
            `user:${userId}`,
            `type:timeoff`,
            `date:${moment().format("YYYYMMDD")}`,
          ],
        },
        {
          op: "add",
          path: "/createdAt",
          value: new Date().getTime(),
        },
        {
          op: "add",
          path: "/info",
          value: requestData,
        },
      ];
      console.log("custom changes", customChanges);

      socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        getCustomCreateRequestPublishTopic(encrypted_token?.connectionId),
        wrapRequestPayload({
          changes: customChanges,
        })
      );
    });
  };

  // Function to close modal
  const handleCancel = () => {
    setIsModalOpen(false);
  };

  return (
    <div>
      {/* Table for listing leave requests */}
      <Table dataSource={leaveRequests} columns={columns} pagination={false} />

      {/* Button to apply for leave */}
      <Button
        className="beam-btn green-btn cover w-100"
        onClick={showModal}
        style={{ marginTop: 16 }}
      >
        Apply timeoff
      </Button>

      {/* Modal for applying leave */}
      <Modal
        title="Apply for timeoff"
        className="beam-modal"
        visible={isModalOpen}
        // onOk={handleOk}
        onCancel={handleCancel}
      // okText="Submit"
      // cancelText="Cancel"
      >
        <Form form={form} layout="vertical">
          <Form.Item
            label="Start Date"
            name="startDate"
            rules={[
              { required: true, message: "Please select the start date!" },
            ]}
          >
            <DatePicker getPopupContainer={() => document.body} className={'mobile-datepicker-modal'} inputReadOnly showTime={{ use12Hours: true, format: 'hh:mm A' }} format="YYYY-MM-DD hh:mm A" disabledDate={disableThisWeek} />
          </Form.Item>
          <Form.Item
            label="End Date"
            name="endDate"
            rules={[{ required: true, message: "Please select the end date!" }]}
            className="mt-3"
          >
            <DatePicker getPopupContainer={() => document.body} className={'mobile-datepicker-modal'} inputReadOnly showTime={{ use12Hours: true, format: 'hh:mm A' }} format="YYYY-MM-DD hh:mm A" disabledDate={disableThisWeek} />
          </Form.Item>
          <Form.Item
            label="Reason for Leave"
            name="reason"
            rules={[
              { required: true, message: "Please provide a reason for leave!" },
            ]}
            className="mt-3"
          >
            <Input.TextArea autoSize={{ minRows: 3, maxRows: 6 }} />
          </Form.Item>

          <Form.Item>
            <Row className="action-grp mt-4">
              <Col span={12} xs={12} sm={12}>
                <Button
                  className="beam-btn orange-btn bordered w-full"
                  onClick={() => handleCancel()}
                >
                  Cancel
                </Button>
              </Col>
              <Col span={12} className="pl-2" xs={12} sm={12}>
                <Button
                  className="beam-btn green-btn cover w-full"
                  onClick={() => handleOk()}
                >
                  Save
                </Button>
              </Col>
            </Row>
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
};

export default LeaveRequest;
