const EditDriverModal: FC<{
  onClose: () => void;
  socket?: ISocket;
  student?: any;
  adminRoles?: any;
  onAdd?: () => void;
}> = (props) => {
  const { onClose, socket, student, adminRoles, onAdd } = props;
  const [isModalVisible, setIsModalVisible] = useState(true);
  const [registerForm] = Form.useForm();
  const [error, setError] = useState<string>("");
  const [saving, setSaving] = useState(false);
  const { projects } = useSelector((state: RootState) => state.auth);
  const { updateUserRequestPayloadV2 } = useSocketActions();
  const dispatch = useDispatch();

  const handleCancel = () => {
    setIsModalVisible(false);
    onClose && onClose();
  };

  useEffect(() => {
    if (student?.scheduleId) {
      registerForm.setFieldsValue({
        ...student?.data,
        drivers: student?.data?.drivers
          ? {
              type: "responder",
              responders: Object.values(student?.data?.drivers || {})?.map(
                (x: any) => {
                  return { id: x?.userId, beamId: x?.beamId };
                }
              ),
              values: Object.values(student?.data?.drivers || {})?.map(
                (x: any) => {
                  return x?.userId;
                }
              ),
            }
          : undefined,
        time: student?.data?.scheduleTime,
      });
    }
  }, []);

  const onSubmitHandler = async (values: any) => {
    console.log("values", values);
    const {
      name,
      daysOfTheWeek,
      notificationType,
      time,
      drivers,
    } = values;
    const requestData = {
      name,
      daysOfTheWeek,
      scheduleTime: time,
      notificationType,
      drivers: drivers?.responders
        ?.map((x) => {
          return { userId: x?.id, beamId: x?.beamId };
        })
        ?.reduce((acc, item, index) => {
          acc[item.userId] = {
            ...item,
          };
          return acc;
        }, {} as { [key: string]: any }),
      timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
      cudbServiceId: projects?.userServiceId,
    };
    // const notifyDate = new Date(time);
    const originalTime = moment.tz(
      time,
      "MM/DD/YYYY HH:mm",
      Intl.DateTimeFormat().resolvedOptions().timeZone
    );
    const convertedTime = originalTime.utc().format("MM/DD/YYYY HH:mm");
    const notifyDate = new Date(convertedTime);

    // const cron = dateToCron(notifyDate, daysOfTheWeek);
    const cron = `${notifyDate.getMinutes()} ${notifyDate.getHours()} * 0-11 *`;
    if (!student?.scheduleId) {
      const createRequest = {
        cron,
        topic: `${process.env.REACT_APP_ECO_SYSTEM}/service/scheduler-service/service/dps/sendReminderNotification`,
        data: requestData,
        info: {},
        to: 4920566400000,
      };
      console.log("request", createRequest);
      setSaving(true);
      const response: any = await createSchedule(createRequest);
      const objectId = response?.data?.id?.toString();
      const updateRequest = {
        objectId,
        changes: [
          {
            op: "replace",
            path: "/partitions",
            value: [`org:${projects?.userServiceId}`, "type:notification"],
          },
        ],
      };
      await updateSchedule(updateRequest);
      pushNotification(
        "Schedule created successfully",
        "success",
        "TOP_CENTER",
        3000
      );
    } else {
      setSaving(true);
      const objectId = student?.scheduleId?.toString();
      const updateRequest = {
        objectId,
        changes: [
          {
            op: "replace",
            path: "/cron",
            value: cron,
          },
          {
            op: "replace",
            path: "/data",
            value: requestData,
          },
        ],
      };
      await updateSchedule(updateRequest);
      pushNotification(
        "Schedule updated successfully",
        "success",
        "TOP_CENTER",
        3000
      );
    }
    setSaving(false);
    onAdd();
  };

  const createSchedule = async (requestData) => {
    return new Promise((resolve, reject) => {
      dispatch(
        CREATE_SCHEDULE({
          request: requestData,
          callback: (response) => {
            console.log("create response ehere", response);
            resolve(response);
          },
        })
      );
    });
  };

  const updateSchedule = async (requestData) => {
    return new Promise((resolve, reject) => {
      dispatch(
        UPDATE_SCHEDULE({
          request: requestData,
          callback: (response) => {
            console.log("create response ehere", response);
            resolve(response);
          },
        })
      );
    });
  };

  const daysOfWeek = [
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday",
    "Sunday",
  ];


  const ScheduleInformationInput: React.FC<any> = ({ value, onChange }) => {
    const ScheduleTimeInput = (props) => {
      const { value, onChange } = props;
      return (
        <TimeInput
          placeholder={`Select Time`}
          value={value ? moment(value).format("HH:mm") : undefined}
          onChange={onChange}
        />
      );
    };

    return (
      <React.Fragment>
        <Form.Item
          label="Notification Schedule Name"
          name="name"
          rules={[
            { required: true, message: "Please input the schedule name" },
          ]}
        >
          <Input placeholder="Enter name" />
        </Form.Item>

        <Form.Item
          className="mt-3"
          label="Notification Type"
          name="notificationType"
          rules={[
            { required: true, message: "Please select notification type" },
          ]}
        >
          <Radio.Group>
            <Radio value="push">Push</Radio>
            <Radio value="email">Email</Radio>
            <Radio value="sms">SMS</Radio>
          </Radio.Group>
        </Form.Item>

        <Form.Item
          className="mt-3"
          label={`Schedule Days`}
          name={`daysOfTheWeek`}
          rules={[{ required: true, message: "Days selection is required" }]}
        >
          <Select
            placeholder={`Select Days`}
            mode="multiple"
            style={{ width: "100%" }}
          >
            {daysOfWeek.map((day) => (
              <Select.Option key={day} value={day}>
                {day}
              </Select.Option>
            ))}
          </Select>
        </Form.Item>

        <Form.Item
          className="mt-3"
          label={`Schedule Time`}
          name={`time`}
          rules={[{ required: true, message: "Time is required" }]}
        >
          <ScheduleTimeInput onChange={(time) => {}} />
        </Form.Item>
      </React.Fragment>
    );
  };

  return (
    <Modal
      title={
        student?.scheduleId ? `Edit (${student?.data?.name})` : "Add notification schedule"
      }
      visible={isModalVisible}
      onCancel={handleCancel}
      width="800px"
      className="beam-modal"
      // width="100%"
      // className="beam-modal analytics-summary-modal"
      footer={[]}
      destroyOnClose={true}
    >
      <Form
        className="auth-form"
        name="register-form"
        id="register-form"
        layout="vertical"
        form={registerForm}
        onFinish={onSubmitHandler}
        requiredMark={false}
      >
        <div className="main-cards mt-3">
          {/* <Collapse
            activeKey={["vehicle", "driver", "preferences"]}
            bordered={false}
            className="simple-collapse d-flex flex-column"
          >
            <Panel
              header={
                <div className="d-flex">
                  <h5 className="m-2">Vehicle Information</h5>
                </div>
              }
              key={"vehicle"}
            >
              <Form.Item name="vehicle">
                <VehicleInformationInput />
              </Form.Item>
            </Panel>

            <Panel
              header={
                <div className="d-flex">
                  <h5 className="m-2">Driver Assignment</h5>
                </div>
              }
              key={"driver"}
            >
              <Form.Item name="responder">
                <ResponderInput
                  placeholder="Assign driver"
                  adminRoles={adminRoles}
                />
              </Form.Item>
            </Panel>

            <Panel
              header={
                <div className="d-flex">
                  <h5 className="m-2">Preferences</h5>
                </div>
              }
              key={"preferences"}
            >
              <Form.Item name="preferences">
                <AdditionalConstraints />
              </Form.Item>
            </Panel>
          </Collapse> */}

          <Form.Item name="schedule">
            <ScheduleInformationInput />
          </Form.Item>

          

          <Form.Item name="drivers" label="Driver" className="mt-3">
            <ResponderInput
              multiple={true}
              placeholder="Select drivers"
              adminRoles={adminRoles}
            />
          </Form.Item>

        
        </div>

        <Row className="action-grp mt-3">
          <Col span={24}>
            <Form.Item>
              <Button
                className="beam-btn green-btn cover w-full"
                loading={saving}
                type="primary"
                htmlType="submit"
                onClick={() => setError("")}
              >
                Save
              </Button>
            </Form.Item>
          </Col>
        </Row>
      </Form>
    </Modal>
  );
};

export default EditDriverModal;
