import React from "react";
import { Row, Col, Button } from "antd";
import { FilterOutlined, RedoOutlined } from "@ant-design/icons";
import { useDashboard } from "../context";

// Status tiles (color -> label -> statusCount key) shown left-to-right.
const STATUS_TILES: { color: string; label: string; countKey: string }[] = [
  { color: "brown", label: "Advance", countKey: "brown" },
  { color: "purple", label: "Dispatching", countKey: "purple" },
  { color: "amber", label: "Assigned", countKey: "amber" },
  { color: "aqua", label: "Arrived", countKey: "aqua" },
  { color: "blue", label: "Started", countKey: "blue" },
  { color: "red", label: "Escalated", countKey: "red" },
  { color: "green", label: "Completed", countKey: "green" },
  { color: "grey", label: "Processed", countKey: "grey" },
  { color: "black", label: "Cancelled", countKey: "black" },
];

const StatusFilterBar: React.FC = () => {
  const {
    statusSelected,
    setStatusPagePaths,
    statusCount,
    showTableFilterModal,
    setShowTableFilterModal,
    projectFilterLoading,
    statusFilterLoading,
    setProjectFilterLoading,
    searchPage,
  } = useDashboard();

  return (
    <Row className="d-flex mb-2">
      <Col
        span={2}
        className={`border rounded text-center p-2 mx-2 cursor-pointer ${statusSelected === undefined ? "status-selected" : ""
          }`}
        onClick={() => {
          setStatusPagePaths(undefined);
        }}
      >
        <div>
          <span>All</span>
          <h4>{statusCount.live}</h4>
        </div>
      </Col>

      {STATUS_TILES.map((tile) => (
        <Col
          key={tile.color}
          span={2}
          className={`border rounded text-center p-2 mx-2 cursor-pointer ${statusSelected === tile.color ? "status-selected" : ""
            }`}
          onClick={() => {
            setStatusPagePaths(tile.color);
          }}
        >
          <div className={tile.color}>
            <span>{tile.label}</span>
            <h4>{statusCount[tile.countKey]}</h4>
          </div>
        </Col>
      ))}

      <div>
        <Button
          className="beam-btn icon-btn"
          style={{ float: "right", margin: "10px 0 10px 0" }}
          onClick={() => {
            setShowTableFilterModal(!showTableFilterModal);
          }}
        >
          <FilterOutlined />
        </Button>

        <Button
          className="beam-btn icon-btn"
          style={{ float: "right", margin: "10px 10px 10px 0" }}
          loading={projectFilterLoading || statusFilterLoading}
          onClick={() => {
            setProjectFilterLoading(true);
            searchPage();
          }}
        >
          {!projectFilterLoading && !statusFilterLoading && <RedoOutlined />}
        </Button>
      </div>
    </Row>
  );
};

export default StatusFilterBar;
