import React from "react";
import { Row, Col, Button, Form } from "antd";
import { CompassOutlined } from "@ant-design/icons";
import LocationInput from "common/LocationInput";
import { useDispatchPanel } from "../context";
import { getCurrentLocation, reverseGeocode } from "../utils";

const LocationSection: React.FC = () => {
  const {
    form,
    webBooker,
    standLocations,
    screens,
    setScreens,
    addOtherLocation,
    getRideEstimation,
    getCouponByLocation,
    locationType,
  } = useDispatchPanel();

  return (
    <React.Fragment>
      <Row className="mt-3">
        <Col span={22}>
          <Form.Item
            name="pickupLocation"
            rules={[{ required: true, message: "**Required Field" }]}
          >
            <LocationInput
              placeholder="Pick up location"
              onChange={(location: any) => {
                addOtherLocation({ pickupLocation: location });
                setScreens({
                  ...screens,
                  map: true,
                });
                const dropoffLocation = form.getFieldValue("dropoffLocation");
                if (dropoffLocation?.value?.coordinates) {
                  getRideEstimation(location, dropoffLocation);
                }
                locationType.current = "pickup";
                getCouponByLocation(location);
              }}
            />
          </Form.Item>
          {standLocations?.length > 0 && (
            <Form.Item>
              <p className="error">
                **Blocked Area. Please select nearest pickup point on the map
              </p>
            </Form.Item>
          )}
        </Col>

        <Col
          span={2}
          className="d-flex align-items-center justify-content-center"
        >
          <Button
            className="beam-btn icon-btn ml-2"
            onClick={async () => {
              const location = await getCurrentLocation();
              console.log("location", location);
              const address = await reverseGeocode(location);
              console.log("address", address);

              const pickupLocation = {
                type: "incident-location",
                label: address,
                value: {
                  description: address,
                  place_id: "",
                  coordinates: location,
                },
              };
              form.setFieldsValue({
                pickupLocation,
              });

              addOtherLocation({ pickupLocation });
              setScreens({
                ...screens,
                map: true,
              });
              const dropoffLocation = form.getFieldValue("dropoffLocation");
              if (dropoffLocation?.value?.coordinates) {
                getRideEstimation(pickupLocation, dropoffLocation);
              }
              getCouponByLocation(pickupLocation);
              locationType.current = "pickup";
            }}
          >
            <CompassOutlined />
          </Button>
        </Col>
      </Row>
      <Row className="mt-3">
        <Col span={22}>
          <Form.Item
            name="dropoffLocation"
            rules={
              webBooker
                ? [{ required: true, message: "**Required Field" }]
                : []
            }
          >
            <LocationInput
              placeholder="Drop off location"
              onChange={(location: any) => {
                addOtherLocation({ dropoffLocation: location });
                const pickupLocation = form.getFieldValue("pickupLocation");
                if (pickupLocation?.value?.coordinates) {
                  getRideEstimation(pickupLocation, location);
                }
                locationType.current = "dropoff";
              }}
            />
          </Form.Item>
        </Col>
        <Col
          span={2}
          className="d-flex align-items-center justify-content-center"
        >
          <Button
            className="beam-btn icon-btn ml-2"
            onClick={async () => {
              const location = await getCurrentLocation();
              console.log("location", location);
              const address = await reverseGeocode(location);
              console.log("address", address);

              const dropoffLocation = {
                type: "incident-location",
                label: address,
                value: {
                  description: address,
                  place_id: "",
                  coordinates: location,
                },
              };
              form.setFieldsValue({
                dropoffLocation,
              });

              addOtherLocation({ dropoffLocation });
              setScreens({
                ...screens,
                map: true,
              });
              const pickupLocation = form.getFieldValue("pickupLocation");
              if (pickupLocation?.value?.coordinates) {
                getRideEstimation(pickupLocation, dropoffLocation);
              }
              locationType.current = "dropoff";
            }}
          >
            <CompassOutlined />
          </Button>
        </Col>
      </Row>
    </React.Fragment>
  );
};

export default LocationSection;
