import React, { FC, useEffect, useRef, useState } from "react";
import { Modal, Row, Col, Button } from "antd";
import _ from "lodash";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { useDispatch } from "react-redux";
import "react-phone-number-input/style.css";
import "../Dashboard/Dashboard.scss";
import {
  refundPaymentIntentPublishTopic,
  refundPaymentIntentSubscriptionTopic,
} from "hooks/MQTTConstants";
import { pushNotification } from "utils/notifications";

import { SocketTopics } from "constants/enums";
import { wrapRequestPayload } from "../../../../helpers/request/RequestPayload";

const PaymentModal: FC<{
  socket: ISocket;
  params?: any;
  onClose?: any;
  payment?: any;
}> = ({ socket, params, onClose, payment }) => {
  const { encrypted_token } = useSelector((state: RootState) => state.auth);
  const dispatch = useDispatch();
  const [isModalVisible, setIsModalVisible] = useState<boolean>(true);
  const [loading, setLoading] = useState<boolean>(false);
  const [paymentInfo, setPaymentInfo] = useState<any>([]);
  const [paymentStatus, setPaymentStatus] = useState<any>();
  const encryptedTokenRef = useRef<any>();

  useEffect(() => {
    if (encrypted_token) {
      encryptedTokenRef.current = encrypted_token;
      const info = [];
      console.log("payment", payment);
      Object.keys(payment?.stripe || {}).map((key) => {
        if (
          typeof payment.stripe[key] === "string" ||
          typeof payment.stripe[key] === "number"
        ) {
          info.push({
            name: key,
            value: payment.stripe[key],
          });
        }
        if (key === "status") {
          setPaymentStatus(payment.stripe[key]);
        }
      });
      setPaymentInfo(info);

      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        refundPaymentIntentSubscriptionTopic(encrypted_token?.connectionId),
        ({ response }) => {
          setLoading(false);
          if (response?.status) {
            pushNotification(
              "Refund Successful",
              "success",
              "TOP_CENTER",
              3000
            );
          } else {
            pushNotification(
              response?.data?.details,
              "error",
              "TOP_CENTER",
              3000
            );
          }
        }
      );
    }
  }, [encrypted_token]);

  const handleCancel = () => {
    setIsModalVisible(false);
    onClose && onClose();
  };

  const handleOk = () => {
    setIsModalVisible(false);
    onClose && onClose();
  };

  // const refund

  return (
    <React.Fragment>
      <Modal
        title="Payment"
        visible={isModalVisible}
        onCancel={handleCancel}
        width="600px"
        // bodyStyle={{ height: 600 }}
        className="beam-modal"
        footer={[]}
        destroyOnClose={true}
      >
        <Row className="beam-modal analytics-summary-modal">
          <Col span={24}>
            <ul className="incident-information mt-2">
              {paymentInfo.map((item, i) => (
                <li key={i}>
                  <Row>
                    <Col span={12}>
                      <p>{item.name}</p>
                    </Col>
                    <Col span={12}>
                      <p>{item.value}</p>
                    </Col>
                  </Row>
                </li>
              ))}
            </ul>
          </Col>
        </Row>

        {paymentStatus === "succeeded" && (
          <Row className="action-grp mt-3">
            <Col span={12} className="px-2">
              <Button
                className="beam-btn yellow-btn bordered w-full"
                loading={loading}
                disabled={true}
                onClick={() => {
                  // const refund = window.prompt("Enter refund amount in USD?");
                  // if (!isNaN(parseInt(refund))) {
                  //   setLoading(true);
                  //   socket.publishToEvent(
                  //     SocketTopics.PublishPageTopics,
                  //     refundPaymentIntentPublishTopic(
                  //       encrypted_token?.connectionId
                  //     ),
                  //     wrapRequestPayload({
                  //       userId: encrypted_token?.userId,
                  //       pageId: payment?.pageId,
                  //       // partial: true,
                  //       refund: parseInt(refund)
                  //     })
                  //   );
                  //   console.log('refund', parseInt(refund));
                  // }
                }}
              >
                Partial Refund
              </Button>
            </Col>

            <Col span={12} className="pl-2">
              <Button
                className="beam-btn green-btn cover w-full"
                loading={loading}
                onClick={() => {
                  if (
                    window.confirm("Are you sure you want to refund amount?") ==
                    true
                  ) {
                    setLoading(true);
                    socket.publishToEvent(
                      SocketTopics.PublishPageTopics,
                      refundPaymentIntentPublishTopic(
                        encrypted_token?.connectionId
                      ),
                      wrapRequestPayload({
                        userId: encrypted_token?.userId,
                        pageId: payment?.pageId,
                        // partial: false,
                      })
                    );
                  }
                }}
              >
                Refund
              </Button>
            </Col>
          </Row>
        )}
      </Modal>
    </React.Fragment>
  );
};

export default PaymentModal;
