import React, { FC } from "react";
import { Popover, Spin, Tag } from "antd";
import {
  Assignment,
  SchedActivity,
  SchedResource,
  Violation,
} from "services/apis/aiSchedulerTypes";
import { activityPalette } from "../utils";

export const resourceNames = (
  a: Assignment,
  resourcesById: Record<string, SchedResource>
): { kind: string; names: string[] }[] =>
  Object.entries(a.resources || {}).map(([kind, ids]) => ({
    kind,
    names: (ids || []).map((id) => resourcesById[id]?.name || `Unknown ${kind}`),
  }));

const AssignmentBlock: FC<{
  assignment: Assignment;
  activity?: SchedActivity;
  resourcesById: Record<string, SchedResource>;
  violations: Violation[];
  style: React.CSSProperties;
  validating?: boolean;
  dragging?: boolean;
  pinned?: boolean;
  dimmed?: boolean;
  shaking?: boolean;
  popoverVisible?: boolean;
  onPopoverVisibleChange?: (visible: boolean) => void;
  onPointerDown?: (e: React.PointerEvent) => void;
}> = ({
  assignment,
  activity,
  resourcesById,
  violations,
  style,
  validating,
  dragging,
  pinned,
  dimmed,
  shaking,
  popoverVisible,
  onPopoverVisibleChange,
  onPointerDown,
}) => {
  const soft = violations.filter((v) => v.severity === "soft");
  const palette = activityPalette(assignment.activityId);
  const name = assignment.activityName || activity?.name || assignment.activityId;
  const resList = resourceNames(assignment, resourcesById);

  const content = (
    <div className="assignment-popover">
      <p style={{ marginBottom: 4 }}>
        <strong>{name}</strong> — meeting #{assignment.occurrence + 1}
        {pinned && " · 🔒 pinned"}
      </p>
      <p style={{ marginBottom: 4 }}>
        {assignment.day} {assignment.start}–{assignment.end}
        {assignment.location ? ` · ${assignment.location}` : ""}
      </p>
      {resList.map(({ kind, names }) => (
        <p key={kind} style={{ marginBottom: 2 }}>
          <span style={{ color: "#8c8c8c" }}>{kind}: </span>
          {names.join(", ")}
        </p>
      ))}
      {activity?.enrollment !== undefined && (
        <p style={{ marginBottom: 2 }}>
          <span style={{ color: "#8c8c8c" }}>enrollment: </span>
          {activity.enrollment}
        </p>
      )}
      {soft.length > 0 && (
        <div style={{ marginTop: 6 }}>
          {soft.map((v, i) => (
            <Tag color="orange" key={i} style={{ marginBottom: 4, whiteSpace: "normal" }}>
              {v.constraint}
              {v.detail ? `: ${v.detail}` : ""}
            </Tag>
          ))}
        </div>
      )}
      <p style={{ marginTop: 6, marginBottom: 0, color: "#8c8c8c", fontSize: 11 }}>
        {pinned
          ? "This meeting is pinned in the activity — unpin it there to move it."
          : "Drag the block to reschedule — changes are checked instantly."}
      </p>
    </div>
  );

  const classes = [
    "assignment-block",
    soft.length ? "soft" : "",
    dragging ? "dragging" : "",
    pinned ? "pinned" : "",
    dimmed ? "dim" : "",
    shaking ? "shake" : "",
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <Popover
      content={content}
      title={null}
      trigger="click"
      visible={popoverVisible}
      onVisibleChange={onPopoverVisibleChange}
    >
      <div
        className={classes}
        style={{
          ...style,
          background: palette.bg,
          borderColor: palette.border,
          color: palette.text,
        }}
        onPointerDown={onPointerDown}
      >
        <div className="assignment-block-name">
          {pinned && <span className="pin-icon">🔒</span>}
          {name}
        </div>
        <div className="assignment-block-time">
          {assignment.start}–{assignment.end}
        </div>
        {resList.length > 0 && (
          <div className="assignment-block-resources">
            {resList.map(({ names }) => names.join(", ")).join(" · ")}
          </div>
        )}
        {validating && (
          <span className="assignment-block-validating">
            <Spin size="small" />
          </span>
        )}
        {soft.length > 0 && !validating && (
          <span className="assignment-block-flag">soft</span>
        )}
      </div>
    </Popover>
  );
};

export default AssignmentBlock;
