import { useEffect } from "react";
import { SocketTopics, UserTopics } from "constants/enums";
import {
  getProjectsRequestPublishTopic,
  getProjectsSubscriptionTopic,
  getRespondersSubscriptionTopic,
  getAssetsSubscriptionTopic,
  getPageRequestPublishTopic,
  getPageSubscriptionTopic,
  getCreateRidePageSubscriptionTopic,
  getVehiclesPublishTopic,
  getRideEstimationSubscriptionTopic,
  getAggregateBdsSubscriptionTopic,
  getAccountsRequestPublishTopic,
  getAccountsSubscriptionTopic,
  getUsersSubscriptionTopic,
  callAcceptedPublishTopic,
  getCancelRidePageSubscriptionTopic,
  getFocusPageSubscriptionTopic,
  getFixedRateSubscriptionTopic,
  getBlockedAreaSubscriptionTopic,
  getApplyCouponSubscriptionTopic,
  getCouponByLocationSubscriptionTopic,
  getVehicleTypesTopic,
} from "hooks/MQTTConstants";
import {
  SET_SUBMITTED,
  ADD_GEOFENCE_LOCATION,
  ADD_STAND_LOCATION,
  DECRYPT_TOKEN,
  GET_USER_INFO,
} from "reducers/reducer";
import { pushNotification } from "utils/notifications";
import { getVehicleTypesPath } from "hooks/socketConstants";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";

// Owns every socket subscription / publish lifecycle effect for the panel:
// project + account bootstrap, ride estimation, coupons, fixed rate, blocked
// areas, page focus/cancel, token decryption and the Paystack resume flow.
export const useDispatchSubscriptions = (d: any) => {
  const { socket } = d;

  useEffect(() => {
    if (d.selectedPage) {
      console.log("selected page", d.selectedPage);
      d.setFormValuesFromPage({
        ...d.selectedPage?.page,
        persistent: {
          static: {
            profile: d.selectedPage?.page?.profile,
          },
        },
      });
      if (!d.selectedPage?.ignorePage) {
        d.setPageId(d.selectedPage?.page?.pageId?.toString());
        d.setPageStatus(
          d.selectedPage?.page?.status ||
          d.selectedPage?.page?.nonpersistent?.static?.live?.status?.name
        );
      } else {
        d.setPageId(undefined);
        d.setPageStatus(undefined);
      }
    }
  }, [d.selectedPage]);

  useEffect(() => {
    if (d.selectedPickup) {
      console.log("set pickup", d.selectedPickup);
      const pickupLocation = {
        type: "incident-location",
        label: d.selectedPickup.location.attributes?.address,
        value: {
          description: d.selectedPickup?.location.attributes?.address,
          place_id: "",
          coordinates: d.selectedPickup?.location.coordinates,
        },
      };
      d.form.setFieldsValue({
        pickupLocation,
      });

      if (pickupLocation) {
        d.addOtherLocation({ pickupLocation });
        d.setScreens({
          ...d.screens,
          map: true,
        });
        d.dispatch({ type: ADD_GEOFENCE_LOCATION, payload: undefined });
        d.dispatch({ type: ADD_STAND_LOCATION, payload: [] });
      }
    }
  }, [d.selectedPickup]);

  useEffect(() => {
    if (d.page) {
      d.setFormValuesFromPage({
        ...d.page,
        persistent: {
          static: {
            profile: d.page?.persistent?.static?.ride,
          },
        },
      });
      d.setPageId(d.page?.objectId?.toString());
      d.setPageStatus(d.page?.nonpersistent?.static?.live?.status?.name);
    }
  }, [JSON.stringify(d.page?.persistent?.static?.profile ?? {})]);

  useEffect(() => {
    if (d.submitted) {
      console.log("submitted here", d.submitted);
      d.setSearching(false);
      if (d.submitted.status) {
        pushNotification(
          "Ride request submitted",
          "success",
          "TOP_CENTER",
          1000
        );
        d.dispatch({ type: SET_SUBMITTED, payload: false });
        d.clearForm();
      } else if (d.submitted.status === false) {
        pushNotification(
          d.submitted?.data?.details || "Ride request failed",
          "error",
          "TOP_CENTER",
          3000
        );
        d.dispatch({ type: SET_SUBMITTED, payload: false });
      }
    }
  }, [
    d.dispatch,
    d.history,
    d.form,
    d.screens,
    d.search,
    d.searching,
    d.setScreens,
    d.submitted,
  ]);

  useEffect(() => {
    if (d.projects?.adminUserId) {
      console.log("test", d.projects);

      const connectionId = d.encrypted_token?.connectionId;
      const userId = d.encrypted_token?.userId;
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getAggregateBdsSubscriptionTopic(connectionId)
      );
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getUsersSubscriptionTopic(connectionId, d.projects?.userServiceId)
      );
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        callAcceptedPublishTopic(userId),
        (response: any) => {
          console.log("response", response);
          d.setIsConfirmationModalVisible(response?.data);
        }
      );
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getRideEstimationSubscriptionTopic(d.encrypted_token?.connectionId),
        (response: any) => {
          const estimation = response?.response;
          console.log("estimation", estimation?.data);
          if (estimation?.data?.leadTime > -1) {
            d.form.setFieldsValue({
              leadTime: Math.ceil(estimation?.data.leadTime),
            });
          } else {
            d.form.setFieldsValue({
              leadTime: 15,
            });
          }
          if (estimation?.data?.roundTripLeadTime > -1) {
            d.form.setFieldsValue({
              roundTripLeadTime: Math.ceil(estimation?.data.roundTripLeadTime),
            });
          }
          if (estimation?.data.estimate) {
            const estimate = [];
            estimate.push({
              label: "Estimate",
              value: `${estimation?.data.estimate} ${estimation?.data.currency}`,
            });
            estimate.push({
              label: "Distance",
              value: `${((estimation?.data.distance / 1000) * 0.6214).toFixed(
                2
              )} miles`,
            });
            estimate.push({
              label: "Duration",
              value: `${(estimation?.data.duration / 60).toFixed(2)} mins`,
            });
            estimate.push({
              label: "Wait time",
              value: `${(estimation?.data.waitTime / 60).toFixed(2)} mins`,
            });
            d.setEstimation(estimate);
            d.setEstimatedFare(estimation?.data.estimate);
            if (d.projects?.webSettings?.fixedEstimatedFare) {
              if (d.webBooker) {
                d.form.setFieldsValue({
                  fareType: {
                    type: "fareType",
                    value: "fixedEstimate",
                  },
                });
              } else {
                d.form.setFieldsValue({
                  fareType: {
                    type: "fareType",
                    value: "fixed",
                    fare: estimation?.data.estimate,
                  },
                });
              }
            } else {
              d.form.setFieldsValue({
                fareType: {
                  type: "fareType",
                  value: "variable",
                },
              });
            }
          } else {
            pushNotification("No estimation found", "error", "TOP_CENTER", 3000);
            d.setEstimatedFare(undefined);
            d.setEstimation(undefined);
            d.form.setFieldsValue({
              fareType: {
                type: "fareType",
                value: "variable",
              },
            });
          }
        }
      );

      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getApplyCouponSubscriptionTopic(d.encrypted_token?.connectionId),
        (response: any) => {
          const coupon = response?.response;
          console.log("coupon", coupon);
          d.setCouponResponse(coupon);
          if (coupon?.status === false) {
            d.form.setFieldsValue({ coupon: undefined });
          }
        }
      );

      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getCouponByLocationSubscriptionTopic(d.encrypted_token?.connectionId),
        (response: any) => {
          const coupons = response?.response;
          console.log("coupons", coupons?.data?.coupons);
          d.setCoupons(coupons?.data?.coupons);
        }
      );

      const query = new URLSearchParams(d.search);
      const reference = query.get("reference");
      if (reference) {
        const rideRequests = JSON.parse(localStorage.getItem("rideRequests"));
        if (rideRequests?.length > 0) {
          rideRequests.map((request: any) => {
            d.submitRideRequest(request, reference, 5000);
            console.log("submit ride request", request);
          });

          localStorage.removeItem("rideRequests");
          query.delete("reference");
          d.history.replace({
            search: query.toString(),
          });
        }
      }

      d.setLoaded(true);
    }
  }, [d.projects]);

  useEffect(() => {
    if (d.loaded) {
      console.log("loaded true", d.loaded);
      d.getAdminUsers();
      socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        getVehiclesPublishTopic(d.encrypted_token?.connectionId),
        wrapRequestPayload({
          userId: d.encrypted_token?.userId,
          cudbServiceId: d.projects?.userServiceId,
        })
      );

      socket.publishToServiceIdSurvey(
        SocketTopics.SurveyTopics,
        UserTopics.SearchInUser,
        d.getUserRequestPayload(d.projects?.adminUserId, "$", getVehicleTypesPath()),
        getVehicleTypesTopic(d.encrypted_token?.connectionId),
        d.projects?.userServiceId
      );
    }
  }, [d.loaded]);

  useEffect(() => {
    if (d.encrypted_token) {
      const query = new URLSearchParams(d.search);
      const token = query.get("token");
      const sessionId = query.get("setup_intent_client_secret");

      if (token && sessionId) {
        console.log("re submit here");
        const form = JSON.parse(localStorage.getItem("formValues"));
        console.log("form here", form);
        if (form) {
          d.form.setFieldsValue({
            ...form,
          });
        }
      }

      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getProjectsSubscriptionTopic(d.encrypted_token?.connectionId)
      );
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getAccountsSubscriptionTopic(d.encrypted_token?.connectionId)
      );
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getRespondersSubscriptionTopic(d.encrypted_token?.connectionId)
      );
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getAssetsSubscriptionTopic(d.encrypted_token?.connectionId)
      );
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getCreateRidePageSubscriptionTopic(d.encrypted_token?.connectionId)
      );
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getFocusPageSubscriptionTopic(d.encrypted_token?.userId),
        (response: any) => {
          d.setFormValuesFromPage({
            ...response?.page,
            persistent: {
              static: {
                profile: response?.page?.profile,
              },
            },
          });
          d.setPageId(response?.page?.pageId?.toString());
        }
      );
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getCancelRidePageSubscriptionTopic(d.encrypted_token?.connectionId),
        (response: any) => {
          pushNotification(
            "Ride cancelled successfully",
            "success",
            "TOP_CENTER",
            1000
          );
          d.dispatch({ type: SET_SUBMITTED, payload: false });
          d.clearForm();
          localStorage.removeItem("lastRideId");
        }
      );
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getPageSubscriptionTopic(d.encrypted_token?.connectionId)
      );
      socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        getProjectsRequestPublishTopic(d.encrypted_token?.connectionId),
        wrapRequestPayload({
          userId: d.encrypted_token?.userId,
          cudbServiceId:
            d.encrypted_token?.cudbServiceId || d.encrypted_token?.serviceId,
          location: d.encrypted_token?.location,
        })
      );
      socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        getAccountsRequestPublishTopic(d.encrypted_token?.connectionId),
        wrapRequestPayload({
          userId: d.encrypted_token?.userId,
          cudbServiceId:
            d.encrypted_token?.cudbServiceId || d.encrypted_token?.serviceId,
          location: d.encrypted_token?.location,
        })
      );

      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getFixedRateSubscriptionTopic(d.encrypted_token?.connectionId),
        ({ response }: any) => {
          console.log("fixed rate response", response);

          const priceList = response?.data?.fixedRate?.priceConfig;
          const numberOfPassengers = d.form.getFieldValue("numberOfPeople");

          let selectedPrice = priceList?.find((x: any) => {
            return x?.numberOfPassengers === numberOfPassengers;
          });
          if (!selectedPrice) {
            priceList?.sort(
              (a: any, b: any) => parseFloat(b.price) - parseFloat(a.price)
            );
            selectedPrice = priceList?.[0];
          }

          console.log("selected price", selectedPrice);

          if (
            selectedPrice?.price &&
            response?.data?.fixedRate?.[d.locationType.current]
          ) {
            d.form.setFieldsValue({
              fareType: {
                type: "fareType",
                value: "fixed",
                fare: selectedPrice?.price,
                ...selectedPrice,
              },
            });
          }
          d.locationTypeFare.current[d.locationType.current] = priceList;
          if (
            !d.locationTypeFare.current?.pickup &&
            !d.locationTypeFare.current?.dropoff
          ) {
            d.form.setFieldsValue({
              fareType: {
                type: "fareType",
                value: "variable",
              },
            });
          }
        }
      );

      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getBlockedAreaSubscriptionTopic(d.encrypted_token?.connectionId),
        ({ response }: any) => {
          console.log("blocked area response", response);
          if (response?.data?.blockedArea) {
            d.dispatch({
              type: ADD_GEOFENCE_LOCATION,
              payload: response?.data?.blockedArea?.geofence,
            });
            d.dispatch({
              type: ADD_STAND_LOCATION,
              payload: response?.data?.blockedArea?.pois,
            });
          } else {
            d.dispatch({ type: ADD_GEOFENCE_LOCATION, payload: undefined });
            d.dispatch({ type: ADD_STAND_LOCATION, payload: [] });
          }
        }
      );

      const lastRideId = localStorage.getItem("lastRideId");
      const tempWebBooker =
        d.encrypted_token?.cudbServiceId !== undefined ||
        d.encrypted_token?.location !== undefined;

      if (d.encrypted_token?.pageId || (lastRideId && tempWebBooker)) {
        console.log("last ride id", lastRideId);
        socket.publishToEvent(
          SocketTopics.PublishPageTopics,
          getPageRequestPublishTopic(d.encrypted_token?.connectionId),
          wrapRequestPayload(
            {
              objectId: d.encrypted_token?.pageId || lastRideId,
              paths: ["$"],
              returnPaths: ["$"],
            },
            d.encrypted_token?.pageId || lastRideId
          )
        );
      }
      d.setWebBooker(tempWebBooker);
      if (d.encrypted_token?.location) {
        localStorage.setItem("RID", d.encrypted_token?.userId);
        d.dispatch(GET_USER_INFO());
      }
    }
  }, [d.encrypted_token]);

  useEffect(() => {
    if (d.userInfo && d.encrypted_token?.location) {
      console.log("userInfo", d.userInfo);
      d.form.setFieldsValue({
        passengerName: d.userInfo?.firstName + " " + d.userInfo?.lastName,
        passengerPhoneNumber: d.userInfo?.phone,
        passengerEmail: d.userInfo?.email,
        payWith: d.userInfo?.phone?.includes("+27") ? "paystack" : "stripe",
      });

      if (d.userInfo?.phone?.includes("+27")) {
        d.setPayWith("paystack");
      } else {
        d.setPayWith("stripe");
      }
    }
  }, [d.userInfo]);

  useEffect(() => {
    if (socket.client) {
      console.log("subscribe here");
      const query = new URLSearchParams(d.search);
      const userId = query.get("userId");
      const connectionId = query.get("connectionId");
      const pageId = query.get("pageId");
      const token = query.get("token");
      const lat = query.get("lat");
      const lng = query.get("lng");
      const rawCudbServiceId = query.get("cudbServiceId");
      const cudbServiceId =
        rawCudbServiceId &&
        rawCudbServiceId !== "null" &&
        rawCudbServiceId !== "undefined" &&
        rawCudbServiceId.trim() !== "" &&
        rawCudbServiceId !== "cudb-live"
          ? rawCudbServiceId
          : undefined;
      d.setPageId(pageId);
      if (token) {
        console.log("decry");
        d.dispatch(
          DECRYPT_TOKEN({
            data: { payload: token },
            callback: (data: any) => {},
          })
        );
      } else {
        d.dispatch({
          type: "ADD_ENCRYPTED_TOKEN",
          payload: {
            connectionId,
            userId,
            pageId,
            cudbServiceId,
            location:
              lat && lng ? { coordinates: { lat, long: lng } } : undefined,
          },
        });
      }
    }
  }, [d.search, socket.client]);
};
