function* setUrlParamsAPI(action: { payload: any }) {
  try {
    const response = yield call(geDecryptPayload, { data: action.payload });
    const urlParams: any = {};
    if (response.status) {
      const { decryptedPayload } = response.data;
      const urlParamsStr = new URLSearchParams(decryptedPayload);

      const entries = urlParamsStr.entries();
      for (const entry of entries) {
        urlParams[entry[0]] = entry[1];
        console.log(`${entry[0]}: ${entry[1]}`);
      }
      yield put({ type: SET_URL_PARAMS as any, payload: urlParams });
    } else {
      pushNotification(
        "There is something wrong with the url",
        "error",
        "TOP_CENTER",
        1000
      );
    }
  } catch (error: any) {
    pushNotification(
      "There is something wrong with the url",
      "error",
      "TOP_CENTER",
      1000
    );
  }
}

function* GetMapPlacesFilterDataAPI(action) {
  try {
    const { objectType } = action.payload;
    const response = yield call(getUsersAggregateList, {
      data: action.payload,
    });
    if (response && response.data) {
      let responseData;
      if (objectType === "user") {
        responseData = response.data
          ?.filter((user) => {
            return user.email || user.phone;
          })
          ?.map((user) => {
            console.log('user', user);
            return {
              id: user.objectIds.toString(),
              name: user?.profile?.firstName + " " + user.profile?.lastName,
              extendedBio: user?.extendedBio,
              extendedBioValue: user?.extendedBioValue,
              firstName: user?.profile?.firstName ?? "",
              lastName: user?.profile?.lastName ?? "",
              gender: user?.profile?.gender ?? "",
              dob: user?.profile?.dob ?? "",
              email: user.email,
              phone: user.phone,
              beamId: `${user?.profile?.firstName?.toLowerCase()}.${user?.profile?.lastName?.toLowerCase()}`,
              objectType,
              location: user?.profile?.location?.coordinates
                ? {
                    coordinates: [
                      user?.profile?.location.coordinates.long,
                      user?.profile?.location.coordinates.lat,
                    ],
                  }
                : undefined,
            };
          });
      } else if (objectType === "asset") {
        responseData = response.data.map((place) => ({
          id: place.objectId.toString(),
          name: place?.persistent?.static?.fixedAsset?.location?.attributes?.title,
          objectType,
          location: place?.persistent?.static?.fixedAsset?.location?.coordinates
            ? {
                coordinates: [
                  place?.persistent?.static?.fixedAsset?.location.coordinates.long,
                  place?.persistent?.static?.fixedAsset?.location.coordinates.lat,
                ],
              }
            : undefined,
        }));
      }
      console.log("response", responseData);
      yield put({
        type: `ADD_MAP_${action.payload.objectType.toUpperCase()}_FILTER`,
        payload: responseData || [],
      });
    } else {
      pushNotification(response, "error", "TOP_CENTER", 1000);
    }
  } catch (error: any) {
    console.log(error);
    pushNotification(error, "error", "TOP_CENTER", 1000);
  }
}

