function* loginUserTokenAPI(action: { payload: any }) {
  console.log(action);
  const { userId, deviceUdid, password } = action.payload;
  try {
    const data = {
      userIds: [
        {
          rootUserId: userId,
        },
      ],
      deviceIds: [
        {
          udid: deviceUdid,
        },
      ],
      authTypeParams: [
        {
          typeId: 1,
          param: {
            password: password,
          },
        },
      ],
    };
    yield put({ type: SHOW_PROGRESS });
    const response = yield call(loginUser, { data });
    const [responseData] = response.data;
    if (responseData.authCode === "0") {
      if (
        responseData.authentications &&
        responseData.authentications.length > 0
      ) {
        const [authData] = responseData.authentications;
        console.log(authData);
        localStorage.setItem("TOKEN", authData.connectionId);
        localStorage.setItem("CID", authData.connectionId);
        localStorage.setItem("RID", responseData.userId);
        localStorage.setItem("NON_BEAMER_UDID", deviceUdid);
        localStorage.setItem("NON_BEAMER_USER", userId);
        localStorage.setItem("TYPE", "nonBeamer");
        pushNotification("User logged in", "success", "TOP_CENTER", 1000);
        yield put({ type: LOGIN_SUCCESS });
      } else {
        yield put({ type: HIDE_PROGRESS });
        pushNotification("User not found", "error", "TOP_CENTER", 1000);
      }
    } else if (responseData.authCode === "1") {
      // redirect user to verify pin
      yield put({
        type: "REGISTRATION_SUCCESS",
        payload: { success: true, email: action.payload.email },
      });
    } else if (responseData.authCode === "3" || responseData.authCode === "4") {
      const payload = {
        ...(action.payload.email.includes("@")
          ? {
            email: action.payload.email.trim(),
          }
          : {
            phone: action.payload.email.trim(),
          }),
        password: action.payload.password,
        reRegisteration: true,
      };
      yield call(registerUserApi, { payload });
    } else {
     yield put({ type: HIDE_PROGRESS });
      pushNotification(
        "Email or password is incorrect",
        "error",
        "TOP_CENTER",
        1000
      );
    }
  } catch (error: any) {
    console.log(error);
    yield put({ type: HIDE_PROGRESS });
    pushNotification(error, "error", "TOP_CENTER", 1000);
  }
}

function* registerUserApi(action: { payload: any }) {
  console.log(action);
  yield put({ type: SHOW_PROGRESS });
  const uuid = localStorage.getItem("UUID");
  let data = {};
  try {
    if (!action.payload.reRegisteration) {
      const verifyIdsResponse = yield call(verifyNewIdsAPIV2, action);
      if (verifyIdsResponse.status) {
        data = {
          userIds: [],
          deviceIds: [
            {
              udid: uuid,
            },
          ],
          authTypeParams: [
            {
              typeId: 2,
              param: {
                password: action.payload.password,
                useMultiOtp: true,
                verificationChannels: [
                  ...(action.payload.email && action.payload.email !== ""
                    ? [
                      {
                        email: action.payload.email.trim(),
                      },
                    ]
                    : []),
                  ...(action.payload.phoneNumber &&
                    action.payload.phoneNumber !== ""
                    ? [
                      {
                        phone: action.payload.phoneNumber.trim(),
                      },
                    ]
                    : []),
                ],
              },
            },
          ],
        };
      } else {
      yield put({ type: HIDE_PROGRESS });
        pushNotification(
          "Email or phone number already in use",
          "error",
          "TOP_CENTER",
          1000
        );
        return;
      }
    } else {
      data = {
        userIds: [
          ...(action.payload.email && action.payload.email !== ""
            ? [
              {
                email: action.payload.email.trim(),
              },
            ]
            : []),
          ...(action.payload.phoneNumber && action.payload.phoneNumber !== ""
            ? [
              {
                phone: action.payload.phoneNumber.trim(),
              },
            ]
            : []),
        ],
        deviceIds: [
          {
            udid: uuid,
          },
        ],
        authTypeParams: [
          {
            typeId: 2,
            param: {
              password: action.payload.password,
              useMultiOtp: true,
              generatePassword: false,
              verificationChannels: [
                ...(action.payload.email && action.payload.email !== ""
                  ? [
                    {
                      email: action.payload.email.trim(),
                    },
                  ]
                  : []),
                ...(action.payload.phoneNumber &&
                  action.payload.phoneNumber !== ""
                  ? [
                    {
                      phone: action.payload.phoneNumber.trim(),
                    },
                  ]
                  : []),
              ],
            },
          },
        ],
      };
    }
   yield put({ type: SHOW_PROGRESS });

   const response  = yield call(registerUser, { data });
   
    console.log(response);

    const [dataObject] = response.data;
    if (response && dataObject.authCode === "1") {
      yield put({
        type: "REGISTRATION_SUCCESS",
        payload: {
          success: true,
          email: action.payload.email || action.payload.phoneNumber,
          phone: action.payload.phoneNumber,
          payload: {
            ...action.payload,
            userId: dataObject.userId || localStorage.getItem("RID"),
          },
        },
      });
      if (dataObject.userId) {
        localStorage.setItem("RID", dataObject.userId);
      }
      pushNotification("Verification Code Sent", "success", "TOP_CENTER", 1000);
    } else {
     yield put({ type: HIDE_PROGRESS });
      pushNotification(response, "error", "TOP_CENTER", 1000);
    }
  } catch (error: any) {
    console.log(error);
    yield put({ type: HIDE_PROGRESS });
    pushNotification(error, "error", "TOP_CENTER", 1000);
  }
}

