import React, { FC, useEffect, useState } from "react";
import { Alert, Button, Checkbox, Col, Form, Row, Select, Tag, TimePicker } from "antd";
import moment from "moment";
import { putSettings } from "services/apis/collections/aiSchedulerApis";
import { getErrorMessage } from "services/apis/aiSchedulerClient";
import {
  DAY_LABELS,
  DAY_ORDER,
  OrgSettings,
  SLOT_MINUTES_OPTIONS,
} from "services/apis/aiSchedulerTypes";
import { pushNotification } from "utils/notifications";

const SettingsTab: FC<{
  orgId: string;
  settings?: OrgSettings;
  settingsMissing: boolean;
  refetchSettings: () => Promise<void>;
}> = ({ orgId, settings, settingsMissing, refetchSettings }) => {
  const [form] = Form.useForm();
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    form.setFieldsValue({
      slotMinutes: settings?.slotMinutes ?? 30,
      days: settings?.days ?? ["mon", "tue", "wed", "thu", "fri"],
      dayStart: settings?.dayStart ? moment(settings.dayStart, "HH:mm") : moment("08:00", "HH:mm"),
      dayEnd: settings?.dayEnd ? moment(settings.dayEnd, "HH:mm") : moment("18:00", "HH:mm"),
    });
  }, [settings, form]);

  const handleSave = async () => {
    try {
      const values = await form.validateFields();
      if (!values.dayEnd.isAfter(values.dayStart)) {
        pushNotification("Day end must be after day start", "error", "TOP_CENTER", 3000);
        return;
      }
      setSaving(true);
      await putSettings(orgId, {
        slotMinutes: values.slotMinutes,
        days: DAY_ORDER.filter((d) => values.days.includes(d)),
        dayStart: values.dayStart.format("HH:mm"),
        dayEnd: values.dayEnd.format("HH:mm"),
      });
      await refetchSettings();
      pushNotification("Settings saved", "success", "TOP_CENTER", 2000);
    } catch (e: any) {
      if (e?.errorFields) return;
      pushNotification(getErrorMessage(e), "error", "TOP_CENTER", 4000);
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="scheduler-tab">
      <div className="tab-intro">
        <h3>Scheduling grid</h3>
        <p>
          The slot size, days and day span define the grid every class snaps to. Set
          them once for this school — everything else builds on top.
        </p>
      </div>

      {settingsMissing && (
        <Alert
          className="mb-3"
          type="warning"
          showIcon
          message="Not configured yet"
          description="Save the grid below to unlock the timetable and solver."
        />
      )}

      {settings && (
        <div className="settings-summary mb-3">
          <Tag color="blue">{settings.slotMinutes}-minute slots</Tag>
          <Tag color="blue">
            {settings.dayStart} – {settings.dayEnd}
          </Tag>
          <Tag color="blue">{settings.days.length} days / week</Tag>
        </div>
      )}

      <div className="scheduler-card">
        <Form layout="vertical" form={form} requiredMark={false} className="auth-form">
          <Row gutter={16}>
            <Col xs={24} sm={8}>
              <Form.Item
                label="Slot size"
                name="slotMinutes"
                rules={[{ required: true, message: "Required" }]}
                tooltip="Every class start time and duration snaps to this grid."
              >
                <Select
                  options={SLOT_MINUTES_OPTIONS.map((m) => ({
                    label: `${m} minutes`,
                    value: m,
                  }))}
                />
              </Form.Item>
            </Col>
            <Col xs={12} sm={8}>
              <Form.Item
                label="Day starts"
                name="dayStart"
                rules={[{ required: true, message: "Required" }]}
              >
                <TimePicker format="HH:mm" minuteStep={5} style={{ width: "100%" }} />
              </Form.Item>
            </Col>
            <Col xs={12} sm={8}>
              <Form.Item
                label="Day ends"
                name="dayEnd"
                rules={[{ required: true, message: "Required" }]}
              >
                <TimePicker format="HH:mm" minuteStep={5} style={{ width: "100%" }} />
              </Form.Item>
            </Col>
          </Row>
          <Form.Item
            label="Scheduling days"
            name="days"
            rules={[{ required: true, message: "Pick at least one day" }]}
          >
            <Checkbox.Group
              options={DAY_ORDER.map((d) => ({ label: DAY_LABELS[d], value: d }))}
            />
          </Form.Item>
          <Button
            loading={saving}
            className="beam-btn green-btn cover"
            onClick={handleSave}
          >
            Save settings
          </Button>
        </Form>
      </div>
    </div>
  );
};

export default SettingsTab;
